const uniqueIds = new Set();
const colorKeys = ['dotColor', 'skyTop', 'skyMid', 'skyBot', 'lightTop', 'lightMid', 'lightBot'];

for (const habitat of HABITATS) {
  const validIdentity = typeof habitat.id === 'string' && /^[a-z0-9-]+$/.test(habitat.id)
    && typeof habitat.name === 'string' && habitat.name.trim()
    && typeof habitat.hint === 'string' && habitat.hint.trim();
  const validProfiles = sceneProfileIds.has(habitat.sceneProfile)
    && creatureProfileIds.has(habitat.creatureProfile)
    && interactionProfileIds.has(habitat.interactionProfile)
    && typeof habitat.weatherSky === 'boolean';
  const validPalette = colorKeys.every((key) => /^#[0-9a-f]{6}$/i.test(habitat[key] || ''))
    && Array.isArray(habitat.rgb)
    && habitat.rgb.length === 3
    && habitat.rgb.every((channel) => Number.isInteger(channel) && channel >= 0 && channel <= 255);

  if (!validIdentity || !validProfiles || !validPalette) {
    throw new Error(`Invalid habitat catalog entry: ${habitat.id || 'unknown'}`);
  }
  if (uniqueIds.has(habitat.id)) throw new Error(`Duplicate habitat id: ${habitat.id}`);
  uniqueIds.add(habitat.id);
}


// ============================================================================
// MODULE: js/scene-math.js
// ============================================================================
function calculateFrameChance(probability, frameScale, randomValue) {
  const chance = Math.max(0, Math.min(1, Number(probability) || 0));
  const scale = Math.max(0, Number(frameScale) || 0);
  const roll = Math.max(0, Math.min(1, Number(randomValue) || 0));
  return roll < 1 - Math.pow(1 - chance, scale);
}

function calculateFrameSmoothing(amount, frameScale) {
  const factor = Math.max(0, Math.min(1, Number(amount) || 0));
  const scale = Math.max(0, Number(frameScale) || 0);
  return 1 - Math.pow(1 - factor, scale);
}

const X_POSITION_KEYS = new Set(['x', 'baseX', 'targetX', 'originX', 'startX', 'endX', 'homeX', 'anchorX', 'centerX']);
const Y_POSITION_KEYS = new Set(['y', 'baseY', 'targetY', 'originY', 'startY', 'endY', 'homeY', 'anchorY', 'centerY', 'branchY']);
const Y_SIZE_KEYS = new Set(['h', 'len', 'rootLen']);

/** Scale viewport-relative positions and vertical extents in place without recreating scene entities. */
function scaleSceneCollections(collections, scaleX, scaleY) {
  const sx = Number.isFinite(scaleX) && scaleX > 0 ? scaleX : 1;
  const sy = Number.isFinite(scaleY) && scaleY > 0 ? scaleY : 1;
  for (const collection of collections) {
    if (!Array.isArray(collection)) continue;
    for (const entity of collection) {
      if (!entity || typeof entity !== 'object') continue;
      for (const [key, value] of Object.entries(entity)) {
        if (typeof value !== 'number' || !Number.isFinite(value)) continue;
        if (X_POSITION_KEYS.has(key)) entity[key] = value * sx;
        else if (Y_POSITION_KEYS.has(key)) entity[key] = value * sy;
        else if (Y_SIZE_KEYS.has(key)) entity[key] = value * sy;
      }
    }
  }
}




