        const PIXEL_SCALE = 3; // Crisp 3x3 pixel art resolution
        const BASE_FRAME_MS = 1000 / 60;
        const MAX_FRAME_DELTA_MS = 140; // Prevent large jumps after a slow frame or wake-up.
        const REDUCED_MOTION_QUERY = window.matchMedia('(prefers-reduced-motion: reduce)');
        let prefersReducedMotion = REDUCED_MOTION_QUERY.matches;
        let frameScale = 1; // 1.0 equals one original 60 Hz simulation frame.
        let pw = 420;
        let ph = 240;

        function frameChance(probability) {
            return calculateFrameChance(probability, frameScale, Math.random());
        }

        function frameSmoothing(amount) {
            return calculateFrameSmoothing(amount, frameScale);
        }

        let lastFillStyle = '';

        function resetFillStyleCache() {
            lastFillStyle = '';
        }

        function setSceneFill(color) {
            if (color !== lastFillStyle) {
                ctx.fillStyle = color;
                lastFillStyle = color;
            }
        }

        let cachedDetailTier = [1, 2, 3].includes(Number(window.__weDetailTier)) ? Number(window.__weDetailTier) : 1;

        function resizePixelCanvas(forceRebuild = false) {
            const previousWidth = pw;
            const previousHeight = ph;
            const taskbarPx = Math.max(0, Math.min(140, Number(window.__weTaskbarHeightPx ?? 48)));
            const visibleWinH = Math.max(240, window.innerHeight - taskbarPx);
            const rScale = [1, 2, 3].includes(Number(window.__weDetailTier)) ? Number(window.__weDetailTier) : 1;
            cachedDetailTier = rScale;
            const nextWidth = Math.max(1, Math.ceil(window.innerWidth / PIXEL_SCALE));
            const nextHeight = Math.max(80, Math.ceil(visibleWinH / PIXEL_SCALE));
            const targetCanvasW = nextWidth * rScale;
            const targetCanvasH = nextHeight * rScale;
            if (!forceRebuild && nextWidth === previousWidth && nextHeight === previousHeight && canvas.width === targetCanvasW && canvas.height === targetCanvasH) return;

            pw = nextWidth;
            ph = nextHeight;
            canvas.width = targetCanvasW;
            canvas.height = targetCanvasH;
            lastFillStyle = '';
            ctx.setTransform(rScale, 0, 0, rScale, 0, 0);
            ctx.imageSmoothingEnabled = false;
            invalidateBackgroundCache();

            if (previousWidth > 0 && previousHeight > 0) {
                if (creatures.length + stimuli.length + ambientParticles.length + shootingStars.length > 0) {
                    scaleSceneCollections(
                        [creatures, stimuli, ambientParticles, shootingStars],
                        pw / previousWidth,
                        ph / previousHeight,
                    );
                }
                if (typeof populateHabitatFlora === 'function' && HABITATS[currentHabitatIdx]) {
                    flora.length = 0;
                    populateHabitatFlora(HABITATS[currentHabitatIdx]);
                }
            }
        }
        window.addEventListener('resize', resizePixelCanvas, { passive: true });

        function pRect(x, y, w, h, color) {
            if (cachedDetailTier <= 1) {
                if (color !== lastFillStyle) {
                    ctx.fillStyle = color;
                    lastFillStyle = color;
                }
                ctx.fillRect(Math.round(x), Math.round(y), Math.round(w), Math.round(h));
                return;
            }
            const tier = cachedDetailTier;
            const rx = Math.round(x * tier) / tier;
            const ry = Math.round(y * tier) / tier;
            const rw = Math.max(1 / tier, Math.round(w * tier) / tier);
            const rh = Math.max(1 / tier, Math.round(h * tier) / tier);
            if (color !== lastFillStyle) {
                ctx.fillStyle = color;
                lastFillStyle = color;
            }
            ctx.fillRect(rx, ry, rw, rh);
            if (rw >= 5 && rh >= 3 && typeof color === 'string' && color.charCodeAt(0) === 35) {
                const step = 1 / tier;
                ctx.fillStyle = tier === 3 ? 'rgba(255, 255, 255, 0.11)' : 'rgba(255, 255, 255, 0.07)';
                ctx.fillRect(rx, ry, rw, step);
                const shCol = 'rgba(0, 0, 0, 0.12)';
                ctx.fillStyle = shCol;
                ctx.fillRect(rx, ry + rh - step, rw, step);
                lastFillStyle = shCol;
            }
        }

        function lerpHex(c1, c2, t) {
            const r1 = parseInt(c1.slice(1, 3), 16), g1 = parseInt(c1.slice(3, 5), 16), b1 = parseInt(c1.slice(5, 7), 16);
            const r2 = parseInt(c2.slice(1, 3), 16), g2 = parseInt(c2.slice(3, 5), 16), b2 = parseInt(c2.slice(5, 7), 16);
            const r = Math.round(r1 + (r2 - r1) * t);
            const g = Math.round(g1 + (g2 - g1) * t);
            const b = Math.round(b1 + (b2 - b1) * t);
            return `rgb(${r},${g},${b})`;
        }

        // ============================================================================
        // BÖLÜM SONU: CANVAS VE ÇİZİM YARDIMCILARI
