// MODULE: js/habitat-ambient-wildlife.js
// ============================================================================




/* HABITAT AMBIENT WILDLIFE — hero-scale, widget-safe, click-reactive pixel-art
   hosts for every biome with natural resting/action rhythms, roaming Loch Ness,
   relocated Axolotl, sculpted coral-crimson Reef Octopus, and toggleable Arctic
   Christmas Wonderland. */

// ============================================================================
// BÖLÜM BAŞI: ETKİLEŞİMLİ HİTBOX VE TEPKİ YÖNETİMİ
// ============================================================================

let activeAmbientSceneProfile = null;
const ambientHitboxes = [];
const ambientReactions = new Map();
const ambientTouchPulses = [];

const AMBIENT_REACTION_DURATIONS = Object.freeze({
    meadow_bear: 3600,
    betta_axolotl: 4400,
    betta_snail: 3200,
    wetland_heron: 3200,
    wetland_turtle: 3200,
    botanical_cat: 4500,
    botanical_robin: 2800,
    reef_octopus: 4200,
    reef_anemone: 3400,
    koi_loch_ness: 3800,
    koi_terrapin: 3600,
    rainforest_toucan: 2800,
    rainforest_sloth: 3400,
    rainforest_frog: 2600,
    rainforest_morpho: 3400,
    arctic_bear: 3200,
    arctic_hare: 2800,
    arctic_snowman: 2600,
    arctic_elf_1: 2600,
    arctic_elf_2: 2600,
    arctic_elf_3: 2600,
    arctic_santa: 2400
});

const nessRoam = {
    initialized: false,
    x: 0,
    y: 0,
    vx: 0.018,
    vy: 0.004,
    dir: 1,
    wpIdx: 1,
    loopDir: 1,
    lastTime: 0,
    targetX: 0,
    targetY: 0
};

const clampVal = (v, lo, hi) => Math.max(lo, Math.min(hi, v));
const easeOutQuad = (t) => 1 - (1 - t) * (1 - t);
const easeInOutQuad = (t) => (t < 0.5 ? 2 * t * t : 1 - Math.pow(-2 * t + 2, 2) / 2);

function beginAmbientWildlifeFrame(sceneProfile, _time) {
    if (sceneProfile !== activeAmbientSceneProfile) {
        activeAmbientSceneProfile = sceneProfile;
        ambientReactions.clear();
        ambientTouchPulses.length = 0;
        nessRoam.initialized = false;
        nessRoam.wpIdx = 1;
        nessRoam.loopDir = 1;
        nessRoam.lastTime = 0;
    }
    ambientHitboxes.length = 0;
}

function registerAmbientHitbox(id, x1, y1, x2, y2, priority = 0) {
    const pad = 6;
    ambientHitboxes.push({
        id,
        x1: Math.min(x1, x2) - pad,
        y1: Math.min(y1, y2) - pad,
        x2: Math.max(x1, x2) + pad,
        y2: Math.max(y1, y2) + pad,
        priority
    });
}

function getAmbientReaction(id, time) {
    const entry = ambientReactions.get(id);
    if (!entry) return null;
    if (entry.startTime === null) {
        entry.startTime = time;
    }
    const elapsed = time - entry.startTime;
    if (elapsed < 0 || elapsed >= entry.duration) {
        ambientReactions.delete(id);
        return null;
    }
    return {
        id,
        progress: elapsed / entry.duration,
        elapsed,
        duration: entry.duration,
        clickX: entry.clickX,
        clickY: entry.clickY,
        seed: entry.seed
    };
}

function hasAmbientWildlifeAt(sceneProfile, px, py) {
    if (sceneProfile !== activeAmbientSceneProfile) return false;
    for (let i = 0; i < ambientHitboxes.length; i++) {
        const b = ambientHitboxes[i];
        if (px >= b.x1 && px <= b.x2 && py >= b.y1 && py <= b.y2) {
            return true;
        }
    }
    return false;
}

function tryInteractAmbientWildlife(sceneProfile, px, py) {
    if (sceneProfile !== activeAmbientSceneProfile) return false;
    let best = null;
    for (let i = 0; i < ambientHitboxes.length; i++) {
        const b = ambientHitboxes[i];
        if (px >= b.x1 && px <= b.x2 && py >= b.y1 && py <= b.y2) {
            if (!best || b.priority >= best.priority) {
                best = b;
            }
        }
    }
    if (!best) return false;
    ambientReactions.set(best.id, {
        startTime: null,
        duration: AMBIENT_REACTION_DURATIONS[best.id] || 3200,
        clickX: px,
        clickY: py,
        seed: Math.random()
    });
    if (ambientTouchPulses.length >= 6) ambientTouchPulses.shift();
    ambientTouchPulses.push({
        x: Math.round(px),
        y: Math.round(py),
        startTime: null,
        duration: 520
    });
    return true;
}

function drawAmbientTouchPulses(time) {
    for (let i = ambientTouchPulses.length - 1; i >= 0; i--) {
        const pulse = ambientTouchPulses[i];
        if (pulse.startTime === null) pulse.startTime = time;
        const elapsed = time - pulse.startTime;
        if (elapsed < 0 || elapsed >= pulse.duration) {
            ambientTouchPulses.splice(i, 1);
            continue;
        }
        const t = easeOutQuad(elapsed / pulse.duration);
        const r = Math.max(2, Math.round(t * 14));
        const alpha = ((1 - elapsed / pulse.duration) * 0.92).toFixed(2);
        const ringCol = `rgba(253, 224, 71, ${alpha})`;
        const sparkCol = `rgba(255, 255, 255, ${alpha})`;
        pRect(pulse.x - Math.floor(r * 0.5), pulse.y - r, r, 1, ringCol);
        pRect(pulse.x - Math.floor(r * 0.5), pulse.y + r, r, 1, ringCol);
        pRect(pulse.x - r, pulse.y - Math.floor(r * 0.5), 1, r, ringCol);
        pRect(pulse.x + r, pulse.y - Math.floor(r * 0.5), 1, r, ringCol);
        const d = Math.round(r * 0.72);
        pRect(pulse.x - d, pulse.y - d, 2, 2, sparkCol);
        pRect(pulse.x + d - 1, pulse.y - d, 2, 2, sparkCol);
        pRect(pulse.x - d, pulse.y + d - 1, 2, 2, sparkCol);
        pRect(pulse.x + d - 1, pulse.y + d - 1, 2, 2, sparkCol);
    }
}

function getLeftSafeX(pct) {
    return Math.max(Math.round(pw * pct), 146);
}

function getRightSafeX(pct) {
    return Math.min(Math.round(pw * pct), pw - 142);
}

// ============================================================================
// BÖLÜM SONU: ETKİLEŞİMLİ HİTBOX VE TEPKİ YÖNETİMİ
// BÖLÜM BAŞI: BİYOMLARIN EV SAHİBİ DURGUN VE ROAMING CANLILARI
// ============================================================================

function drawMeadowHoneyBear(time) {
    // Sol meyve ağaçlarının yanında, Music Widget'tan ve orta akıştan tamamen uzakta (~38px boy x 36px en)
    const bearX = getLeftSafeX(0.27);
    const groundY = getGroundY(bearX, 'meadow', pw, ph) + 1;
    const potX = bearX + 12;
    const potY = groundY;

    const react = getAmbientReaction('meadow_bear', time);
    let standLift = 0;
    let swipeAmt = 0;
    let isAngry = false;

    if (react) {
        const p = react.progress;
        isAngry = true;
        if (p < 0.16) {
            standLift = Math.round(easeOutQuad(p / 0.16) * 11);
        } else if (p < 0.78) {
            standLift = 11;
        } else {
            standLift = Math.round((1 - easeInOutQuad((p - 0.78) / 0.22)) * 11);
        }
        const sw1 = p >= 0.16 && p < 0.35 ? (p - 0.16) / 0.19 : -1;
        const sw2 = p >= 0.35 && p < 0.54 ? (p - 0.35) / 0.19 : -1;
        swipeAmt = sw1 >= 0 ? Math.sin(sw1 * Math.PI) : (sw2 >= 0 ? Math.sin(sw2 * Math.PI) : 0);
    }

    // 18 saniyelik sakin, doğal ritim (~%56 dingin dinlenme & nefes, ardından yavaş bal alma & keyifli tadım)
    const phase = (time % 18000) / 18000;
    const breath = isAngry
        ? (Math.sin(time * 0.016) > 0 ? -1 : 0)
        : (Math.sin(time * 0.0020) > 0.35 ? -1 : 0);
    const blink = !isAngry && (time % 5400) > 5220;
    const earTwitch = !isAngry && (time % 7900) > 7640 ? -1 : 0;

    let pawLift = 0;
    let mouthOpen = false;
    let happyEyes = false;
    if (!isAngry) {
        if (phase >= 0.56 && phase < 0.64) {
            pawLift = -1;
        } else if (phase >= 0.64 && phase < 0.72) {
            const t = (phase - 0.64) / 0.08;
            pawLift = Math.round(t * 10);
            mouthOpen = t > 0.6;
        } else if (phase >= 0.72 && phase < 0.88) {
            const slowChew = Math.sin(((phase - 0.72) / 0.16) * Math.PI * 3);
            pawLift = slowChew > 0 ? 10 : 8;
            mouthOpen = slowChew < 0.15;
            happyEyes = true;
        } else if (phase >= 0.88) {
            const t = (phase - 0.88) / 0.12;
            pawLift = Math.round((1 - t) * 10);
        }
    }

    const furDeep = '#2d1407';
    const furDark = '#4a2511';
    const furMid = '#733c1b';
    const furHi = '#9a5a2c';
    const tan = '#d6a676';
    const cream = '#ebd0ad';

    pRect(bearX - 16, groundY, 39, 3, 'rgba(2, 10, 14, 0.36)');
    pRect(bearX - 14, groundY + 2, 35, 2, 'rgba(2, 10, 14, 0.22)');

    pRect(bearX - 14, groundY - 7 - Math.round(standLift * 0.35), 4, 4, furDark);
    pRect(bearX - 15, groundY - 6 - Math.round(standLift * 0.35), 2, 2, furDeep);

    // Gövde (balını korurken şaha kalkıp uzar!)
    pRect(bearX - 12 - (isAngry ? 1 : 0), groundY - 21 - standLift + breath, 22 + (isAngry ? 2 : 0), 20 + Math.round(standLift * 0.7), furMid);
    pRect(bearX - 12, groundY - 19 - standLift + breath, 5, 18 + Math.round(standLift * 0.6), furDark);
    pRect(bearX - 11, groundY - 17 - standLift + breath, 2, 14, furDeep);
    pRect(bearX - 8, groundY - 22 - standLift + breath, 12, 5, furHi);
    pRect(bearX + 4, groundY - 19 - standLift + breath, 5, 16, furDark);

    pRect(bearX - 4, groundY - 18 - standLift + breath, 11, 15 + Math.round(standLift * 0.5), tan);
    pRect(bearX - 2, groundY - 16 - standLift + breath, 7, 12 + Math.round(standLift * 0.4), cream);

    // Güçlü arka/alt ayaklar
    const stanceSpread = isAngry ? 2 : 0;
    pRect(bearX - 11 - stanceSpread, groundY - 6, 9, 6, furDark);
    pRect(bearX - 10 - stanceSpread, groundY - 5, 7, 4, furMid);
    pRect(bearX - 8 - stanceSpread, groundY - 4, 4, 3, tan);
    pRect(bearX + 2 + Math.round(stanceSpread * 0.5), groundY - 6, 8, 6, furDark);
    pRect(bearX + 3 + Math.round(stanceSpread * 0.5), groundY - 5, 6, 4, furMid);
    pRect(bearX + 5 + Math.round(stanceSpread * 0.5), groundY - 4, 4, 3, cream);

    // Sol kol (öfkelenince küpü kucaklayıp korur)
    if (isAngry) {
        pRect(bearX - 10, groundY - 17 - standLift + breath, 6, 5, furDark);
        pRect(bearX - 4, groundY - 14 - Math.round(standLift * 0.4), 10, 4, furMid);
        pRect(bearX + 4, groundY - 13 - Math.round(standLift * 0.4), 4, 3, cream);
    } else {
        pRect(bearX - 10, groundY - 15 + breath, 5, 7, furDark);
        pRect(bearX - 9, groundY - 13 + breath, 6, 4, furMid);
        pRect(bearX - 5, groundY - 11 + breath, 5, 3, tan);
    }

    // Baş, kulaklar & yüz ifadesi
    const hy = groundY - 35 - standLift + breath;
    pRect(bearX - 9, hy - 3 + earTwitch, 5, 5, furDark);
    pRect(bearX - 8, hy - 2 + earTwitch, 3, 3, furMid);
    pRect(bearX - 7, hy - 1 + earTwitch, 2, 2, tan);
    pRect(bearX + 4, hy - 3, 5, 5, furDark);
    pRect(bearX + 5, hy - 2, 3, 3, furMid);
    pRect(bearX + 5, hy - 1, 2, 2, tan);

    pRect(bearX - 8, hy - 1, 16, 14, furMid);
    pRect(bearX - 9, hy + 2, 18, 10, furMid);
    pRect(bearX - 9, hy + 2, 3, 10, furDark);
    pRect(bearX - 6, hy - 2, 12, 3, furHi);
    pRect(bearX - 3, hy + 5, 11, 8, tan);
    pRect(bearX - 2, hy + 6, 10, 6, cream);
    pRect(bearX + 4, hy + 6, 5, 3, cream);
    pRect(bearX + 6, hy + 6, 3, 2, '#09090b');
    pRect(bearX + 7, hy + 6, 1, 1, '#52525b');

    if (isAngry) {
        // Çatık öfkeli kaşlar + parlayan gözler + diş gösteren kükreme + kırmızı öfke işareti
        pRect(bearX - 5, hy + 1, 3, 1, furDeep);
        pRect(bearX - 3, hy + 2, 2, 1, furDeep);
        pRect(bearX + 4, hy + 1, 3, 1, furDeep);
        pRect(bearX + 2, hy + 2, 2, 1, furDeep);
        pRect(bearX - 4, hy + 3, 2, 2, '#09090b');
        pRect(bearX + 3, hy + 3, 2, 2, '#09090b');
        pRect(bearX - 3, hy + 3, 1, 1, '#ef4444');
        pRect(bearX + 4, hy + 3, 1, 1, '#ef4444');
        // Kükreyen ağız & sivri beyaz dişler
        pRect(bearX + 1, hy + 9, 6, 4, '#7f1d1d');
        pRect(bearX + 2, hy + 10, 4, 2, '#991b1b');
        pRect(bearX + 2, hy + 9, 1, 1, '#ffffff');
        pRect(bearX + 5, hy + 9, 1, 1, '#ffffff');
        pRect(bearX + 3, hy + 12, 1, 1, '#ffffff');
        // Öfke işareti (#ef4444 & #fde047)
        const pulse = Math.sin(time * 0.02) > 0;
        const ax = bearX - 11;
        const ay = hy - 7;
        pRect(ax, ay, 4, 1, pulse ? '#ef4444' : '#f97316');
        pRect(ax + 1, ay - 2, 1, 4, pulse ? '#ef4444' : '#f97316');
        pRect(ax + 4, ay - 1, 2, 2, '#fde047');
    } else if (happyEyes) {
        pRect(bearX - 4, hy + 4, 3, 1, furDeep);
        pRect(bearX + 2, hy + 4, 3, 1, furDeep);
        pRect(bearX - 5, hy + 7, 2, 1, '#fb7185');
        pRect(bearX + 2, hy + 7, 2, 1, '#fb7185');
    } else if (blink) {
        pRect(bearX - 4, hy + 4, 2, 1, furDark);
        pRect(bearX + 3, hy + 4, 2, 1, furDark);
    } else {
        pRect(bearX - 4, hy + 3, 2, 2, '#09090b');
        pRect(bearX + 3, hy + 3, 2, 2, '#09090b');
        pRect(bearX - 4, hy + 3, 1, 1, '#ffffff');
        pRect(bearX + 3, hy + 3, 1, 1, '#ffffff');
    }
    if (!isAngry && mouthOpen) {
        pRect(bearX + 2, hy + 10, 4, 2, '#7f1d1d');
        pRect(bearX + 3, hy + 11, 2, 1, '#fb7185');
    }

    // Bal küpü
    const potTilt = swipeAmt > 0.4 ? -1 : 0;
    pRect(potX - 6, potY - 10 + potTilt, 13, 10, '#78350f');
    pRect(potX - 5, potY - 9 + potTilt, 10, 8, '#b45309');
    pRect(potX - 3, potY - 8 + potTilt, 5, 5, '#d97706');
    pRect(potX - 7, potY - 12 + potTilt, 15, 3, '#92400e');
    pRect(potX - 6, potY - 12 + potTilt, 13, 2, '#d97706');
    pRect(potX - 5, potY - 13 + potTilt, 11, 2, '#f59e0b');
    pRect(potX - 4, potY - 13 + potTilt, 8, 1, '#fde047');
    pRect(potX + 2, potY - 10 + potTilt, 3, 4, '#f59e0b');
    pRect(potX + 3, potY - 9 + potTilt, 1, 2, '#fde047');
    pRect(potX - 2, potY - 10 + potTilt, 2, 2, '#f59e0b');

    if (isAngry) {
        // Sağ kol yukarı kalkar ve bal küpü önünde keskin pençe savurur!
        const sw = Math.round(swipeAmt * 11);
        const armX = bearX + 4 + sw;
        const armY = potY - 22 - standLift + Math.round(swipeAmt * 9);
        pRect(armX - 2, armY, 7, 5, furDark);
        pRect(armX, armY + 1, 6, 4, furMid);
        pRect(armX + 5, armY, 2, 1, '#ffffff');
        pRect(armX + 6, armY + 2, 2, 1, '#ffffff');
        pRect(armX + 5, armY + 4, 2, 1, '#ffffff');
        if (swipeAmt > 0.25) {
            for (let sl = 0; sl < 3; sl++) {
                const sx = potX + 3 + sl * 2;
                const sy = potY - 25 + sl * 4;
                pRect(sx, sy, 9, 1, '#ffffff');
                pRect(sx + 2, sy + 1, 7, 1, '#fde047');
                pRect(sx + 4, sy + 2, 4, 1, '#f97316');
            }
            const dropY = Math.round(swipeAmt * 11);
            pRect(potX + 8, potY - 16 - dropY, 2, 2, '#fde047');
            pRect(potX + 12, potY - 13 - Math.round(dropY * 0.7), 1, 2, '#f59e0b');
        }
    } else {
        const armX = bearX + 4 + (pawLift > 5 ? 1 : 3);
        const armY = potY - 13 - pawLift;
        pRect(armX - 1, armY + 1, 5, 6, furDark);
        pRect(armX, armY + 1, 4, 5, furMid);
        pRect(armX, armY, 4, 3, '#f59e0b');
        pRect(armX + 1, armY, 2, 2, '#fde047');
        if (pawLift > 2) {
            const dripStep = Math.floor((time * 0.008) % 4);
            pRect(armX + 2, armY + 3 + dripStep, 1, 2, '#fde047');
        }
    }

    registerAmbientHitbox('meadow_bear', bearX - 18, groundY - 46 - standLift, potX + 12, groundY + 4, 3);
}

function drawBettaTankCritters(time) {
    const soilY = (x) => {
        const nx = x / Math.max(1, pw);
        const mound = Math.pow(Math.abs(nx - 0.50) * 1.95, 1.45) * 18;
        return Math.round(ph - 4 - mound - Math.sin(x * 0.04) * 2);
    };

    // 1. Yeniden Konumlandırılmış Pembe Aksolotl (~42x20px): Sağ-orta açık koydaki kum yatağında sola bakar, tıklayınca suda yüzüp döner!
    const homeX = getRightSafeX(0.69);
    const homeY = Math.min(ph - 20, soilY(homeX) - 6);

    // Aksolotl için özel açık renkli yumuşak dere kumu & çakıl yatağı
    pRect(homeX - 18, homeY + 3, 36, 4, isLightMode ? '#cbd5e1' : '#334155');
    pRect(homeX - 15, homeY + 2, 30, 2, isLightMode ? '#e2e8f0' : '#475569');
    pRect(homeX + 13, homeY + 1, 5, 3, isLightMode ? '#94a3b8' : '#1e293b');

    const axoReact = getAmbientReaction('betta_axolotl', time);
    const loopX = (t) => -Math.sin(t * Math.PI) * 58 + Math.sin(t * Math.PI * 2) * 14;
    const loopY = (t) => -Math.sin(t * Math.PI) * 44 - Math.sin(t * Math.PI * 2) * 8;

    let curX = homeX;
    let curY = homeY;
    let facingDir = -1;
    let isSwimming = false;
    let swimKick = 0;

    if (axoReact) {
        const p = axoReact.progress;
        if (p < 0.12) {
            curY = Math.round(homeY - easeOutQuad(p / 0.12) * 4);
            isSwimming = true;
            for (let b = 0; b < 4; b++) {
                pRect(homeX - 10 + b * 5, Math.round(homeY - 12 - b * 4 - (p / 0.12) * 10), 2, 2, 'rgba(224, 242, 254, 0.78)');
            }
        } else if (p < 0.84) {
            const u = (p - 0.12) / 0.72;
            const ox = loopX(u);
            const oy = loopY(u);
            const prevU = Math.max(0, u - 0.02);
            const dxVel = ox - loopX(prevU);
            curX = clampVal(Math.round(homeX + ox), 146, pw - 142);
            curY = clampVal(Math.round(homeY + oy), 34, homeY + 2);
            facingDir = Math.abs(dxVel) > 0.15 ? (dxVel >= 0 ? 1 : -1) : -1;
            isSwimming = true;
            swimKick = Math.round(Math.sin(u * Math.PI * 14) * 2.4);
            for (let b = 0; b < 4; b++) {
                const trailU = Math.max(0, u - b * 0.035);
                const bx = clampVal(Math.round(homeX + loopX(trailU) - facingDir * 12), 142, pw - 138);
                const by = clampVal(Math.round(homeY + loopY(trailU) - b * 3 - 4), 28, ph - 12);
                pRect(bx, by, b % 2 === 0 ? 2 : 1, 2, 'rgba(224, 242, 254, 0.65)');
            }
        } else {
            const landT = (p - 0.84) / 0.16;
            curY = Math.round(homeY - (1 - easeOutQuad(landT)) * 2);
            facingDir = -1;
        }
    }

    const phase = (time % 16000) / 16000;
    const breath = isSwimming ? Math.round(Math.sin(time * 0.014) * 0.8) : (Math.sin(time * 0.0022) > 0.3 ? -1 : 0);
    const gillFlick = isSwimming ? (Math.sin(time * 0.02) > 0 ? -1 : 0) : ((phase > 0.35 && phase < 0.42) || (phase > 0.78 && phase < 0.85) ? -1 : 0);
    const yawnWindow = !isSwimming && phase > 0.56 && phase < 0.66;
    const tailSway = isSwimming ? swimKick : Math.round(Math.sin(time * 0.0024) * 1.5);

    const pinkDeep = '#be185d';
    const pinkMid = '#f472b6';
    const pinkLight = '#f9a8d4';
    const pinkHi = '#fbcfe8';
    const gillBase = '#e11d48';
    const gillTip = '#fb7185';

    const axRect = (ox, oy, w, h, col) => pRect(facingDir >= 0 ? curX + ox : curX - ox - w, curY + oy, w, h, col);

    if (!isSwimming) {
        pRect(curX - 20, curY + 2, 38, 3, 'rgba(2, 8, 16, 0.36)');
    }

    // Uzun yüzgeçli kuyruk
    axRect(-23, -5 + tailSway, 9, 6, 'rgba(249, 168, 212, 0.58)');
    axRect(-19, -4 + tailSway, 7, 4, pinkMid);
    axRect(-15, -3 + Math.round(tailSway * 0.5), 7, 4, pinkLight);

    // Tombul gövde & bacaklar
    axRect(-10, -5 + breath, 19, 8, pinkLight);
    axRect(-9, -6 + breath, 16, 2, pinkHi);
    axRect(-8, 1, 15, 2, pinkMid);
    const legOff = isSwimming ? 2 : 0;
    axRect(-8 - legOff, 2, 3, 3, pinkMid);
    axRect(-9 - legOff, 4, 4, 1, pinkHi);
    axRect(4 - legOff, 2, 3, 3, pinkMid);
    axRect(4 - legOff, 4, 4, 1, pinkHi);

    // Tüylü pembe-kızıl solungaç dalları
    [-1, 0, 1].forEach((row, idx) => {
        const gY = -9 + row * 3 + breath + gillFlick;
        axRect(2, gY, 6 + (idx === 1 ? 1 : 0), 2, gillBase);
        axRect(1 - idx, gY - 1, 3, 2, gillTip);
        axRect(0 - idx, gY - 1, 1, 1, '#fda4af');
        axRect(11, gY, 4, 2, gillBase);
        axRect(14, gY - 1, 2, 2, gillTip);
    });

    // Geniş baş, parlak siyah gözler & gülümseyen ağız
    axRect(5, -10 + breath, 12, 10, pinkLight);
    axRect(6, -11 + breath, 10, 2, pinkHi);
    axRect(6, -2 + breath, 10, 2, pinkMid);
    axRect(9, -7 + breath, 2, 2, '#0f172a');
    axRect(14, -7 + breath, 2, 2, '#0f172a');
    axRect(9, -7 + breath, 1, 1, '#ffffff');
    axRect(14, -7 + breath, 1, 1, '#ffffff');
    if (yawnWindow) {
        axRect(10, -4 + breath, 4, 2, pinkDeep);
        for (let b = 0; b < 3; b++) {
            const bprog = ((phase - 0.56) / 0.10 + b * 0.28) % 1;
            const bx = facingDir >= 0 ? curX + 12 + b : curX - 13 - b;
            pRect(bx, Math.round(curY - 8 - bprog * 14), 2, 2, 'rgba(224, 242, 254, 0.72)');
        }
    } else {
        axRect(10, -4 + breath, 4, 1, pinkDeep);
    }

    registerAmbientHitbox('betta_axolotl', curX - 24, curY - 15, curX + 24, curY + 10, 3);

    // 2. Büyütülmüş Altın Elma Salyangozu (~24x19px — kütük kemeri üzerine tam oturur, tıklayınca kabuğuna çekilir!)
    const maxTrunkX = Math.min(190, Math.floor(pw * 0.46));
    const snX = Math.min(Math.round(maxTrunkX * 0.57), Math.round(pw * 0.17));
    const tArch = snX / Math.max(1, maxTrunkX);
    const snY = Math.round(ph - 18 - Math.sin(tArch * Math.PI * 0.88) * 54 + Math.cos(tArch * 4) * 3) + 1;

    const snailReact = getAmbientReaction('betta_snail', time);
    let snailTucked = false;
    let shellRock = 0;
    let peekAmt = 1;
    if (snailReact) {
        const sp = snailReact.progress;
        shellRock = sp < 0.22 ? Math.round(Math.sin(sp * Math.PI * 10) * 1.4) : 0;
        if (sp >= 0.08 && sp < 0.68) {
            snailTucked = true;
            peekAmt = 0;
        } else if (sp >= 0.68) {
            peekAmt = easeOutQuad((sp - 0.68) / 0.32);
        }
        if (sp < 0.28) {
            pRect(snX + 8, Math.round(snY - 14 - sp * 45), 2, 2, 'rgba(224, 242, 254, 0.75)');
            pRect(snX + 5, Math.round(snY - 17 - sp * 35), 1, 1, 'rgba(224, 242, 254, 0.65)');
        }
    }

    const stalkWave = Math.round(Math.sin(time * 0.0022) * 0.9);
    // Ağaç üzerinde yumuşak temas gölgesi & krem gövde tabanı
    pRect(snX - 10, snY - 1, 20, 2, 'rgba(2, 8, 16, 0.38)');
    pRect(snX - 9, snY - 4, 17, 4, '#fef3c7');
    pRect(snX - 8, snY - 5, 14, 2, '#fde68a');

    // Büyük Altın Spiral Kabuk (~17x15px)
    const sx = snX - 1 + shellRock;
    pRect(sx - 9, snY - 12, 16, 9, '#78350f');
    pRect(sx - 8, snY - 15, 14, 11, '#b45309');
    pRect(sx - 7, snY - 17, 12, 11, '#d97706');
    pRect(sx - 5, snY - 16, 9, 8, '#f59e0b');
    pRect(sx - 3, snY - 15, 6, 5, '#fde047');
    pRect(sx - 2, snY - 14, 3, 2, '#ffffff');
    pRect(sx - 4, snY - 12, 4, 2, '#92400e');
    pRect(sx - 1, snY - 10, 2, 2, '#78350f');

    // Kafa ve duyargalar (tıklanınca kabuğa gizlenir)
    if (!snailTucked) {
        const ext = Math.max(1, Math.round(peekAmt * 5));
        const hx = snX + 5 + ext;
        pRect(snX + 5, snY - 6, ext + 2, 4, '#fef3c7');
        pRect(hx - 1, snY - 8, 4, 3, '#fde68a');
        pRect(hx + 1, snY - 12 + stalkWave, 1, 4, '#fcd34d');
        pRect(hx + 3, snY - 11 - stalkWave, 1, 4, '#fcd34d');
        pRect(hx + 1, snY - 13 + stalkWave, 1, 1, '#0f172a');
        pRect(hx + 3, snY - 12 - stalkWave, 1, 1, '#0f172a');
    }

    registerAmbientHitbox('betta_snail', snX - 15, snY - 21, snX + 16, snY + 5, 2);
}

function drawWetlandCritters(time) {
    // 1. Sazlığın Asil Ev Sahibi: Mavi Balıkçıl (~42px, tıklayınca kanat açıp ürkek sıçrar!)
    const hx = getLeftSafeX(0.30);
    const groundHeronY = ph - 14;
    const react = getAmbientReaction('wetland_heron', time);

    let lift = 0;
    let wingOpen = false;
    let flap = 0;
    let isSquawking = false;
    if (react) {
        const p = react.progress;
        lift = Math.round(Math.sin(p * Math.PI) * 11);
        wingOpen = p >= 0.05 && p < 0.88;
        flap = Math.round(Math.sin(p * Math.PI * 7) * 3);
        isSquawking = p >= 0.06 && p < 0.44;
    }

    const hy = groundHeronY - lift;
    const phase = (time % 17000) / 17000;
    const blink = !wingOpen && (time % 5100) > 4920;

    let dipNeck = 0;
    if (!wingOpen) {
        if (phase >= 0.62 && phase < 0.76) {
            dipNeck = Math.round(((phase - 0.62) / 0.14) * 5);
        } else if (phase >= 0.76 && phase < 0.81) {
            dipNeck = 8;
        } else if (phase >= 0.81 && phase < 0.92) {
            dipNeck = Math.round((1 - (phase - 0.81) / 0.11) * 6);
        }
    }

    pRect(hx - 7, groundHeronY + 2, 15, 2, 'rgba(2, 12, 18, 0.35)');
    if (react && react.progress < 0.65) {
        pRect(hx - 10, groundHeronY, 22, 1, 'rgba(224, 242, 254, 0.72)');
        pRect(hx - 6, groundHeronY - 3, 2, 2, '#e0f2fe');
        pRect(hx + 7, groundHeronY - 4, 2, 2, '#bae6fd');
    }

    pRect(hx - 1, hy - 14, 2, 16, '#1e293b');
    pRect(hx + 3, hy - 14, 2, 16, '#334155');
    if (!wingOpen) {
        pRect(hx - 5, groundHeronY + 1, 12, 1, 'rgba(186, 230, 253, 0.38)');
    }
    if (!wingOpen && phase >= 0.76 && phase < 0.84) {
        const sp = Math.round(((phase - 0.76) / 0.08) * 9);
        pRect(hx + 16 - sp, groundHeronY, sp * 2, 1, 'rgba(224, 242, 254, 0.65)');
    }

    // Geniş açılan katmanlı kanatlar (tıklama tepkisi)
    if (wingOpen) {
        pRect(hx - 23, hy - 34 + flap, 21, 9, '#334155');
        pRect(hx - 21, hy - 32 + flap, 18, 6, '#64748b');
        pRect(hx - 23, hy - 27 + flap, 15, 4, '#0f172a');
        pRect(hx + 3, hy - 34 - flap, 18, 8, '#475569');
        pRect(hx + 6, hy - 31 - flap, 15, 5, '#94a3b8');
        pRect(hx + 14, hy - 27 - flap, 7, 3, '#1e293b');
    }

    pRect(hx - 9, hy - 25, 16, 11, '#334155');
    pRect(hx - 7, hy - 26, 13, 9, '#475569');
    pRect(hx - 5, hy - 25, 9, 5, '#64748b');
    pRect(hx - 2, hy - 23, 6, 3, '#cbd5e1');
    pRect(hx - 11, hy - 21, 5, 4, '#1e293b');
    pRect(hx + 3, hy - 23, 5, 7, '#e2e8f0');

    const neckForward = Math.round(dipNeck * 0.75);
    const neckDown = dipNeck - (wingOpen ? 2 : 0);
    pRect(hx + 4 + Math.round(neckForward * 0.3), hy - 32 + Math.round(neckDown * 0.5), 3, 9, '#f1f5f9');
    pRect(hx + 5 + Math.round(neckForward * 0.6), hy - 38 + Math.round(neckDown * 0.8), 3, 8, '#ffffff');
    pRect(hx + 5 + neckForward, hy - 41 + neckDown, 6, 4, '#ffffff');
    pRect(hx + 3 + neckForward, hy - 42 + neckDown, 7, 2, '#0f172a');
    pRect(hx + 1 + neckForward, hy - 41 + neckDown, 3, 1, '#334155');
    pRect(hx + 8 + neckForward, hy - 40 + neckDown, 1, 1, blink ? '#cbd5e1' : '#facc15');
    if (isSquawking) {
        pRect(hx + 11, hy - 41 + neckDown, 8, 1, '#f59e0b');
        pRect(hx + 11, hy - 38 + neckDown, 8, 1, '#fde047');
        pRect(hx + 21, hy - 43 + neckDown, 2, 1, '#ffffff');
        pRect(hx + 22, hy - 40 + neckDown, 3, 1, '#fef08a');
    } else {
        pRect(hx + 11 + neckForward, hy - 40 + neckDown, 8, 2, '#f59e0b');
        pRect(hx + 15 + neckForward, hy - 39 + neckDown, 5, 1, '#fde047');
    }

    registerAmbientHitbox('wetland_heron', hx - 14, hy - 44, hx + 22, groundHeronY + 5, 3);

    // 2. Büyütülmüş Su Kaplumbağası (~25x14px — tıklayınca kabuğa gizlenip su dalgalandırır)
    const snagX = Math.round(pw * 0.66);
    const snagBankY = getGroundY(snagX + 8, 'wetland', pw, ph) + 1;
    const tuX = snagX - 3;
    const tuY = snagBankY - 8;
    const tReact = getAmbientReaction('wetland_turtle', time);
    const tuckPhase = (time % 15000) / 15000;
    const hideFully = tReact ? tReact.progress < 0.72 : false;
    const rockTu = tReact && tReact.progress < 0.25 ? Math.round(Math.sin(tReact.progress * Math.PI * 12)) : 0;
    const headPull = hideFully ? 8 : ((tuckPhase > 0.74 && tuckPhase < 0.88) ? 3 : 0);
    const blinkTu = (time % 4600) > 4420;

    pRect(tuX - 8, tuY - 2, 17, 3, '#92400e');
    if (tReact && tReact.progress < 0.45) {
        pRect(tuX - 13, tuY + 2, 26, 1, 'rgba(186, 230, 253, 0.55)');
    }
    pRect(tuX - 9 + rockTu, tuY - 8, 18, 6, '#14532d');
    pRect(tuX - 7 + rockTu, tuY - 10, 14, 5, '#166534');
    pRect(tuX - 5 + rockTu, tuY - 9, 4, 2, '#4ade80');
    pRect(tuX + 1 + rockTu, tuY - 9, 4, 2, '#4ade80');
    pRect(tuX - 6 + rockTu, tuY - 6, 4, 2, '#d97706');
    pRect(tuX + 2 + rockTu, tuY - 6, 4, 2, '#d97706');
    if (!hideFully) {
        pRect(tuX - 8, tuY, 3, 3, '#365314');
        pRect(tuX + 5, tuY, 3, 3, '#365314');
        pRect(tuX - 13 + headPull, tuY - 6, 6, 3, '#4d7c0f');
        pRect(tuX - 15 + headPull, tuY - 8, 5, 3, '#65a30d');
        pRect(tuX - 12 + headPull, tuY - 6, 2, 1, '#ef4444');
        pRect(tuX - 14 + headPull, tuY - 8, 1, 1, blinkTu ? '#365314' : '#0f172a');
    }

    registerAmbientHitbox('wetland_turtle', tuX - 17, tuY - 13, tuX + 14, tuY + 6, 2);
}

function drawBotanicalCatStanding(cx, footY, facing, archH, stepCycle, heartUp) {
    const px = (ox, oy, w, h, col) => pRect(facing >= 0 ? cx + ox : cx - ox - w, footY + oy, w, h, col);

    pRect(cx - 12, footY - 1, 24, 3, 'rgba(2, 8, 16, 0.36)');

    // Kıvrılmış neşeli turuncu kuyruk
    const tailWag = Math.round(Math.sin(stepCycle * 0.5) * 1.5);
    px(-14, -14 + tailWag, 4, 3, '#f97316');
    px(-15, -17 + tailWag, 3, 3, '#fef3c7');
    px(-11, -11, 4, 4, '#ea580c');

    // Dört beyaz patili adım atan bacak
    const legA = Math.round(Math.sin(stepCycle) * 2);
    const legB = -legA;
    px(-8 + legA, -6, 3, 5, '#ea580c');
    px(-8 + legA, -2, 4, 2, '#fef3c7');
    px(-3 + legB, -6, 3, 5, '#c2410c');
    px(-3 + legB, -2, 3, 2, '#ffffff');
    px(3 + legB, -6, 3, 5, '#ea580c');
    px(3 + legB, -2, 4, 2, '#fef3c7');
    px(6 + legA, -6, 3, 5, '#c2410c');
    px(6 + legA, -2, 3, 2, '#ffffff');

    // Gövde + tekir çizgileri (esnerken sırtı kamburlaşır!)
    px(-9, -13 - archH, 18, 7 + Math.round(archH * 0.6), '#ea580c');
    px(-7, -14 - archH, 14, 3, '#f97316');
    px(-5, -14 - archH, 10, 2, '#fb923c');
    px(-6, -13 - archH, 2, 4, '#9a3412');
    px(-1, -13 - archH, 2, 4, '#9a3412');
    px(4, -13 - archH, 2, 4, '#9a3412');
    px(2, -9, 7, 3, '#fef3c7');

    // Baş (oyuncak ya da neşeli yürüyüş bakışı)
    const hy = -21 - Math.round(archH * 0.35);
    px(5, hy - 3, 3, 4, '#c2410c');
    px(6, hy - 2, 1, 2, '#fda4af');
    px(11, hy - 3, 3, 4, '#c2410c');
    px(12, hy - 2, 1, 2, '#fda4af');
    px(4, hy, 11, 9, '#f97316');
    px(6, hy - 1, 7, 2, '#fb923c');
    px(7, hy + 4, 7, 5, '#fef3c7');
    px(11, hy + 5, 2, 1, '#fb7185');
    px(7, hy + 3, 2, 2, '#34d399');
    px(11, hy + 3, 2, 2, '#34d399');
    px(7, hy + 3, 1, 1, '#0f172a');
    px(11, hy + 3, 1, 1, '#0f172a');

    if (heartUp >= 0) {
        const hyPos = footY - 27 - Math.round(heartUp);
        pRect(cx - 2, hyPos, 2, 2, '#fb7185');
        pRect(cx + 1, hyPos, 2, 2, '#fb7185');
        pRect(cx - 1, hyPos + 1, 3, 2, '#f43f5e');
        pRect(cx, hyPos + 3, 1, 1, '#e11d48');
    }
}

function drawBotanicalCritters(time) {
    // 1. Bahçenin Uyuyan Sarman Kedisi (~34x22px, tıklayınca uyanıp sırt esnetir, koşup pati atar ve taşına döner!)
    const catX = getRightSafeX(0.68);
    const catY = getGroundY(catX, 'botanical', pw, ph) + 1;

    // Sabit yosunlu bahçe taşı
    pRect(catX - 17, catY, 35, 3, 'rgba(2, 8, 16, 0.42)');
    pRect(catX - 16, catY - 3, 33, 4, '#334155');
    pRect(catX - 15, catY - 4, 31, 2, '#475569');
    pRect(catX - 13, catY - 4, 6, 1, '#15803d');

    const catReact = getAmbientReaction('botanical_cat', time);
    let curCatX = catX;

    if (catReact && catReact.progress >= 0.04 && catReact.progress < 0.90) {
        const p = catReact.progress;
        let jumpY = 0;
        let archH = 0;
        let facing = -1;
        let stepCycle = p * 26;
        let heartUp = -1;

        if (p < 0.18) {
            archH = Math.round(Math.sin(((p - 0.04) / 0.14) * Math.PI) * 3);
            stepCycle = 0;
            heartUp = ((p - 0.04) / 0.14) * 7;
        } else if (p < 0.54) {
            const u = (p - 0.18) / 0.36;
            const walkOut = Math.min(1, u / 0.65);
            curCatX = catX - Math.round(easeInOutQuad(walkOut) * 28);
            facing = -1;
            if (u > 0.65) {
                const pounceU = (u - 0.65) / 0.35;
                jumpY = -Math.round(Math.sin(pounceU * Math.PI) * 7);
                pRect(curCatX - 18, catY - 12 - Math.round(Math.sin(pounceU * Math.PI) * 5), 2, 2, '#fde047');
                pRect(curCatX - 21, catY - 9, 2, 2, '#f472b6');
                stepCycle = Math.PI * 0.5;
            }
        } else {
            const u = (p - 0.54) / 0.36;
            curCatX = catX - Math.round((1 - easeInOutQuad(u)) * 28);
            facing = 1;
            heartUp = u * 9;
        }

        const standingFootY = Math.round(catY - 3 + jumpY);
        drawBotanicalCatStanding(curCatX, standingFootY, facing, archH, stepCycle, heartUp);
    } else {
        const phase = (time % 18000) / 18000;
        const breath = Math.sin(time * 0.0019) > 0.3 ? -1 : 0;
        const earTwitch = (time % 6800) > 6580 ? -1 : 0;
        const tailCurl = Math.round(Math.sin(time * 0.0020) * 1.4);

        const waking = phase >= 0.62 && phase < 0.86;
        const yawning = phase >= 0.71 && phase < 0.80;
        const headLift = waking ? -2 : 0;

        pRect(catX - 12, catY - 12 + breath, 21, 9, '#ea580c');
        pRect(catX - 9, catY - 14 + breath, 15, 4, '#f97316');
        pRect(catX - 6, catY - 14 + breath, 9, 2, '#fb923c');
        pRect(catX - 7, catY - 13 + breath, 2, 5, '#9a3412');
        pRect(catX - 2, catY - 13 + breath, 2, 5, '#9a3412');
        pRect(catX + 3, catY - 13 + breath, 2, 5, '#9a3412');

        pRect(catX - 14, catY - 7, 5, 4, '#ea580c');
        pRect(catX - 16, catY - 9 + tailCurl, 4, 3, '#f97316');
        pRect(catX - 17, catY - 10 + tailCurl, 3, 2, '#fef3c7');

        pRect(catX + 6, catY - 5, 6, 3, '#fef3c7');
        pRect(catX + 8, catY - 6, 4, 2, '#ffffff');

        const hx = catX + 3;
        const hy = catY - 18 + breath + headLift;
        pRect(hx, hy - 3 + earTwitch, 3, 4, '#c2410c');
        pRect(hx + 1, hy - 2 + earTwitch, 1, 2, '#fda4af');
        pRect(hx + 7, hy - 3, 3, 4, '#c2410c');
        pRect(hx + 8, hy - 2, 1, 2, '#fda4af');
        pRect(hx - 1, hy, 12, 9, '#f97316');
        pRect(hx + 1, hy - 1, 8, 2, '#fb923c');
        pRect(hx + 2, hy + 4, 8, 5, '#fef3c7');
        pRect(hx + 5, hy + 5, 2, 1, '#fb7185');
        if (yawning) {
            pRect(hx + 5, hy + 6, 3, 2, '#be123c');
            pRect(hx + 6, hy + 7, 1, 1, '#fda4af');
        }
        if (waking && !yawning) {
            pRect(hx + 2, hy + 3, 2, 2, '#34d399');
            pRect(hx + 7, hy + 3, 2, 2, '#34d399');
            pRect(hx + 2, hy + 3, 1, 1, '#0f172a');
            pRect(hx + 7, hy + 3, 1, 1, '#0f172a');
        } else {
            pRect(hx + 2, hy + 3, 2, 1, '#7c2d12');
            pRect(hx + 7, hy + 3, 2, 1, '#7c2d12');
        }
    }

    registerAmbientHitbox('botanical_cat', curCatX - 20, catY - 25, curCatX + 20, catY + 5, 3);

    // 2. Büyütülmüş Bahçe Kızılgerdanı (~22x17px — tıklayınca cıvıldayıp kanat çırparak zıplar)
    const birdX = getLeftSafeX(0.30);
    const birdBaseY = getGroundY(birdX, 'botanical', pw, ph) + 1;
    pRect(birdX - 8, birdBaseY - 4, 16, 5, '#334155');
    pRect(birdX - 6, birdBaseY - 5, 13, 2, '#64748b');

    const birdReact = getAmbientReaction('botanical_robin', time);
    let curRx = birdX;
    let curRy = birdBaseY - 4;
    let wingFlap = 0;

    if (birdReact) {
        const p = birdReact.progress;
        curRx = birdX + Math.round(Math.sin(p * Math.PI * 2) * 14);
        curRy = birdBaseY - 4 - Math.round(Math.sin(p * Math.PI) * 18);
        wingFlap = Math.sin(p * Math.PI * 10) > 0 ? -4 : 1;
        pRect(curRx + 5, curRy - 18 - Math.round(p * 6), 2, 2, '#fde047');
        pRect(curRx + 7, curRy - 20 - Math.round(p * 6), 2, 1, '#fef08a');
    }

    const birdPhase = (time % 14000) / 14000;
    const birdDip = !birdReact && (birdPhase > 0.65 && birdPhase < 0.80) ? 2 : 0;
    const blinkR = !birdReact && (time % 4700) > 4520;

    pRect(curRx - 2, curRy - 3, 2, 3, '#78350f');
    pRect(curRx + 2, curRy - 3, 2, 3, '#78350f');
    pRect(curRx - 11, curRy - 9 + birdDip, 5, 3, '#451a03');
    pRect(curRx - 7, curRy - 11 + birdDip, 13, 8, '#78350f');
    pRect(curRx - 6, curRy - 9 + wingFlap + birdDip, 7, 4, '#5c3a21');
    pRect(curRx - 1, curRy - 11 + birdDip, 8, 7, '#ef4444');
    pRect(curRx + 1, curRy - 10 + birdDip, 5, 4, '#fb923c');
    pRect(curRx, curRy - 4 + birdDip, 5, 2, '#fef3c7');
    pRect(curRx - 1, curRy - 16 + birdDip, 8, 6, '#92400e');
    pRect(curRx + 3, curRy - 15 + birdDip, 2, 2, blinkR ? '#78350f' : '#0f172a');
    if (!blinkR) pRect(curRx + 3, curRy - 15 + birdDip, 1, 1, '#ffffff');
    pRect(curRx + 7, curRy - 13 + birdDip, 4, 2, '#facc15');

    registerAmbientHitbox('botanical_robin', curRx - 13, curRy - 21, curRx + 14, curRy + 4, 2);
}

function drawReefCritters(time) {
    const reefFloorY = (x) => {
        const nx = x / Math.max(1, pw);
        const sideMound = nx < 0.26 ? Math.pow((0.26 - nx) / 0.26, 1.5) * 34
                        : (nx > 0.74 ? Math.pow((nx - 0.74) / 0.26, 1.5) * 34 : 0);
        return Math.round(getGroundY(x, 'reef', pw, ph) - sideMound);
    };

    // 1. TAMAMEN YENİDEN TASARLANAN MERCAN-KIZIL BİYOLÜMİNESAN AHTAPOT (~52x38px, tıklayınca mürekkep bulutuyla yukarı fırlar!)
    const octX = getLeftSafeX(0.30);
    const floorY = reefFloorY(octX) - 2;
    const octReact = getAmbientReaction('reef_octopus', time);

    let crouch = 0;
    let jetY = 0;
    let isJetting = false;
    let flashBoost = false;

    if (octReact) {
        const p = octReact.progress;
        flashBoost = p < 0.22;
        if (p < 0.12) {
            crouch = Math.round(easeOutQuad(p / 0.12) * 3);
        } else if (p < 0.44) {
            isJetting = true;
            jetY = -Math.round(easeOutQuad((p - 0.12) / 0.32) * 28);
        } else if (p < 0.90) {
            isJetting = true;
            jetY = -Math.round((1 - easeInOutQuad((p - 0.44) / 0.46)) * 28);
        }
        // Zemin noktasında dağılan koyu lacivert mürekkep bulutu
        if (p >= 0.12 && p < 0.78) {
            const inkT = (p - 0.12) / 0.66;
            const alpha = ((1 - inkT) * 0.76).toFixed(2);
            const colInkA = `rgba(15, 23, 42, ${alpha})`;
            const colInkB = `rgba(30, 27, 75, ${(Number(alpha) * 0.85).toFixed(2)})`;
            const spread = Math.round(inkT * 22);
            pRect(octX - 11 - spread, floorY - 12 - Math.round(inkT * 10), 14, 9, colInkA);
            pRect(octX - 3 + Math.round(spread * 0.4), floorY - 16 - Math.round(inkT * 14), 16, 11, colInkB);
            pRect(octX - 16 - Math.round(spread * 0.6), floorY - 6, 11, 7, colInkB);
            pRect(octX + 6 + spread, floorY - 8, 10, 6, colInkA);
        }
    }

    const baseY = floorY + crouch + jetY;
    const phase = (time % 16000) / 16000;
    const mantlePulse = isJetting ? 0 : (Math.sin(time * 0.0020) > 0.35 ? -1 : 0);
    const blink = !isJetting && (time % 5200) > 5010;
    const biolumi = flashBoost || (phase > 0.46 && phase < 0.70);
    const wave = Math.sin(time * 0.0026);

    const ocOutline = '#4c0519';
    const ocDeep = '#881337';
    const ocMid = '#be123c';
    const ocBright = '#e11d48';
    const ocHi = '#fb7185';
    const ocCup = '#fbcfe8';
    const ocellusCore = flashBoost ? '#a5f3fc' : (biolumi ? '#67e8f9' : '#22d3ee');

    if (!isJetting) {
        pRect(octX - 24, floorY + 1, 48, 3, 'rgba(5, 4, 23, 0.46)');
    }

    // Organik 5 kıvrımlı dokunaç & pembe vantuz dizileri
    const drawTentacleArc = (points, isBack) => {
        for (let i = 0; i < points.length; i++) {
            const pt = points[i];
            const rx = octX + pt[0];
            const ry = baseY + pt[1];
            const r = pt[2];
            pRect(rx - r, ry - 1, r * 2, r + 1, isBack ? ocOutline : ocDeep);
            pRect(rx - Math.max(1, r - 1), ry - 1, Math.max(1, r * 2 - 2), r, isBack ? ocDeep : ocMid);
            if (!isBack && r >= 3) pRect(rx - r + 1, ry - 1, r, 1, ocBright);
            if (i % 2 === 1 && r >= 2) pRect(rx, ry + r - 1, 2, 1, ocCup);
        }
    };

    if (isJetting && octReact && octReact.progress < 0.44) {
        // Roket gibi yükselirken alta doğru uzanan ince dokunaçlar
        const trail = Math.round(Math.sin(time * 0.025) * 2);
        [-10, -5, 0, 5, 10].forEach((tx, idx) => {
            for (let s = 0; s < 5; s++) {
                const wx = octX + tx + (s >= 3 ? trail * (idx % 2 === 0 ? 1 : -1) : 0);
                const wy = baseY - 2 + s * 4;
                const w = Math.max(1, 3 - Math.floor(s * 0.45));
                pRect(wx - 1, wy, w + 1, 4, s > 2 ? ocDeep : ocMid);
                if (s % 2 === 1) pRect(wx, wy + 2, 1, 1, ocCup);
            }
        });
    } else {
        const lift = Math.round(wave * 2) + (isJetting ? -2 : 0);
        // Arka sol & arka sağ kıvrık dokunaçlar
        drawTentacleArc([[-9, -4, 4], [-14, -2, 3], [-19, -3, 3], [-23, -6, 2], [-25, -9, 1]], true);
        drawTentacleArc([[8, -5, 4], [13, -6 + lift, 3], [17, -10 + lift, 3], [19, -15 + lift, 2], [17, -19 + lift, 1]], true);
        // Ön sol kayaya sarılan, orta yayılan ve ön sağ meraktan sallanan dokunaçlar
        drawTentacleArc([[-7, -3, 4], [-12, 0, 4], [-18, 0, 3], [-23, -2, 2], [-26, -5, 2]], false);
        drawTentacleArc([[-3, -2, 4], [-5, 1, 3], [-1, 2, 3], [4, 1, 2], [8, 0, 2]], false);
        drawTentacleArc([[5, -3, 4], [11, 0, 4], [17, 1, 3], [22, -2, 2], [25, -6, 2]], false);
    }

    // Doğal eğimli armut biçimli manto kubbesi (satır satır organik çizim)
    const domeCenterX = octX - 2;
    const domeTop = baseY - 33 + mantlePulse;
    const domeHeight = 19;
    for (let dy = 0; dy < domeHeight; dy++) {
        const t = dy / (domeHeight - 1);
        const bulge = Math.sin(Math.pow(t, 0.72) * Math.PI);
        const halfW = Math.max(2, Math.round(3 + bulge * 8.5));
        const lean = Math.round((1 - t) * -3);
        const rowX = domeCenterX + lean;
        const rowY = domeTop + dy;
        pRect(rowX - halfW - 1, rowY, halfW * 2 + 2, 1, ocOutline);
        pRect(rowX - halfW, rowY, halfW * 2, 1, t > 0.72 ? ocDeep : ocMid);
        pRect(rowX - halfW + 1, rowY, Math.max(2, Math.round(halfW * 1.3)), 1, ocBright);
        if (t < 0.45 && halfW >= 5) {
            pRect(rowX - Math.floor(halfW * 0.5), rowY, Math.max(2, Math.floor(halfW * 0.7)), 1, t < 0.2 ? '#fda4af' : ocHi);
        }
    }

    // Yan sifon hunisi & biyolüminesan camgöbeği göz-benek (ocelli) halkaları
    pRect(octX + 8, baseY - 19 + mantlePulse, 5, 3, ocDeep);
    pRect(octX + 12, baseY - 18 + mantlePulse, 2, 2, ocBright);
    pRect(octX - 8, baseY - 26 + mantlePulse, 4, 3, ocOutline);
    pRect(octX - 7, baseY - 25 + mantlePulse, 2, 2, ocellusCore);
    pRect(octX - 3, baseY - 21 + mantlePulse, 4, 3, ocOutline);
    pRect(octX - 2, baseY - 20 + mantlePulse, 2, 2, ocellusCore);
    pRect(octX + 3, baseY - 25 + mantlePulse, 3, 2, ocOutline);
    pRect(octX + 4, baseY - 25 + mantlePulse, 1, 1, ocellusCore);

    // İfade dolu ahtapot başı, çıkıntılı kaşlar ve yatay dikdörtgen gözbebekleri
    pRect(octX - 10, baseY - 16, 20, 12, ocMid);
    pRect(octX - 8, baseY - 15, 16, 9, ocBright);
    pRect(octX - 9, baseY - 17, 7, 3, ocHi);
    pRect(octX + 2, baseY - 17, 7, 3, ocHi);
    pRect(octX - 8, baseY - 14, 5, 5, blink ? ocDeep : '#fbbf24');
    pRect(octX + 3, baseY - 14, 5, 5, blink ? ocDeep : '#fbbf24');
    if (!blink) {
        pRect(octX - 7, baseY - 13, 3, 2, '#fef08a');
        pRect(octX + 4, baseY - 13, 3, 2, '#fef08a');
        pRect(octX - 7, baseY - 12, 4, 2, '#090d16');
        pRect(octX + 4, baseY - 12, 4, 2, '#090d16');
        pRect(octX - 8, baseY - 14, 1, 1, '#ffffff');
        pRect(octX + 3, baseY - 14, 1, 1, '#ffffff');
    }

    registerAmbientHitbox('reef_octopus', octX - 28, baseY - 35, octX + 28, baseY + 6, 3);

    // 2. Mercanda Şakayık ve Palyaço Balığı (~26x18px — tıklayınca balığı içeri saklanıp neşeli tur atar!)
    const anemX = Math.min(Math.round(pw * 0.62), getRightSafeX(0.66));
    const anemY = reefFloorY(anemX) - 2;
    const anemReact = getAmbientReaction('reef_anemone', time);
    const sw = Math.sin(time * 0.0022);
    const hideCurl = anemReact && anemReact.progress < 0.25 ? 1 : 0;

    pRect(anemX - 10, anemY - 3, 20, 4, '#831843');
    for (let t = -8; t <= 8; t += 4) {
        const th = (hideCurl ? 5 : 8) + ((Math.abs(t) + 1) % 3) * 2;
        const ts = hideCurl ? -Math.sign(t) : Math.round(sw * (t >= 0 ? 1.3 : 0.8));
        pRect(anemX + t, anemY - th, 3, th, '#db2777');
        pRect(anemX + t + ts, anemY - th - 2, 3, 2, '#f472b6');
        pRect(anemX + t + ts, anemY - th - 3, 2, 1, '#fbcfe8');
    }

    let cfX = anemX + 2;
    let cfY = anemY - 9;
    let cfDir = 1;
    let cfHide = false;
    if (anemReact) {
        const ap = anemReact.progress;
        if (ap < 0.22) {
            cfHide = true;
        } else if (ap < 0.86) {
            const loopU = (ap - 0.22) / 0.64;
            cfX = anemX + Math.round(Math.sin(loopU * Math.PI * 2) * 14);
            cfY = anemY - 12 - Math.round(Math.sin(loopU * Math.PI) * 11);
            cfDir = Math.cos(loopU * Math.PI * 2) >= 0 ? 1 : -1;
            pRect(cfX - cfDir * 7, cfY + 1, 2, 2, 'rgba(224, 242, 254, 0.72)');
        }
    } else if (phase > 0.45 && phase < 0.78) {
        cfX += Math.round(Math.sin(((phase - 0.45) / 0.33) * Math.PI) * 5);
    }

    if (!cfHide) {
        const cfRect = (ox, oy, w, h, col) => pRect(cfDir >= 0 ? cfX + ox : cfX - ox - w, cfY + oy, w, h, col);
        cfRect(-6, -3, 12, 6, '#f97316');
        cfRect(-9, -2, 3, 4, '#ea580c');
        cfRect(-2, -3, 2, 6, '#ffffff');
        cfRect(2, -3, 2, 6, '#ffffff');
        cfRect(4, -2, 1, 2, '#0f172a');
    }

    registerAmbientHitbox('reef_anemone', anemX - 16, anemY - 21, anemX + 19, anemY + 4, 2);
}

function drawKoiPondCritters(time) {
    // 1. DIŞ ÇEVRE KORİDORUNDA GEZİNEN LOCH NESS / YEŞİM GÖL EJDERHASI
    // Saat, Arama Kutusu, Kısayollar & Gündem UI bölgesini [0.27..0.73*pw, 0.23..0.82*ph] ASLA kesmeyen 8 noktalı açık su halkası!
    const waypoints = [
        { x: Math.round(pw * 0.16), y: Math.round(ph * 0.21), canEmerge: true },  // 0: Sol-üst açık su
        { x: Math.round(pw * 0.16), y: Math.round(ph * 0.46), canEmerge: true },  // 1: Sol-orta açık göl (Arama & Saat solu)
        { x: Math.round(pw * 0.18), y: Math.round(ph * 0.72), canEmerge: true },  // 2: Sol-alt açık göl (Müzik Widget üstü)
        { x: Math.round(pw * 0.30), y: Math.round(ph * 0.87), canEmerge: true },  // 3: Alt-sol açık kanal
        { x: Math.round(pw * 0.52), y: Math.round(ph * 0.88), canEmerge: true },  // 4: Alt-orta açık gölet (Gündem altı)
        { x: Math.round(pw * 0.74), y: Math.round(ph * 0.84), canEmerge: true },  // 5: Alt-sağ açık kanal (Sistem Widget solu)
        { x: Math.round(pw * 0.78), y: Math.round(ph * 0.46), canEmerge: true },  // 6: Sağ-orta açık derin su
        { x: Math.round(pw * 0.76), y: Math.round(ph * 0.21), canEmerge: false }  // 7: Sağ-üst & üst bar altı su-altı transit
    ];

    if (!nessRoam.initialized) {
        nessRoam.initialized = true;
        nessRoam.wpIdx = 1;
        nessRoam.loopDir = 1;
        nessRoam.x = waypoints[1].x;
        nessRoam.y = waypoints[1].y;
        nessRoam.targetX = waypoints[2].x;
        nessRoam.targetY = waypoints[2].y;
        nessRoam.dir = 1;
        nessRoam.lastTime = time;
    }

    const react = getAmbientReaction('koi_loch_ness', time);
    const phase = (time % 22000) / 22000;
    let baseEmerge = 0;
    if (phase >= 0.48 && phase < 0.58) {
        const u = (phase - 0.48) / 0.10;
        baseEmerge = 1 - (1 - u) * (1 - u);
    } else if (phase >= 0.58 && phase < 0.86) {
        baseEmerge = 1;
    } else if (phase >= 0.86) {
        const u = (phase - 0.86) / 0.14;
        baseEmerge = 1 - u * u;
    }

    let reactEmerge = 0;
    let rearExtra = 0;
    if (react) {
        const rp = react.progress;
        if (rp < 0.18) {
            reactEmerge = easeOutQuad(rp / 0.18);
            rearExtra = Math.round(reactEmerge * 7);
        } else if (rp < 0.76) {
            reactEmerge = 1;
            rearExtra = 7;
        } else {
            const d = (rp - 0.76) / 0.24;
            reactEmerge = 1 - d * d;
            rearExtra = Math.round(reactEmerge * 7);
        }
    }

    const curInCenterUI = nessRoam.x > pw * 0.27 && nessRoam.x < pw * 0.73 && nessRoam.y < ph * 0.82;
    const safeToEmerge = nessRoam.y >= Math.round(ph * 0.23) && !curInCenterUI;
    const emerge = Math.max(safeToEmerge ? baseEmerge : 0, reactEmerge);

    // Açık çevre halkası boyunca sıralı ilerleme (merkez arama kutusunu asla kesmez)
    const dt = nessRoam.lastTime ? clampVal(time - nessRoam.lastTime, 0, 80) : 16;
    nessRoam.lastTime = time;
    const targetWp = waypoints[nessRoam.wpIdx] || waypoints[1];
    nessRoam.targetX = targetWp.x;
    nessRoam.targetY = targetWp.y;
    const dxToT = nessRoam.targetX - nessRoam.x;
    const dyToT = nessRoam.targetY - nessRoam.y;
    const distToT = Math.hypot(dxToT, dyToT);
    if (distToT < 16) {
        nessRoam.wpIdx = (nessRoam.wpIdx + nessRoam.loopDir + waypoints.length) % waypoints.length;
        const nextWp = waypoints[nessRoam.wpIdx];
        nessRoam.targetX = nextWp.x;
        nessRoam.targetY = nextWp.y;
    } else if (dt > 0) {
        const moveSpeed = 0.025 * (1 - emerge * 0.85);
        nessRoam.vx = (dxToT / distToT) * moveSpeed;
        nessRoam.vy = (dyToT / distToT) * moveSpeed;
        nessRoam.x = clampVal(nessRoam.x + nessRoam.vx * dt, 64, pw - 90);
        nessRoam.y = clampVal(nessRoam.y + nessRoam.vy * dt, 58, ph - 14);
        if (Math.abs(nessRoam.vx) > 0.002) {
            nessRoam.dir = nessRoam.vx >= 0 ? 1 : -1;
        }
    }

    const nessX = Math.round(nessRoam.x);
    const nessY = Math.round(nessRoam.y);
    const dir = nessRoam.dir;
    const subGlide = Math.sin(time * 0.0022) * 3;

    // Alt vücut HER ZAMAN derin koyu gölet suyunun altında uzun kıvrımlı gölge olarak kalır!
    pRect(Math.round(nessX - dir * 10 - 11 + subGlide), nessY + 6, 22, 6, 'rgba(2, 14, 22, 0.34)');
    pRect(Math.round(nessX - dir * 32 - 14 + subGlide * 0.7), nessY + 10, 28, 7, 'rgba(2, 14, 22, 0.40)');
    pRect(Math.round(nessX - dir * 56 - 11 - subGlide * 0.5), nessY + 8, 22, 5, 'rgba(2, 14, 22, 0.28)');
    pRect(Math.round(nessX - dir * 74 - 7 + subGlide * 0.3), nessY + 6, 14, 3, 'rgba(2, 14, 22, 0.20)');

    if (emerge < 0.05 && ((time % 3200) < 1300)) {
        const bStep = ((time % 3200) / 1300);
        pRect(nessX + dir * 4, Math.round(nessY - 2 - bStep * 6), 2, 2, 'rgba(186, 230, 253, 0.48)');
        pRect(nessX - dir * 12, Math.round(nessY + 2 - bStep * 5), 2, 1, 'rgba(186, 230, 253, 0.38)');
        pRect(nessX - dir * 6, nessY, 16, 1, 'rgba(45, 212, 191, 0.24)');
    }

    if (emerge > 0.02) {
        const drawAboveWater = (x, y, w, h, col) => {
            if (y >= nessY || h <= 0) return;
            pRect(x, y, w, Math.min(h, nessY - y), col);
        };

        const colDeep = '#031d1c';
        const colDark = '#06322f';
        const colMid = '#0d544d';
        const colSpec = react ? '#5eead4' : '#2dd4bf';

        const headBob = emerge > 0.85 && Math.sin(time * 0.0020) > 0.4 ? -1 : 0;
        const liftY = Math.round(emerge * (40 + rearExtra));
        const headBaseY = nessY + 9 - liftY + headBob;
        const blinkNess = !react && (time % 6300) > 6100;

        if (emerge > 0.26) {
            const humpRise = Math.round(((emerge - 0.26) / 0.74) * (9 + Math.round(rearExtra * 0.4)));
            const humpX = nessX - dir * 34;
            drawAboveWater(humpX - 12, nessY - humpRise + 2, 24, humpRise, colDeep);
            drawAboveWater(humpX - 9, nessY - humpRise, 18, humpRise, colDark);
            drawAboveWater(humpX - 6, nessY - humpRise - 1, 12, 2, colMid);
            drawAboveWater(humpX - 4, nessY - humpRise - 3, 3, 2, colSpec);
            drawAboveWater(humpX + 1, nessY - humpRise - 3, 3, 2, colSpec);
            pRect(humpX - 14, nessY, 28, 2, 'rgba(224, 242, 254, 0.48)');
        }

        for (let dy = 0; dy <= 36; dy++) {
            const py = headBaseY - 1 + dy;
            if (py >= nessY) break;
            const prog = dy / 36;
            const curveX = nessX - dir * Math.round(Math.sin((1 - prog) * Math.PI * 0.85) * 6);
            const thick = Math.round(9 + prog * 5);
            const halfW = Math.floor(thick * 0.5);
            drawAboveWater(curveX - halfW, py, thick, 1, colDeep);
            drawAboveWater(curveX - halfW + (dir > 0 ? 2 : 1), py, Math.max(3, thick - 4), 1, colDark);
            drawAboveWater(curveX + (dir > 0 ? 0 : -2), py, 3, 1, colMid);
            if (dy % 5 === 0 && py < nessY - 1) {
                const finX = dir > 0 ? curveX - halfW - 3 : curveX + halfW;
                drawAboveWater(finX, py, 3, 2, colSpec);
            }
        }

        const hx = nessX - dir * 3;
        const hy = headBaseY;
        const hRect = (ox, oy, w, h, col) => drawAboveWater(dir >= 0 ? hx + ox : hx - ox - w, hy + oy, w, h, col);
        hRect(-5, -8, 16, 9, colDark);
        hRect(-4, -9, 13, 3, colMid);
        hRect(5, -6, 13, 5, colDeep);
        hRect(6, -6, 11, 3, colDark);
        hRect(9, -6, 7, 1, colSpec);
        hRect(15, -5, 1, 1, '#020617');
        hRect(-8, -11, 5, 3, colMid);
        hRect(-11, -13, 4, 3, colSpec);
        hRect(12, -2, 3, 2, colSpec);
        if (!blinkNess) {
            hRect(3, -6, 4, 2, '#fde047');
            hRect(5, -6, 1, 2, '#020617');
        } else {
            hRect(3, -5, 4, 1, colMid);
        }
        const dropOff = Math.floor((time * 0.014) % 9);
        drawAboveWater(hx + dir * 13, hy - 1 + dropOff, 1, 2, 'rgba(167, 243, 208, 0.72)');

        const surfHalf = Math.round(12 + emerge * 8 + (react ? 6 : 0));
        pRect(nessX - surfHalf, nessY, surfHalf * 2, 2, 'rgba(224, 242, 254, 0.65)');
        pRect(nessX - surfHalf - 7, nessY + 3, (surfHalf + 7) * 2, 1, 'rgba(45, 212, 191, 0.36)');
        pRect(nessX - surfHalf - 12, nessY + 6, (surfHalf + 12) * 2, 1, 'rgba(186, 230, 253, 0.24)');
        if (react && react.progress < 0.70) {
            const shockR = Math.round(surfHalf + react.progress * 38);
            pRect(nessX - shockR, nessY + 2, shockR * 2, 1, 'rgba(94, 234, 212, 0.45)');
        }
    }

    registerAmbientHitbox(
        'koi_loch_ness',
        Math.min(nessX - 42, nessX - dir * 56),
        nessY - (emerge > 0.04 ? 56 : 12),
        Math.max(nessX + 42, nessX + dir * 26),
        nessY + 22,
        3
    );

    // 2. Sağ-Alt Gölet Kıyısına Oturan Zen Kaplumbağası (~24x14px — tıklayınca suya atlayıp tur atar & kıyıya döner!)
    const rockX = pw >= 400 ? Math.min(Math.round(pw * 0.75), pw - 152) : Math.round(pw * 0.75);
    const rockY = ph - 7;

    // Gölün dibine ve sağ kıyısına organik oturan yosunlu taş kümesi + ufak sazlar
    pRect(rockX - 18, rockY + 1, 36, 6, 'rgba(2, 8, 16, 0.50)');
    pRect(rockX - 17, rockY - 4, 34, 11, '#1e293b');
    pRect(rockX - 15, rockY - 6, 30, 8, '#334155');
    pRect(rockX - 13, rockY - 7, 25, 3, '#475569');
    pRect(rockX - 11, rockY - 7, 19, 2, '#15803d');
    pRect(rockX - 6, rockY - 8, 11, 1, '#22c55e');
    // Taşın alt-sağ kıyısında organik saz yaprakları
    pRect(rockX + 12, rockY - 12, 2, 9, '#15803d');
    pRect(rockX + 15, rockY - 10, 2, 7, '#22c55e');

    const terrReact = getAmbientReaction('koi_terrapin', time);
    let tx = rockX;
    let ty = rockY;
    let tDir = -1;
    let isSwimming = false;
    let flipperKick = 0;

    if (terrReact) {
        const tp = terrReact.progress;
        if (tp < 0.14) {
            const u = tp / 0.14;
            tx = rockX - Math.round(u * 6);
            ty = rockY - Math.round(Math.sin(u * Math.PI) * 5);
            pRect(rockX - 18, rockY + 2, 20, 1, 'rgba(224, 242, 254, 0.72)');
            pRect(rockX - 14, rockY - 2, 2, 2, '#e0f2fe');
        } else if (tp < 0.86) {
            const u = (tp - 0.14) / 0.72;
            isSwimming = true;
            tx = rockX - 6 - Math.round(Math.sin(u * Math.PI) * 26);
            ty = rockY - Math.round(Math.sin(u * Math.PI) * 20) - Math.round(Math.sin(u * Math.PI * 2) * 5);
            tDir = Math.cos(u * Math.PI) >= 0 ? -1 : 1;
            flipperKick = Math.round(Math.sin(u * Math.PI * 10) * 2);
            pRect(tx - tDir * 10, ty - 2, 2, 2, 'rgba(224, 242, 254, 0.68)');
            pRect(tx - 12, ty + 3, 24, 1, 'rgba(45, 212, 191, 0.42)');
        } else {
            const u = (tp - 0.86) / 0.14;
            tx = Math.round(rockX - 6 * (1 - u));
            ty = rockY - Math.round(Math.sin(u * Math.PI) * 4);
            tDir = 1;
        }
    }

    const blinkTu = !isSwimming && (time % 5400) > 5220;
    const tRect = (ox, oy, w, h, col) => pRect(tDir >= 0 ? tx - ox - w : tx + ox, ty + oy, w, h, col);
    // Not: mevcut kaplumbağa varsayılan sola (-1) bakar; tDir = -1 doğal yön, +1 dönüş yönü
    if (isSwimming) {
        tRect(-9, -6 + flipperKick, 4, 3, '#4d7c0f');
        tRect(5, -6 - flipperKick, 4, 3, '#4d7c0f');
    }
    tRect(-7, -12, 16, 5, '#14532d');
    tRect(-5, -14, 12, 4, '#166534');
    tRect(-4, -13, 3, 2, '#4ade80');
    tRect(2, -13, 3, 2, '#d97706');
    tRect(-7, -8, 16, 1, '#b45309');
    tRect(-11, -11, 5, 3, '#4d7c0f');
    tRect(-14, -13, 5, 3, '#65a30d');
    tRect(-13, -12, 1, 1, blinkTu ? '#365314' : '#0f172a');

    registerAmbientHitbox('koi_terrapin', tx - 16, ty - 16, rockX + 18, rockY + 6, 2);
}

function drawArcticAlwaysPresentWildlife(time) {
    const ledges = getArcticLedges(pw, ph);

    // 1. Ledge 2 Üzerinde Koca Kutup Ayısı (~36x34px — tıklayınca şaha kalkıp iki patisini sallayarak buz nefesi verir!)
    const bearX = Math.max(Math.round(pw * 0.24), 146);
    const groundY = ledges[2].yFn(bearX) + 1;
    const bearReact = getAmbientReaction('arctic_bear', time);
    const riseOff = bearReact ? Math.round(Math.sin(bearReact.progress * Math.PI) * 4) : 0;

    const phase = (time % 18000) / 18000;
    const breath = bearReact ? (Math.sin(time * 0.012) > 0 ? -1 : 0) : (Math.sin(time * 0.0020) > 0.35 ? -1 : 0);
    const blink = !bearReact && (time % 5300) > 5120;
    const lookUp = bearReact || (phase > 0.58 && phase < 0.85) ? -1 : 0;
    const pawWaveRight = bearReact
        ? Math.round(Math.sin(bearReact.progress * Math.PI * 6) * 4)
        : (phase > 0.62 && phase < 0.82 ? Math.round(Math.sin(((phase - 0.62) / 0.20) * Math.PI * 3) * 3) : 0);
    const pawWaveLeft = bearReact ? -pawWaveRight : 0;

    const snowDeep = isLightMode ? '#cbd5e1' : '#94a3b8';
    const furShade = isLightMode ? '#e2e8f0' : '#bae6fd';
    const furBody = isLightMode ? '#f8fafc' : '#e0f2fe';
    const furBright = '#ffffff';

    pRect(bearX - 13, groundY - 1, 27, 3, 'rgba(56, 189, 248, 0.28)');
    pRect(bearX - 13, groundY - 6 - riseOff, 3, 3, furShade);
    pRect(bearX - 11, groundY - 20 - riseOff + breath, 20, 19 + riseOff, furBody);
    pRect(bearX - 11, groundY - 18 - riseOff + breath, 4, 16, furShade);
    pRect(bearX - 7, groundY - 21 - riseOff + breath, 12, 4, furBright);
    pRect(bearX - 3, groundY - 17 - riseOff + breath, 9, 14, furBright);
    pRect(bearX - 10, groundY - 5, 8, 5, furShade);
    pRect(bearX - 8, groundY - 4, 5, 3, furBright);
    pRect(bearX + 2, groundY - 5, 8, 5, furShade);
    pRect(bearX + 4, groundY - 4, 5, 3, furBright);
    if (bearReact) {
        pRect(bearX - 13, groundY - 15 - riseOff + breath - Math.max(0, pawWaveLeft), 5, 5, furBody);
        pRect(bearX - 14, groundY - 14 - riseOff + breath - Math.max(0, pawWaveLeft), 2, 2, snowDeep);
    }
    pRect(bearX + 7, groundY - 13 - riseOff + breath - Math.max(0, pawWaveRight), 6, 5, furBody);
    pRect(bearX + 8, groundY - 12 - riseOff + breath - Math.max(0, pawWaveRight), 5, 3, furBright);
    pRect(bearX + 10, groundY - 11 - riseOff + breath - Math.max(0, pawWaveRight), 2, 2, snowDeep);

    const hy = groundY - 32 - riseOff + breath + lookUp;
    pRect(bearX - 8, hy - 3, 4, 4, furShade);
    pRect(bearX - 7, hy - 2, 2, 2, snowDeep);
    pRect(bearX + 3, hy - 3, 4, 4, furShade);
    pRect(bearX + 4, hy - 2, 2, 2, snowDeep);
    pRect(bearX - 8, hy, 15, 12, furBright);
    pRect(bearX - 8, hy + 2, 3, 9, furShade);
    pRect(bearX - 2, hy + 4, 9, 7, furBright);
    pRect(bearX + 5, hy + 5, 3, 2, '#0f172a');
    pRect(bearX - 4, hy + 3, 2, 2, blink ? snowDeep : '#0f172a');
    pRect(bearX + 2, hy + 3, 2, 2, blink ? snowDeep : '#0f172a');
    if (!blink) {
        pRect(bearX - 4, hy + 3, 1, 1, '#ffffff');
        pRect(bearX + 2, hy + 3, 1, 1, '#ffffff');
    }

    const puff = (time * 0.007) % 18;
    if (puff < 12 || bearReact) {
        const alpha = bearReact ? '0.68' : ((1 - puff / 12) * 0.55).toFixed(2);
        pRect(bearX + 8 + Math.round(puff * 0.5), Math.round(hy + 6 - puff * 0.6), 4, 3, `rgba(224, 242, 254, ${alpha})`);
        if (bearReact) {
            pRect(bearX + 11 + Math.round(puff * 0.4), Math.round(hy + 2 - puff * 0.4), 3, 2, 'rgba(255, 255, 255, 0.55)');
        }
    }

    registerAmbientHitbox('arctic_bear', bearX - 16, groundY - 38 - riseOff, bearX + 18, groundY + 4, 3);

    // 2. Büyütülmüş Kutup Tavşanı (~21x19px — açık vadi karında, tıklayınca iki neşeli sıçrayışla kar savurur!)
    const hareHomeX = Math.round(pw * 0.39);
    const hareReact = getAmbientReaction('arctic_hare', time);
    let hopOffsetX = 0;
    let hopOffsetY = 0;
    let hDir = 1;
    if (hareReact) {
        const hp = hareReact.progress;
        if (hp < 0.5) {
            const u = hp / 0.5;
            hopOffsetX = -Math.round(easeInOutQuad(u) * 16);
            hopOffsetY = -Math.round(Math.sin(u * Math.PI) * 12);
            hDir = -1;
        } else {
            const u = (hp - 0.5) / 0.5;
            hopOffsetX = -Math.round((1 - easeInOutQuad(u)) * 16);
            hopOffsetY = -Math.round(Math.sin(u * Math.PI) * 12);
            hDir = 1;
        }
    }

    const curHx = hareHomeX + hopOffsetX;
    const hareGroundY = getGroundY(curHx, 'arctic-tundra', pw, ph);
    const curHy = hareGroundY + hopOffsetY;
    const earFlick = !hareReact && (time % 6100) > 5880 ? -1 : 0;
    const noseWiggle = Math.sin(time * 0.01) > 0.3 ? -1 : 0;

    pRect(curHx - 7, hareGroundY - 1, 14, 2, 'rgba(56, 189, 248, 0.30)');
    if (hareReact && Math.abs(hareReact.progress - 0.5) < 0.08) {
        pRect(curHx - 9, hareGroundY - 3, 3, 2, '#ffffff');
        pRect(curHx + 6, hareGroundY - 3, 3, 2, '#e0f2fe');
    }

    const hRect = (ox, oy, w, h, col) => pRect(hDir >= 0 ? curHx + ox : curHx - ox - w, curHy + oy, w, h, col);
    hRect(-9, -6, 4, 4, '#e0f2fe');
    hRect(-7, -10, 13, 9, '#ffffff');
    hRect(-5, -4, 9, 4, '#bae6fd');
    hRect(1, -3, 7, 3, '#f8fafc');
    hRect(1, -14, 8, 7, '#ffffff');
    hRect(2, -19, 3, 6, '#f8fafc');
    hRect(6, -19 + earFlick, 3, 6, '#f8fafc');
    hRect(2, -21, 3, 2, '#0f172a');
    hRect(6, -21 + earFlick, 3, 2, '#0f172a');
    hRect(5, -12, 2, 2, '#0f172a');
    hRect(5, -12, 1, 1, '#ffffff');
    hRect(8, -10 + noseWiggle, 2, 2, '#fda4af');

    registerAmbientHitbox('arctic_hare', curHx - 12, curHy - 21, curHx + 13, curHy + 4, 2);
}

function drawHabitatAmbientWildlife(sceneProfile, time) {
    if (sceneProfile === 'meadow') drawMeadowHoneyBear(time);
    else if (sceneProfile === 'betta-aquarium') drawBettaTankCritters(time);
    else if (sceneProfile === 'wetland') drawWetlandCritters(time);
    else if (sceneProfile === 'botanical') drawBotanicalCritters(time);
    else if (sceneProfile === 'reef') drawReefCritters(time);
    else if (sceneProfile === 'koi-pond') drawKoiPondCritters(time);
    else if (sceneProfile === 'arctic-tundra') drawArcticAlwaysPresentWildlife(time);
    drawAmbientTouchPulses(time);
}

// ============================================================================
// BÖLÜM SONU: BİYOMLARIN EV SAHİBİ DURGUN VE ROAMING CANLILARI
// BÖLÜM BAŞI: AÇILIP KAPANABİLEN KUTUP NOEL HARİKALAR DİYARI
// ============================================================================

function drawArcticChristmasSky(time) {
    // Widget çakışmasını %100 önleyen açık gökyüzü koridoru (Üst bar 0..28 ve Saat arasından süzülür)
    const travelW = pw + 260;
    const leadX = Math.round(((time * 0.017) % travelW) - 130);
    const sleighY = Math.max(52, Math.round(ph * 0.17 + Math.sin(time * 0.0018) * 3.5));
    if (leadX < -120 || leadX > pw + 110) return;

    const santaReact = getAmbientReaction('arctic_santa', time);
    const extraDust = santaReact ? 12 : 0;

    // 1. Parlayan altın & buz-mavisi sihirli yıldız tozu şeridi
    for (let st = 0; st < 18 + extraDust; st++) {
        const sx = leadX - 36 - st * 4;
        const sy = sleighY + 6 + Math.round(Math.sin(time * 0.008 + st * 0.85) * (santaReact ? 5 : 3.2)) + (st % 3);
        const alpha = Math.max(0.10, (santaReact ? 1.0 : 0.90) - st * 0.036).toFixed(2);
        pRect(sx, sy, st % 3 === 0 ? 2 : 1, st % 5 === 0 ? 2 : 1, st % 2 === 0 ? `rgba(253, 224, 71, ${alpha})` : `rgba(186, 230, 253, ${alpha})`);
    }

    // 2. Görkemli Yakut-Kırmızısı & Altın İşlemeli Noel Kızağı (~36x20px) + Heybetli Noel Baba
    const slX = leadX - 28;
    pRect(slX - 10, sleighY + 7, 29, 2, '#f59e0b');
    pRect(slX - 9, sleighY + 7, 27, 1, '#fef08a');
    pRect(slX + 18, sleighY + 5, 3, 2, '#facc15');
    pRect(slX + 19, sleighY + 3, 2, 2, '#fef08a');
    pRect(slX - 6, sleighY + 3, 2, 4, '#b45309');
    pRect(slX + 10, sleighY + 3, 2, 4, '#b45309');

    pRect(slX - 10, sleighY - 3, 26, 7, '#b91c1c');
    pRect(slX - 12, sleighY - 6, 10, 4, '#dc2626');
    pRect(slX + 8, sleighY - 5, 9, 7, '#dc2626');
    pRect(slX - 11, sleighY - 6, 26, 1, '#facc15');
    pRect(slX - 9, sleighY, 24, 1, '#facc15');

    pRect(slX - 8, sleighY - 12, 10, 9, '#15803d');
    pRect(slX - 7, sleighY - 13, 8, 3, '#16a34a');
    pRect(slX - 9, sleighY - 9, 4, 4, '#38bdf8');
    pRect(slX - 8, sleighY - 9, 2, 4, '#fde047');
    pRect(slX - 4, sleighY - 14, 4, 3, '#f59e0b');
    pRect(slX - 6, sleighY - 15, 2, 3, '#ef4444');

    const waveArm = santaReact
        ? Math.round(Math.sin(time * 0.025) * 3)
        : Math.round(Math.sin(time * 0.008) * 1.5);
    pRect(slX + 2, sleighY - 11, 8, 8, '#dc2626');
    pRect(slX + 2, sleighY - 6, 8, 2, '#0f172a');
    pRect(slX + 6, sleighY - 6, 2, 2, '#facc15');
    pRect(slX + 2, sleighY - 4, 8, 1, '#ffffff');
    pRect(slX + 10, sleighY - 10 + waveArm, 3, 2, '#dc2626');
    pRect(slX + 12, sleighY - 11 + waveArm, 2, 2, '#ffffff');
    pRect(slX + 3, sleighY - 15, 6, 5, '#fed7aa');
    pRect(slX + 5, sleighY - 14, 1, 1, '#0f172a');
    pRect(slX + 7, sleighY - 14, 2, 1, '#fb7185');
    pRect(slX + 3, sleighY - 12, 8, 5, '#ffffff');
    pRect(slX + 4, sleighY - 9, 6, 3, '#f1f5f9');
    pRect(slX + 2, sleighY - 17, 7, 2, '#ffffff');
    pRect(slX + 3, sleighY - 19, 5, 2, '#dc2626');
    pRect(slX + 1, sleighY - 19, 3, 2, '#dc2626');
    pRect(slX - 1, sleighY - 18, 2, 2, '#ffffff');

    // Altın koşum dizginleri kızaktan öndeki geyiğin tasmasına kadar uzanır
    pRect(slX + 16, sleighY - 2, 61, 1, 'rgba(253, 224, 71, 0.78)');

    // 3. 4 Doru Ren Geyiği (Arka ve ön bacaklar, net burun & göz, boynuz & çıngıraklı tasma; öndeki Rudolph!)
    for (let r = 0; r < 4; r++) {
        const rx = slX + 24 + r * 16;
        const step = Math.round(Math.sin(time * 0.012 + r * 1.3) * 2.2);
        const bob = Math.round(Math.sin(time * 0.008 + r * 0.9) * 1.1);
        const ry = sleighY - 1 + bob;

        pRect(rx - 3 - Math.round(step * 0.7), ry + 2, 2, 4, '#290f02');
        pRect(rx + 1 + Math.round(step * 0.7), ry + 2, 2, 4, '#290f02');
        pRect(rx - 4 + step, ry + 2, 2, 4, '#451a03');
        pRect(rx + 2 - step, ry + 2, 2, 4, '#451a03');
        pRect(rx - 5, ry - 3, 10, 5, '#78350f');
        pRect(rx - 4, ry - 3, 7, 2, '#b45309');
        pRect(rx - 6, ry - 2, 2, 2, '#ffffff');
        pRect(rx + 3, ry - 7, 3, 5, '#92400e');
        pRect(rx + 5, ry - 5, 2, 3, '#d97706');
        pRect(rx + 4, ry - 9, 5, 3, '#78350f');
        pRect(rx + 9, ry - 8, 1, 2, '#92400e');
        pRect(rx + 6, ry - 8, 1, 1, '#09090b');
        pRect(rx + 3, ry - 5, 3, 1, '#ef4444');
        pRect(rx + 5, ry - 4, 1, 1, '#facc15');
        pRect(rx + 3, ry - 12, 1, 3, '#d97706');
        pRect(rx + 4, ry - 13, 2, 2, '#fbbf24');
        pRect(rx + 2, ry - 11, 2, 1, '#fde047');
        if (r === 3) {
            const pulseGlow = santaReact ? 0.72 : (Math.sin(time * 0.01) > 0 ? 0.45 : 0.28);
            pRect(rx + 7, ry - 10, 5, 5, `rgba(239, 68, 68, ${pulseGlow})`);
            pRect(rx + 8, ry - 9, 3, 3, 'rgba(254, 202, 202, 0.55)');
            pRect(rx + 9, ry - 8, 2, 2, '#ef4444');
        }
    }

    registerAmbientHitbox('arctic_santa', slX - 14, sleighY - 22, slX + 86, sleighY + 11, 4);
}

function drawArcticCandyCane(x, baseY, height, curveDir) {
    for (let y = 0; y < height - 4; y++) {
        const col = Math.floor(y / 2) % 2 === 0 ? '#ffffff' : '#ef4444';
        pRect(x, baseY - y, 3, 1, col);
    }
    const topY = baseY - height + 4;
    pRect(x + curveDir, topY - 2, 3, 2, '#ef4444');
    pRect(x + curveDir * 3, topY - 4, 4, 3, '#ffffff');
    pRect(x + curveDir * 6, topY - 3, 3, 3, '#ef4444');
    pRect(x + curveDir * 7, topY, 3, 3, '#ffffff');
    pRect(x + curveDir * 7, topY + 3, 2, 1, '#ef4444');
}

function drawArcticGiftBox(x, baseY, w, h, boxCol, ribbonCol, shadowCol) {
    pRect(x - 1, baseY, w + 2, 2, 'rgba(7, 13, 25, 0.36)');
    pRect(x, baseY - h, w, h, boxCol);
    pRect(x + w - 2, baseY - h, 2, h, shadowCol);
    pRect(x - 1, baseY - h, w + 2, 2, boxCol);
    const midX = x + Math.floor(w * 0.5) - 1;
    const midY = baseY - Math.ceil(h * 0.5);
    pRect(midX, baseY - h, 2, h, ribbonCol);
    pRect(x, midY, w, 2, ribbonCol);
    pRect(midX - 2, baseY - h - 2, 2, 2, ribbonCol);
    pRect(midX + 2, baseY - h - 2, 2, 2, ribbonCol);
}

function drawArcticChristmasElf(elfId, x, baseY, hatCol, tunicCol, dir, phaseOff, holdLantern, time) {
    const react = getAmbientReaction(elfId, time);
    const phase = ((time + Math.round(phaseOff * 14000)) % 14000) / 14000;
    const cheerWave = react || (phase > 0.65 && phase < 0.88);
    const hop = react
        ? -Math.round(Math.abs(Math.sin(react.progress * Math.PI * 2)) * 6)
        : (cheerWave && Math.sin(time * 0.008) > 0.35 ? -1 : 0);
    const blink = !react && ((time + Math.round(phaseOff * 2000)) % 4900) > 4720;
    const waveOff = cheerWave ? Math.round(Math.sin(time * 0.014) * 2) : Math.round(Math.sin(time * 0.0025 + phaseOff) * 0.6);
    const by = baseY + hop;

    pRect(x - 5, baseY, 11, 2, 'rgba(7, 13, 25, 0.35)');
    pRect(x - 3, by - 2, 3, 2, '#1e293b');
    pRect(x + 1, by - 2, 3, 2, '#1e293b');
    pRect(x - 4, by - 1, 2, 1, '#facc15');
    pRect(x + 3, by - 1, 2, 1, '#facc15');
    pRect(x - 3, by - 4, 2, 2, hatCol);
    pRect(x + 1, by - 4, 2, 2, '#ffffff');

    pRect(x - 4, by - 11, 9, 7, tunicCol);
    pRect(x - 5, by - 5, 11, 1, '#ffffff');
    pRect(x - 4, by - 8, 9, 1, '#0f172a');
    pRect(x - 1, by - 8, 3, 2, '#facc15');

    pRect(x + dir * 5, by - 10 + waveOff, 2, 4, tunicCol);
    pRect(x + dir * 6, by - 7 + waveOff, 2, 2, '#fed7aa');
    if (holdLantern) {
        pRect(x + dir * 6, by - 5 + waveOff, 3, 4, '#451a03');
        pRect(x + dir * 6, by - 4 + waveOff, 2, 2, '#fde047');
        pRect(x + dir * 5, by - 6 + waveOff, 5, 6, react ? 'rgba(253, 224, 71, 0.45)' : 'rgba(253, 224, 71, 0.25)');
    }
    if (react) {
        pRect(x - 6, by - 24, 2, 2, '#fde047');
        pRect(x + 6, by - 23, 2, 2, '#ffffff');
    }

    pRect(x - 4, by - 16, 9, 5, '#fed7aa');
    pRect(x - 5, by - 15, 1, 2, '#fdba74');
    pRect(x + 5, by - 15, 1, 2, '#fdba74');
    pRect(x - 2, by - 14, 1, 2, blink ? '#d97706' : '#0f172a');
    pRect(x + 2, by - 14, 1, 2, blink ? '#d97706' : '#0f172a');
    pRect(x - 1, by - 12, 3, 1, '#fb7185');

    pRect(x - 5, by - 17, 11, 2, '#ffffff');
    pRect(x - 3, by - 20, 7, 3, hatCol);
    pRect(x - 2, by - 22, 4, 2, hatCol);
    pRect(x - dir * 3, by - 22, 2, 2, hatCol);
    pRect(x - dir * 4, by - 21, 2, 2, '#ffffff');

    registerAmbientHitbox(elfId, x - 8, baseY - 24, x + 9, baseY + 3, 2);
}

function drawArcticSnowman(x, groundY, time) {
    const snowReact = getAmbientReaction('arctic_snowman', time);
    const scarfFlutter = Math.round(Math.sin(time * 0.0032) * 1);
    const armWave = snowReact ? Math.round(Math.sin(snowReact.progress * Math.PI * 6) * 2) : (Math.sin(time * 0.0024) > 0.5 ? -1 : 0);
    const hatLift = snowReact ? -Math.round(Math.sin(snowReact.progress * Math.PI) * 5) : 0;

    pRect(x - 9, groundY - 1, 19, 3, 'rgba(56, 189, 248, 0.28)');
    pRect(x - 8, groundY - 9, 17, 9, '#f8fafc');
    pRect(x - 7, groundY - 10, 15, 2, '#ffffff');
    pRect(x - 8, groundY - 4, 17, 4, '#bae6fd');
    pRect(x - 6, groundY - 17, 13, 8, '#ffffff');
    pRect(x - 5, groundY - 15, 2, 4, '#e0f2fe');
    pRect(x, groundY - 15, 2, 1, '#0f172a');
    pRect(x, groundY - 12, 2, 1, '#0f172a');
    pRect(x - 10, groundY - 16 + armWave, 4, 1, '#451a03');
    pRect(x - 11, groundY - 17 + armWave, 2, 1, '#78350f');
    pRect(x + 7, groundY - 16 - armWave, 4, 1, '#451a03');
    pRect(x + 10, groundY - 17 - armWave, 2, 1, '#78350f');

    pRect(x - 5, groundY - 18, 11, 2, '#dc2626');
    pRect(x + 3, groundY - 16 + scarfFlutter, 3, 5, '#ef4444');
    pRect(x + 4, groundY - 11 + scarfFlutter, 2, 2, '#b91c1c');

    pRect(x - 5, groundY - 24, 10, 6, '#ffffff');
    pRect(x - 3, groundY - 23, 1, 1, '#0f172a');
    pRect(x + 2, groundY - 23, 1, 1, '#0f172a');
    pRect(x, groundY - 21, 5, 2, '#f97316');
    pRect(x + 3, groundY - 21, 2, 1, '#fbbf24');
    pRect(x - 2, groundY - 19, 4, 1, '#0f172a');

    pRect(x - 6, groundY - 25 + hatLift, 13, 2, '#0f172a');
    pRect(x - 4, groundY - 30 + hatLift, 9, 5, '#1e293b');
    pRect(x - 4, groundY - 26 + hatLift, 9, 1, '#ef4444');

    if (snowReact) {
        pRect(x - 11, groundY - 28, 2, 2, '#e0f2fe');
        pRect(x + 9, groundY - 27, 2, 2, '#ffffff');
    }

    registerAmbientHitbox('arctic_snowman', x - 13, groundY - 33, x + 14, groundY + 3, 2);
}

function drawHeroChristmasTree(cx, baseY, h, time) {
    pRect(cx - 14, baseY - 1, 29, 3, 'rgba(7, 13, 25, 0.45)');
    pRect(cx - 3, baseY - 8, 7, 9, '#3b1806');
    pRect(cx - 1, baseY - 8, 2, 8, '#78350f');

    const bulbCols = ['#ef4444', '#fde047', '#38bdf8', '#f472b6', '#ffffff'];
    const tiers = 7;
    for (let t = 0; t < tiers; t++) {
        const prog = t / tiers;
        const ty = baseY - 6 - Math.round(prog * (h - 9));
        const th = Math.max(5, Math.round((h / tiers) * 1.45));
        const maxW = Math.round(4 + (1 - prog * 0.84) * (h * 0.34));
        for (let dy = 0; dy < th; dy++) {
            const w = Math.max(1, Math.round((dy / th) * maxW));
            const py = ty - th + dy;
            pRect(cx - w, py, w * 2 + 1, 1, dy > th - 2 ? '#052e16' : '#14532d');
            pRect(cx - Math.max(1, Math.floor(w * 0.65)), py, Math.max(2, w), 1, '#15803d');
            if (dy === 0 || (dy === 1 && w > 4)) {
                pRect(cx - w, py, 2, 1, '#e0f2fe');
                pRect(cx + w - 1, py, 2, 1, '#bae6fd');
            }
        }
        if (t < tiers - 1) {
            const garY = ty - 2;
            const garW = Math.max(2, maxW - 3);
            pRect(cx - garW, garY, garW * 2, 1, '#f59e0b');
            const cIdx1 = (t + Math.floor(time * 0.0022)) % bulbCols.length;
            const cIdx2 = (t + 2 + Math.floor(time * 0.0022)) % bulbCols.length;
            pRect(cx - Math.round(garW * 0.6), garY - 1, 2, 2, bulbCols[cIdx1]);
            pRect(cx + Math.round(garW * 0.5), garY + 1, 2, 2, bulbCols[cIdx2]);
        }
    }

    const starY = baseY - h - 2;
    const starAura = Math.sin(time * 0.004) > 0 ? 0.42 : 0.24;
    pRect(cx - 5, starY - 5, 11, 11, `rgba(253, 224, 71, ${starAura})`);
    pRect(cx - 3, starY - 1, 7, 2, '#facc15');
    pRect(cx - 1, starY - 3, 3, 6, '#facc15');
    pRect(cx - 2, starY - 2, 5, 4, '#fde047');
    pRect(cx, starY - 1, 1, 2, '#ffffff');
}

function drawArcticChristmasGround(time) {
    const ledges = getArcticLedges(pw, ph);
    const cabX = Math.round(pw * 0.73);
    const cabY = ledges[5].yFn(cabX) + 1;
    const cabPineX = Math.round(pw * 0.66);
    const cabPineY = ledges[5].yFn(cabPineX) + 1;
    const bulbPalette = ['#ef4444', '#fde047', '#38bdf8', '#22c55e'];

    // 1. Kulübe Çatı Işıkları, Kızıl Kurdeleli Kapı Çelengi & Yanındaki Yılbaşı Çamı Süsleri
    pRect(cabPineX - 3, cabPineY - 38, 7, 5, 'rgba(253, 224, 71, 0.35)');
    pRect(cabPineX - 2, cabPineY - 36, 5, 2, '#fde047');
    pRect(cabPineX, cabPineY - 38, 1, 5, '#ffffff');
    [
        { dx: -3, dy: -28, phase: 0 },
        { dx: 3, dy: -25, phase: 1 },
        { dx: -5, dy: -19, phase: 2 },
        { dx: 1, dy: -17, phase: 3 },
        { dx: 6, dy: -15, phase: 4 },
        { dx: -4, dy: -11, phase: 5 },
        { dx: 4, dy: -10, phase: 6 }
    ].forEach((o) => {
        const idx = (o.phase + Math.floor(time * 0.0022)) % bulbPalette.length;
        pRect(cabPineX + o.dx, cabPineY + o.dy, 2, 2, bulbPalette[idx]);
    });

    pRect(cabX - 8, cabY - 10, 5, 5, '#15803d');
    pRect(cabX - 7, cabY - 9, 3, 3, '#271105');
    pRect(cabX - 7, cabY - 10, 3, 1, '#ef4444');
    for (let lx = -15; lx <= 14; lx += 4) {
        const idx = (Math.abs(lx) + Math.floor(time * 0.0026)) % bulbPalette.length;
        const slopeOff = Math.round(Math.abs(lx) * 0.52);
        pRect(cabX + lx, cabY - 22 + slopeOff, 2, 2, bulbPalette[idx]);
    }
    pRect(cabX - 15, cabY - 2, 31, 3, 'rgba(253, 224, 71, 0.14)');

    // 2. Vadi Ön Planda 56px Görkemli Süslenmiş Noel Ağacı
    const heroTreeX = getRightSafeX(0.66);
    const heroTreeY = getGroundY(heroTreeX, 'arctic-tundra', pw, ph) + 1;
    drawHeroChristmasTree(heroTreeX, heroTreeY, 56, time);

    // 3. Sol-Orta Açık Vadi Karında Kırmızı Atkılı Neşeli Kardan Adam (~26px)
    const snowX = getLeftSafeX(0.32);
    const snowY = getGroundY(snowX, 'arctic-tundra', pw, ph) + 1;
    drawArcticSnowman(snowX, snowY, time);

    // 4. 5 Kalın, Net Kırmızı-Beyaz Baston Şeker Kamışı (Candy Canes, 19–23px)
    drawArcticCandyCane(Math.round(pw * 0.18), ledges[1].yFn(Math.round(pw * 0.18)), 20, 1);
    drawArcticCandyCane(Math.round(pw * 0.34), ledges[2].yFn(Math.round(pw * 0.34)), 20, -1);
    drawArcticCandyCane(cabX + 16, ledges[5].yFn(cabX + 16), 19, -1);
    const cLeftX = snowX - 36;
    drawArcticCandyCane(cLeftX, getGroundY(cLeftX, 'arctic-tundra', pw, ph), 22, 1);
    const cRightX = heroTreeX + 20;
    drawArcticCandyCane(cRightX, getGroundY(cRightX, 'arctic-tundra', pw, ph), 23, -1);

    // 5. Dev Paketli Renkli Yılbaşı Hediye Kutuları
    drawArcticGiftBox(heroTreeX - 14, heroTreeY, 10, 9, '#dc2626', '#fde047', '#991b1b');
    drawArcticGiftBox(heroTreeX + 4, heroTreeY, 9, 8, '#2563eb', '#ffffff', '#1e40af');
    drawArcticGiftBox(heroTreeX - 4, heroTreeY - 2, 8, 7, '#16a34a', '#ef4444', '#14532d');
    drawArcticGiftBox(cabX + 9, cabY, 8, 7, '#a855f7', '#fde047', '#6b21a8');
    drawArcticGiftBox(snowX + 12, snowY, 8, 7, '#ef4444', '#ffffff', '#991b1b');

    // 6. 3 İfadeli Büyük Noel Elfi (Tıklamaya zıplayarak tepki verir)
    const elf1X = Math.round(pw * 0.785);
    drawArcticChristmasElf('arctic_elf_1', elf1X, ledges[5].yFn(elf1X) + 1, '#dc2626', '#16a34a', -1, 0.1, true, time);
    const elf2X = heroTreeX - 24;
    drawArcticChristmasElf('arctic_elf_2', elf2X, getGroundY(elf2X, 'arctic-tundra', pw, ph) + 1, '#16a34a', '#dc2626', 1, 0.4, false, time);
    const elf3X = snowX - 24;
    if (elf3X > 136) {
        drawArcticChristmasElf('arctic_elf_3', elf3X, getGroundY(elf3X, 'arctic-tundra', pw, ph) + 1, '#2563eb', '#15803d', 1, 0.7, false, time);
    }
}

// ============================================================================
// BÖLÜM SONU: AÇILIP KAPANABİLEN KUTUP NOEL HARİKALAR DİYARI
// ============================================================================


// ============================================================================
// MODULE: js/habitat-interactions.js
// ============================================================================




/* HABITAT INTERACTIONS — user input that spawns food/stimuli or triggers direct ambient wildlife reactions. */

function getCanvasLogicalPoint(e) {
    const rect = typeof canvas.getBoundingClientRect === 'function' ? canvas.getBoundingClientRect() : null;
    if (rect && rect.width >= Math.max(120, pw) && rect.height >= Math.max(80, ph)) {
        return {
            px: (e.clientX - rect.left) * (pw / rect.width),
            py: (e.clientY - rect.top) * (ph / rect.height)
        };
    }
    return {
        px: e.clientX / PIXEL_SCALE,
        py: e.clientY / PIXEL_SCALE
    };
}

// ============================================================================
// BÖLÜM BAŞI: SAHNEYE TIKLAYARAK YEM VE UYARAN BIRAKMA YA DA CANLIYA DOKUNMA
// Her habitatın interactionProfile değeri doğru uyaran türünü belirler.
// ============================================================================

let lastPointerDownAt = 0;

canvas.addEventListener('pointermove', (e) => {
    if (!canvas || !canvas.style) return;
    const { px, py } = getCanvasLogicalPoint(e);
    const activeHabitat = HABITATS[currentHabitatIdx];
    canvas.style.cursor = (activeHabitat && hasAmbientWildlifeAt(activeHabitat.sceneProfile, px, py))
        ? 'pointer'
        : '';
});

function handleCanvasPress(e) {
    if (typeof e.button === 'number' && e.button !== 0) return;
    const now = Date.now();
    if (e && e.type === 'pointerdown') {
        lastPointerDownAt = now;
    } else if (e && e.type === 'mousedown' && now - lastPointerDownAt < 400) {
        return;
    }

    const { px, py } = getCanvasLogicalPoint(e);
    const activeHabitat = HABITATS[currentHabitatIdx];
    if (activeHabitat && tryInteractAmbientWildlife(activeHabitat.sceneProfile, px, py)) {
        return;
    }
    const interactionProfile = activeHabitat.interactionProfile;

    if (interactionProfile === 'nectar') {
        for (let i = 0; i < 3; i++) {
            const offset = (i - 1) * (8 + Math.random() * 4);
            const bx = Math.max(14, Math.min(pw - 14, px + offset));
            const groundY = getGroundY(bx, 'meadow', pw, ph);
            const naturalTopY = groundY - (14 + i * 6 + Math.floor(Math.random() * 5));
            const targetY = py >= groundY - 40
                ? Math.max(groundY - 38, Math.min(groundY - 10, py + (i - 1) * 3))
                : naturalTopY;
            const startsInAir = py < targetY - 4;
            stimuli.push({
                type: 'honey_nectar',
                x: bx,
                y: startsInAir ? py : targetY,
                baseY: startsInAir ? py : targetY,
                targetY,
                vy: 0.45,
                landed: !startsInAir,
                variant: i % 3,
                phase: Math.random() * Math.PI * 2,
                ripple: 0,
                life: 260,
                claimedBy: null
            });
        }
    } else if (interactionProfile === 'blossom') {
        for (let i = 0; i < 2; i++) {
            const bx = Math.max(14, Math.min(pw - 14, px + (i - 0.5) * 12));
            const groundY = getGroundY(bx, 'botanical', pw, ph);
            const by = Math.max(12, Math.min(groundY - 2, py + (Math.random() - 0.5) * 8));
            stimuli.push({
                type: 'floating_blossom',
                x: bx,
                y: by,
                vx: (Math.random() - 0.5) * 0.08,
                vy: 0.14 + Math.random() * 0.06,
                landed: by >= groundY - 3,
                phase: Math.random() * Math.PI * 2,
                color: i === 0 ? '#f0abfc' : '#7dd3fc',
                petalShade: i === 0 ? '#c084fc' : '#38bdf8',
                core: '#fef08a',
                life: 280,
                claimedBy: null
            });
        }
    } else if (interactionProfile === 'bloodworm') {
        for (let i = 0; i < 3; i++) {
            const bx = Math.max(14, Math.min(pw - 14, px + (i - 1) * 7 + (Math.random() - 0.5) * 4));
            const by = Math.max(6, Math.min(ph - 16, py + (Math.random() - 0.5) * 6));
            stimuli.push({
                type: 'bloodworm',
                x: bx,
                y: by,
                vy: 0.14 + Math.random() * 0.05,
                landed: false,
                dir: Math.random() < 0.5 ? 1 : -1,
                phase: Math.random() * Math.PI * 2,
                life: 300,
                claimedBy: null
            });
        }
    } else if (interactionProfile === 'midge') {
        for (let i = 0; i < 3; i++) {
            const bx = Math.max(16, Math.min(pw - 16, px + (i - 1) * 8 + (Math.random() - 0.5) * 5));
            const by = Math.max(20, Math.min(ph - 22, py + (Math.random() - 0.5) * 10));
            const waterSurfaceY = Math.max(ph - 48, Math.min(ph - 10, by + 10));
            stimuli.push({
                type: 'midge',
                x: bx,
                y: by,
                baseX: bx,
                baseY: by,
                emergeY: waterSurfaceY,
                ripple: i === 1 ? 1 : 0,
                phase: Math.random() * Math.PI * 2,
                life: 250,
                claimedBy: null
            });
        }
    } else if (interactionProfile === 'plankton') {
        for (let i = 0; i < 2; i++) {
            const bx = Math.max(18, Math.min(pw - 18, px + (i - 0.5) * 14));
            const nx = bx / Math.max(1, pw);
            const sideMound = nx < 0.26 ? Math.pow((0.26 - nx) / 0.26, 1.5) * 34
                            : (nx > 0.74 ? Math.pow((nx - 0.74) / 0.26, 1.5) * 34 : 0);
            const maxDepthY = Math.round(getGroundY(bx, 'reef', pw, ph) - sideMound) - 10;
            const by = Math.max(14, Math.min(maxDepthY, py + (Math.random() - 0.5) * 10));
            stimuli.push({
                type: 'plankton_swarm',
                x: bx,
                y: by,
                phase: Math.random() * Math.PI * 2,
                life: 240,
                claimedBy: null
            });
        }
    } else if (interactionProfile === 'pellet') {
        for (let i = 0; i < 3; i++) {
            const rawX = Math.max(20, Math.min(pw - 24, px + (i - 1) * 6 + (Math.random() - 0.5) * 4));
            const nx = rawX / Math.max(1, pw);
            const maxWaterY = (nx <= 0.30 || nx >= 0.68)
                ? getGroundY(rawX, 'koi-pond', pw, ph) - 10
                : ph - 12;
            const rawY = Math.max(28, Math.min(maxWaterY, py + (Math.random() - 0.5) * 8));
            stimuli.push({
                type: 'koi_pellet',
                x: rawX,
                y: rawY,
                baseY: rawY,
                phase: Math.random() * Math.PI * 2,
                ripple: 1,
                life: 260,
                claimedBy: null
            });
        }
    } else if (interactionProfile === 'fruit') {
        // Spawn a trio of detailed pixel-art tropical fruits: Mango, Pink Guava & Golden Banana Cluster
        const kinds = ['mango', 'guava', 'banana'];
        for (let i = 0; i < 3; i++) {
            const offset = (i - 1) * 11;
            const fruitX = Math.max(14, Math.min(pw - 14, px + offset + (Math.random() - 0.5) * 3));
            const groundY = getGroundY(fruitX, 'rainforest', pw, ph);
            const rawY = Math.max(18, Math.min(groundY - 4, py + (Math.random() - 0.5) * 6));
            const isGroundFruit = rawY >= groundY - 22;
            stimuli.push({
                type: 'tropical_fruit',
                kind: kinds[i],
                x: fruitX,
                y: isGroundFruit ? groundY - 5 : rawY,
                baseY: isGroundFruit ? groundY - 5 : rawY,
                onGround: isGroundFruit,
                vineTopY: 4 + (i % 3) * 3,
                phase: Math.random() * Math.PI * 2,
                life: 300,
                claimedBy: null
            });
        }
    } else if (interactionProfile === 'cloudberry') {
        // Spawn Golden Arctic Cloudberries that fall and land onto the nearest snow platform below!
        for (let i = 0; i < 2; i++) {
            const bx = Math.max(12, Math.min(pw - 12, px + (i - 0.5) * 14));
            const landY = getArcticLandingY(bx, py, pw, ph);
            stimuli.push({
                type: 'cloudberry',
                x: bx,
                y: Math.min(py, landY - 12),
                targetY: landY - 2,
                vy: 0.4,
                landed: false,
                phase: Math.random() * Math.PI * 2,
                life: 360,
                claimedBy: null
            });
        }
    }
}

canvas.addEventListener('pointerdown', handleCanvasPress);
canvas.addEventListener('mousedown', handleCanvasPress);

document.addEventListener('pointerdown', (e) => {
    if (e.target === document.body || e.target === document.documentElement) {
        handleCanvasPress(e);
    }
});

// ============================================================================
// BÖLÜM SONU: SAHNEYE TIKLAYARAK YEM VE UYARAN BIRAKMA
// ============================================================================

// ============================================================================
// BÖLÜM BAŞI: YEM VE UYARANLARIN ANİMASYONU, ÇİZİMİ VE ÖMRÜ
// Bu fonksiyon her sahne karesinde çağrılır; süresi biten uyaranları da temizler.
// ============================================================================

function drawHabitatStimuli() {
    for (let i = stimuli.length - 1; i >= 0; i--) {
        const s = stimuli[i];
        s.life -= frameScale;

        if (s.type === 'tropical_fruit') {
            s.phase += 0.08 * frameScale;
            const groundY = getGroundY(s.x, 'rainforest', pw, ph);
            const onGround = Boolean(s.onGround) || s.baseY >= groundY - 18;
            const sway = onGround ? 0 : Math.sin(s.phase * 0.7) * 1.2;
            const fx = Math.round(s.x + sway);
            const fy = onGround
                ? groundY - 5
                : Math.round(s.baseY + Math.sin(s.phase) * 1.1);
            s.y = fy;

            if (onGround) {
                pRect(fx - 6, groundY - 1, 13, 2, 'rgba(2, 10, 10, 0.45)');
                pRect(fx - 6, groundY - 2, 13, 2, '#14532d');
                pRect(fx - 5, groundY - 3, 11, 1, '#16a34a');
            } else {
                const startY = s.vineTopY !== undefined ? s.vineTopY : 5;
                pRect(Math.round(s.x) - 1, startY - 1, 3, 2, '#321e17');
                const vineLen = Math.max(4, (fy - 4) - startY);
                for (let vy = 0; vy <= vineLen; vy += 2) {
                    const prog = vy / vineLen;
                    const vx = Math.round(s.x + sway * Math.pow(prog, 1.2));
                    const py = startY + vy;
                    pRect(vx, py, 1, 2, '#15803d');
                    if (vy > 6 && vy % 12 === 0 && vy < vineLen - 4) {
                        const lSide = (vy % 24 === 0) ? -1 : 1;
                        pRect(vx + lSide, py, 3 * lSide, 2, '#22c55e');
                    }
                }
            }

            const sparkX = fx + Math.round(Math.cos(s.phase * 1.4) * 6);
            const sparkY = fy + Math.round(Math.sin(s.phase * 1.4) * 4);
            pRect(sparkX, sparkY, 1, 1, 'rgba(254, 240, 138, 0.75)');

            if (s.kind === 'mango' || (!s.kind && i % 3 === 0)) {
                pRect(fx - 3, fy - 1, 7, 5, '#f97316');
                pRect(fx - 2, fy - 2, 5, 2, '#ef4444');
                pRect(fx - 2, fy + 2, 6, 2, '#facc15');
                pRect(fx + 2, fy + 1, 3, 2, '#fde047');
                pRect(fx - 2, fy - 1, 2, 1, 'rgba(255, 255, 255, 0.75)');
                pRect(fx - 1, fy - 4, 1, 2, '#78350f');
                pRect(fx - 4, fy - 4, 3, 2, '#16a34a');
                pRect(fx, fy - 4, 3, 2, '#22c55e');
                pRect(fx + 1, fy - 5, 2, 1, '#86efac');
            } else if (s.kind === 'guava' || (!s.kind && i % 3 === 1)) {
                pRect(fx - 4, fy + 1, 9, 2, '#16a34a');
                pRect(fx - 3, fy + 2, 7, 1, '#15803d');
                pRect(fx - 3, fy - 2, 7, 3, '#f43f5e');
                pRect(fx - 2, fy - 3, 5, 2, '#fb7185');
                pRect(fx - 2, fy - 1, 1, 1, '#fef08a');
                pRect(fx, fy - 2, 1, 1, '#1e293b');
                pRect(fx + 2, fy - 1, 1, 1, '#fef08a');
                pRect(fx - 1, fy, 1, 1, '#1e293b');
                pRect(fx - 2, fy - 3, 2, 1, '#ffe4e6');
            } else {
                pRect(fx - 3, fy - 3, 3, 2, '#65a30d');
                pRect(fx - 4, fy - 1, 3, 5, '#eab308');
                pRect(fx - 1, fy - 1, 3, 6, '#facc15');
                pRect(fx + 2, fy - 1, 3, 5, '#fde047');
                pRect(fx, fy, 1, 3, '#fef9c3');
                pRect(fx - 3, fy + 4, 2, 1, '#78350f');
                pRect(fx, fy + 5, 2, 1, '#78350f');
                pRect(fx + 3, fy + 4, 2, 1, '#78350f');
            }

        } else if (s.type === 'cloudberry') {
            if (!s.landed) {
                s.vy = Math.min(2.2, s.vy + 0.08 * frameScale);
                s.y += s.vy * frameScale;
                if (s.y >= s.targetY) {
                    s.y = s.targetY;
                    s.landed = true;
                }
            }
            s.phase += 0.09 * frameScale;
            const bx = Math.round(s.x);
            const by = Math.round(s.y);

            if (s.landed) {
                pRect(bx - 4, by + 1, 9, 2, 'rgba(15, 23, 42, 0.32)');
                pRect(bx - 3, by + 1, 7, 1, '#bae6fd');
                pRect(bx, by - 1, 1, 2, '#451a03');
                pRect(bx - 4, by, 3, 1, '#14532d');
                pRect(bx + 2, by, 3, 1, '#14532d');
                pRect(bx - 3, by - 1, 7, 1, '#15803d');
            } else {
                pRect(bx - 2, by, 5, 1, '#15803d');
                pRect(bx, by - 6, 1, 1, 'rgba(254, 240, 138, 0.85)');
            }

            pRect(bx - 3, by - 3, 7, 2, '#d97706');
            pRect(bx - 2, by - 4, 5, 3, '#f59e0b');
            pRect(bx - 2, by - 3, 2, 2, '#fbbf24');
            pRect(bx + 1, by - 3, 2, 2, '#fbbf24');
            pRect(bx - 1, by - 5, 3, 2, '#fde047');
            pRect(bx - 1, by - 4, 1, 1, '#fef9c3');
            pRect(bx + 1, by - 4, 1, 1, '#fef9c3');

        } else if (s.type === 'honey_nectar') {
            const groundY = getGroundY(s.x, 'meadow', pw, ph);
            const restY = s.targetY !== undefined
                ? Math.min(s.targetY, groundY - 10)
                : Math.min(s.baseY, groundY - 12);

            if (s.landed === false) {
                s.vy = Math.min(1.8, (s.vy || 0.45) + 0.06 * frameScale);
                s.baseY += s.vy * frameScale;
                if (s.baseY >= restY) {
                    s.baseY = restY;
                    s.landed = true;
                }
                s.y = s.baseY;
                const dx = Math.round(s.x);
                const dy = Math.round(s.y);
                pRect(dx, dy - 3, 1, 1, 'rgba(254, 240, 138, 0.85)');
                pRect(dx - 1, dy - 1, 3, 3, '#f59e0b');
                pRect(dx, dy - 2, 1, 4, '#fbbf24');
                pRect(dx, dy - 1, 1, 2, '#fef9c3');
                pRect(dx - 1, groundY - 2, 3, 2, '#15803d');
            } else {
                s.phase += 0.10 * frameScale;
                const sway = Math.sin(s.phase * 0.7) * 1.4;
                const cupX = Math.round(s.x + sway);
                const cupY = Math.round(restY + Math.sin(s.phase) * 0.5);
                s.y = cupY;

                pRect(s.x - 2, groundY, 5, 2, 'rgba(2, 10, 14, 0.35)');
                pRect(s.x - 2, groundY - 1, 5, 2, '#14532d');
                pRect(s.x - 3, groundY - 2, 2, 1, '#16a34a');
                pRect(s.x + 2, groundY - 2, 2, 1, '#16a34a');

                const stemH = Math.max(4, groundY - cupY);
                for (let sy = 1; sy < stemH; sy++) {
                    const prog = sy / stemH;
                    const sx = Math.round(s.x + sway * Math.pow(prog, 1.2));
                    const py = groundY - sy;
                    pRect(sx, py, 1, 1, '#15803d');
                    if (sy === Math.floor(stemH * 0.45) || sy === Math.floor(stemH * 0.72)) {
                        const lDir = sy % 2 === 0 ? -1 : 1;
                        pRect(sx + lDir, py, 2 * lDir, 1, '#22c55e');
                    }
                }

                const petalOuter = s.variant === 1 ? '#fb7185' : '#f59e0b';
                const petalInner = s.variant === 1 ? '#fda4af' : '#fbbf24';
                pRect(cupX - 1, cupY + 2, 3, 1, '#15803d');
                pRect(cupX - 2, cupY + 1, 5, 1, '#22c55e');
                pRect(cupX - 3, cupY, 7, 1, petalOuter);
                pRect(cupX - 2, cupY - 1, 5, 2, petalInner);
                pRect(cupX - 1, cupY - 2, 3, 2, '#fde047');
                pRect(cupX, cupY - 2, 1, 1, '#ffffff');

                for (let m = 0; m < 3; m++) {
                    const a = s.phase * 0.9 + (m * Math.PI * 2) / 3;
                    const mx = cupX + Math.round(Math.cos(a) * 4);
                    const my = cupY - 2 + Math.round(Math.sin(a) * 2.5);
                    pRect(mx, my, 1, 1, 'rgba(254, 240, 138, 0.82)');
                }
            }

        } else if (s.type === 'floating_blossom') {
            s.phase += 0.08 * frameScale;
            const groundY = getGroundY(s.x, 'botanical', pw, ph);

            if (!s.landed) {
                s.x += (s.vx + Math.sin(s.phase) * 0.16) * frameScale;
                s.x = Math.max(10, Math.min(pw - 10, s.x));
                s.y += (Math.max(0.10, s.vy) + Math.cos(s.phase * 0.7) * 0.04) * frameScale;
                if (s.y >= groundY - 2) {
                    s.y = groundY - 2;
                    s.landed = true;
                }
            } else {
                s.y = groundY - 2;
            }

            const bx = Math.round(s.x);
            const by = Math.round(s.y);
            const shade = s.petalShade || '#c084fc';

            if (s.landed) {
                pRect(bx - 4, groundY, 9, 2, 'rgba(2, 8, 16, 0.38)');
                pRect(bx - 3, by + 1, 7, 1, '#15803d');
                pRect(bx - 4, by, 2, 1, '#22c55e');
                pRect(bx + 3, by, 2, 1, '#22c55e');
            } else {
                pRect(bx, by + 2, 1, 2, '#15803d');
                pRect(bx - 2, by + 2, 2, 1, '#22c55e');
            }

            for (let p = 0; p < 5; p++) {
                const ang = (s.landed ? 0.2 : s.phase * 0.35) + (p * Math.PI * 2) / 5;
                const px = Math.round(bx + Math.cos(ang) * 2.6);
                const py = Math.round(by + Math.sin(ang) * (s.landed ? 1.6 : 2.2));
                pRect(px, py, 2, 2, p % 2 === 0 ? s.color : shade);
            }
            pRect(bx - 1, by - 1, 3, 2, s.color);
            pRect(bx, by - 1, 2, 2, s.core);
            pRect(bx, by - 1, 1, 1, '#ffffff');
            pRect(bx + Math.sin(s.phase * 1.8) * 3.5, by - 3, 1, 1, 'rgba(254, 240, 138, 0.75)');

        } else if (s.type === 'bloodworm') {
            const nx = s.x / Math.max(1, pw);
            const floorY = Math.abs(nx - 0.50) < 0.085
                ? ph - 5 - Math.round(Math.cos((nx - 0.50) * 18) * 2)
                : Math.round(ph - 4 - Math.pow(Math.abs(nx - 0.50) * 1.95, 1.45) * 18 - Math.sin(s.x * 0.04) * 2);

            if (!s.landed) {
                s.phase += 0.20 * frameScale;
                s.y += s.vy * 0.48 * frameScale;
                s.x += Math.sin(s.phase * 0.7) * 0.08 * frameScale;
                if (s.y >= floorY - 3) {
                    s.y = floorY - 2;
                    s.landed = true;
                }
                for (let seg = 0; seg < 7; seg++) {
                    const wave = Math.sin(s.phase + seg * 0.75) * 1.8;
                    const wx = Math.round(s.x + wave);
                    const wy = Math.round(s.y + seg * 0.85 - 2);
                    const col = seg === 0 ? '#4c0519' : (seg % 2 === 0 ? '#e11d48' : '#9f1239');
                    pRect(wx, wy, 2, 1, col);
                    if (seg === 2 || seg === 4) {
                        pRect(wx, wy, 1, 1, '#fda4af');
                    }
                }
            } else {
                s.phase += 0.10 * frameScale;
                s.y = floorY - 2;
                const dir = s.dir || 1;
                pRect(s.x - 3, floorY, 7, 1, 'rgba(2, 8, 16, 0.42)');
                for (let seg = 0; seg < 7; seg++) {
                    const sx = Math.round(s.x + (seg - 3) * dir);
                    const arch = Math.round(Math.sin(s.phase + seg * 0.8) * 0.8);
                    const sy = Math.round(floorY - 2 + arch);
                    const col = seg === 0 ? '#4c0519' : (seg % 2 === 0 ? '#e11d48' : '#9f1239');
                    pRect(sx, sy, 1, 2, col);
                    if (seg === 3) pRect(sx, sy, 1, 1, '#fda4af');
                }
            }

        } else if (s.type === 'midge') {
            s.phase += 0.24 * frameScale;
            s.x = s.baseX + Math.sin(s.phase) * 3.8;
            s.y = s.baseY + Math.sin(s.phase * 2) * 1.8;
            const mx = Math.round(s.x);
            const my = Math.round(s.y);
            const wingFlutter = Math.sin(s.phase * 3.5) > 0 ? -1 : 0;

            if (s.ripple > 0 && s.ripple < 12) {
                s.ripple += 0.18 * frameScale;
                const r = Math.round(s.ripple);
                const rAlpha = ((1 - s.ripple / 12) * 0.35).toFixed(2);
                const ry = s.emergeY || Math.min(ph - 8, Math.round(s.baseY + 10));
                pRect(Math.round(s.baseX) - r, ry, 2, 1, `rgba(186, 230, 253, ${rAlpha})`);
                pRect(Math.round(s.baseX) + r - 1, ry, 2, 1, `rgba(186, 230, 253, ${rAlpha})`);
            }

            pRect(mx - 2, my - 1 + wingFlutter, 2, 1, 'rgba(224, 242, 254, 0.82)');
            pRect(mx + 1, my - 1 + wingFlutter, 2, 1, 'rgba(224, 242, 254, 0.82)');
            pRect(mx - 1, my, 3, 1, '#3f6212');
            pRect(mx, my, 1, 1, '#fde047');
            pRect(mx, my + 1, 1, 1, 'rgba(254, 240, 138, 0.65)');

        } else if (s.type === 'plankton_swarm') {
            s.phase += 0.07 * frameScale;
            s.y = Math.max(12, s.y - 0.015 * frameScale);
            const cx = Math.round(s.x + Math.sin(s.phase * 0.6) * 1.2);
            const cy = Math.round(s.y);

            pRect(cx - 5, cy - 4, 11, 9, 'rgba(103, 232, 249, 0.12)');
            pRect(cx - 3, cy - 2, 7, 5, 'rgba(240, 171, 252, 0.18)');

            for (let k = 0; k < 6; k++) {
                const r = 2.2 + (k % 3) * 2.1;
                const ang = s.phase * (k % 2 === 0 ? 1 : -0.8) + k * 1.05;
                const px = Math.round(cx + Math.cos(ang) * r);
                const py = Math.round(cy + Math.sin(ang * 1.1) * (r * 0.85));
                const bodyCol = k % 2 === 0 ? '#f0abfc' : '#67e8f9';
                pRect(px, py, 2, 1, bodyCol);
                pRect(px, py, 1, 1, '#ffffff');
                pRect(px, py + 1, 1, 1, k % 2 === 0 ? 'rgba(217, 70, 239, 0.65)' : 'rgba(6, 182, 212, 0.65)');
            }
            pRect(cx, cy, 2, 2, '#fef08a');
            pRect(cx, cy, 1, 1, '#ffffff');

        } else if (s.type === 'koi_pellet') {
            s.phase = (s.phase || 0) + 0.09 * frameScale;
            s.ripple += 0.16 * frameScale;
            const bobY = (s.baseY !== undefined ? s.baseY : s.y) + Math.sin(s.phase) * 0.6;
            s.y = bobY;
            const px = Math.round(s.x);
            const py = Math.round(bobY);

            if (s.ripple < 15) {
                const alpha = ((1 - s.ripple / 15) * 0.35).toFixed(2);
                for (let a = 0; a < Math.PI * 2; a += 0.55) {
                    pRect(px + Math.cos(a) * s.ripple, py + Math.sin(a) * (s.ripple * 0.65), 1, 1, `rgba(224, 242, 254, ${alpha})`);
                }
            }

            pRect(px - 2, py + 2, 5, 1, 'rgba(2, 10, 18, 0.42)');
            pRect(px - 2, py, 4, 2, '#92400e');
            pRect(px - 1, py - 1, 3, 2, '#d97706');
            pRect(px, py - 1, 2, 1, '#fbbf24');
            pRect(px, py - 1, 1, 1, '#fef08a');
        }

        if (s.life <= 0) stimuli.splice(i, 1);
    }
}

// ============================================================================
// BÖLÜM SONU: YEM VE UYARANLARIN ANİMASYONU, ÇİZİMİ VE ÖMRÜ
// ============================================================================


// ============================================================================
// MODULE: js/habitat-backgrounds.js
// ============================================================================




/* HABITAT BACKGROUNDS — cached static pixel-art environment layers. */

// ============================================================================
// BÖLÜM BAŞI: ÖNBELLEKLENEN STATİK HABİTAT KATMANLARI
// Bu fonksiyon animasyon döngüsünden ayrı çalışır; habitat/tema/boyut değişince yeniden üretilir.
// ============================================================================

function buildStaticEnvironmentLayer(hab) {
    const tier = [1, 2, 3].includes(Number(window.__weDetailTier)) ? Number(window.__weDetailTier) : 1;
    const off = document.createElement('canvas');
    off.width = pw * tier;
    off.height = ph * tier;
    const sCtx = off.getContext('2d');
    sCtx.setTransform(tier, 0, 0, tier, 0, 0);
    const sRect = (x, y, w, h, col) => {
        sCtx.fillStyle = col;
        if (tier <= 1) {
            sCtx.fillRect(Math.round(x), Math.round(y), Math.round(w), Math.round(h));
            return;
        }
        const rx = Math.round(x * tier) / tier;
        const ry = Math.round(y * tier) / tier;
        const rw = Math.max(1 / tier, Math.round(w * tier) / tier);
        const rh = Math.max(1 / tier, Math.round(h * tier) / tier);
        sCtx.fillRect(rx, ry, rw, rh);
        if (rw >= 4 && rh >= 2 && typeof col === 'string' && col.charCodeAt(0) === 35) {
            const step = 1 / tier;
            sCtx.fillStyle = 'rgba(255, 255, 255, 0.06)';
            sCtx.fillRect(rx, ry, rw, step);
        }
    };

    const mistCol = isLightMode ? 'rgba(255, 255, 255, 0.08)' : 'rgba(148, 163, 184, 0.035)';
    sRect(0, ph - 28, pw, 10, mistCol);

    if (hab.sceneProfile === 'meadow') {
        // BÖLÜM BAŞI: ÇAYIR STATİK ÇEVRESİ
        const trunkDark = isLightMode ? '#451a03' : '#181014';
        const trunkMid = isLightMode ? '#78350f' : '#291b22';
        const trunkHi = isLightMode ? '#92400e' : '#3d2832';
        const leafShadow = isLightMode ? '#0c3b20' : '#051613';
        const leafDark = isLightMode ? '#14532d' : '#08221d';
        const leafMid = isLightMode ? '#15803d' : '#10382e';
        const leafHi = isLightMode ? '#22c55e' : '#1b5442';
        const leafRim = isLightMode ? '#4ade80' : '#2dd4bf';

        const drawLeafCluster = (cx, cy, rx, ry, blossoms = false, blossomCol = '#fda4af') => {
            for (let dy = -ry; dy <= ry; dy++) {
                const ratio = 1 - (dy * dy) / (ry * ry);
                if (ratio <= 0) continue;
                const scallop = Math.sin(dy * 0.65 + cx * 0.14) * 2.2 + Math.cos(dy * 1.1) * 1.1;
                const span = Math.max(1, Math.round(rx * Math.sqrt(ratio) + scallop));
                let col = leafMid;
                if (dy < -ry * 0.45) col = leafRim;
                else if (dy < -ry * 0.15) col = leafHi;
                else if (dy > ry * 0.55) col = leafShadow;
                else if (dy > ry * 0.22) col = leafDark;
                sRect(cx - span, cy + dy, span * 2, 1, col);

                if (dy > -ry * 0.4 && dy < ry * 0.3 && dy % 3 === 0 && span > 5) {
                    const texShift = ((dy + cx) % 5) - 2;
                    sRect(cx - Math.floor(span * 0.6) + texShift, cy + dy, Math.max(2, Math.floor(span * 0.5)), 1, dy < 0 ? leafHi : leafDark);
                }
            }
            if (blossoms) {
                [[-0.52, -0.22], [0.38, -0.32], [-0.18, 0.22], [0.46, 0.16], [0.04, -0.46], [-0.34, 0.04], [0.22, -0.06]].forEach(([bx, by], bIdx) => {
                    const px = Math.round(cx + bx * rx);
                    const py = Math.round(cy + by * ry);
                    sRect(px, py + 1, 1, 1, trunkDark);
                    sRect(px - 1, py, 3, 1, blossomCol);
                    sRect(px, py - 1, 1, 3, blossomCol);
                    sRect(px, py, 1, 1, bIdx % 2 === 0 ? '#fef08a' : '#fff1f2');
                });
            }
        };

        const drawBranchSegment = (x0, y0, x1, y1, startThick, endThick) => {
            const steps = Math.max(1, Math.round(Math.hypot(x1 - x0, y1 - y0)));
            for (let s = 0; s <= steps; s++) {
                const t = s / steps;
                const bx = Math.round(x0 + (x1 - x0) * t);
                const by = Math.round(y0 + (y1 - y0) * t - Math.sin(t * Math.PI) * 2.5);
                const thick = Math.max(1, Math.round(startThick + (endThick - startThick) * t));
                sRect(bx, by, 1, thick, trunkDark);
                if (thick >= 2) sRect(bx, by, 1, 1, trunkHi);
            }
        };

        const drawOrchardTree = (baseX, baseY, height, baseWidth, leanDir, blossoms, blossomCol) => {
            const topY = baseY - height;
            sRect(baseX - baseWidth - 6, baseY - 1, (baseWidth + 6) * 2, 3, 'rgba(2, 10, 14, 0.35)');

            for (let y = topY; y < baseY; y++) {
                const prog = (y - topY) / height;
                const curve = Math.sin(prog * Math.PI * 0.9) * 3.5 * leanDir;
                const flare = prog > 0.70 ? Math.pow((prog - 0.70) / 0.30, 2) * (baseWidth * 1.25) : 0;
                const w = Math.round(baseWidth * (0.42 + prog * 0.58) + flare);
                const left = Math.round(baseX + curve - w * 0.5);
                sRect(left, y, w, 1, trunkDark);
                sRect(left + Math.floor(w * 0.28), y, Math.max(1, Math.floor(w * 0.42)), 1, trunkMid);
                sRect(left + (leanDir >= 0 ? w - 2 : 1), y, 1, 1, trunkHi);
                if (prog > 0.78 && y % 2 === 0) {
                    sRect(left + (leanDir >= 0 ? 0 : w - 2), y, 2, 1, leafDark);
                }
            }

            [-1, 1].forEach(rDir => {
                for (let r = 0; r < 6; r++) {
                    const rx = baseX + rDir * (Math.floor(baseWidth * 0.7) + r);
                    const ry = baseY - 2 + Math.floor(r * 0.4);
                    sRect(rx, ry, 2, 2, trunkDark);
                    sRect(rx, ry, 1, 1, r < 3 ? trunkMid : leafDark);
                }
            });

            const rx = Math.round(height * 0.34);
            const ry = Math.round(height * 0.20);
            const forkY = topY + Math.round(height * 0.22);
            const forkX = Math.round(baseX + Math.sin(0.22 * Math.PI * 0.9) * 3.5 * leanDir);

            const leftClusterX = baseX - Math.round(rx * 0.65);
            const leftClusterY = topY + 8;
            const rightClusterX = baseX + Math.round(rx * 0.68);
            const rightClusterY = topY + 6;
            const topClusterX = baseX + leanDir * 8;
            const topClusterY = topY - 10;

            drawLeafCluster(leftClusterX, leftClusterY, Math.round(rx * 0.84), Math.round(ry * 0.84), false);
            drawLeafCluster(rightClusterX, rightClusterY, Math.round(rx * 0.86), Math.round(ry * 0.86), blossoms, blossomCol);

            drawBranchSegment(forkX, forkY, leftClusterX + 4, leftClusterY + 2, Math.max(2, Math.round(baseWidth * 0.45)), 2);
            drawBranchSegment(forkX, forkY - 2, rightClusterX - 4, rightClusterY + 2, Math.max(2, Math.round(baseWidth * 0.45)), 2);
            drawBranchSegment(forkX, topY + 6, topClusterX, topClusterY + 4, Math.max(2, Math.round(baseWidth * 0.35)), 2);

            drawLeafCluster(baseX, topY - 4, rx, ry, blossoms, blossomCol);
            drawLeafCluster(topClusterX, topClusterY, Math.round(rx * 0.76), Math.round(ry * 0.74), blossoms, blossomCol);
        };

        const farHillCol = isLightMode ? 'rgba(20, 83, 45, 0.14)' : 'rgba(10, 38, 34, 0.34)';
        const midHillCol = isLightMode ? 'rgba(21, 101, 52, 0.22)' : 'rgba(12, 48, 40, 0.48)';
        const hillCol = isLightMode ? 'rgba(22, 101, 52, 0.32)' : 'rgba(15, 62, 48, 0.62)';
        const hedgerowCol = isLightMode ? 'rgba(20, 83, 45, 0.38)' : 'rgba(8, 36, 29, 0.72)';

        for (let x = 0; x < pw; x++) {
            const nx = x / Math.max(1, pw);
            const gy = getGroundY(x, 'meadow', pw, ph);

            const farH = Math.round(26 + Math.sin(nx * Math.PI * 1.8 + 0.4) * 10 + Math.cos(x * 0.025) * 4);
            sRect(x, gy - farH, 1, farH, farHillCol);

            const midH = Math.round(19 + Math.cos(nx * Math.PI * 2.2 - 0.5) * 8 + Math.sin(x * 0.035) * 3);
            sRect(x, gy - midH, 1, midH, midHillCol);

            if ((x % 18 < 9) && nx > 0.22 && nx < 0.76) {
                const bushH = 3 + Math.round(Math.sin(x * 0.35) * 1.5);
                sRect(x, gy - midH - bushH, 1, bushH + 1, hedgerowCol);
            }

            const h = Math.round(12 + Math.sin(nx * Math.PI * 2.5) * 6 + Math.cos(x * 0.04) * 2.5);
            sRect(x, gy - h, 1, h, hillCol);
        }

        const fenceStart = Math.round(pw * 0.24);
        const fenceEnd = Math.round(pw * 0.75);
        const fenceDark = isLightMode ? '#5c3a21' : '#1f161b';
        const fenceHi = isLightMode ? '#92400e' : '#3b2830';
        for (let fx = fenceStart; fx <= fenceEnd; fx++) {
            const fgy = getGroundY(fx, 'meadow', pw, ph) - Math.round(9 + Math.sin((fx / Math.max(1, pw)) * Math.PI * 2.5) * 4);
            if ((fx - fenceStart) % 16 === 0) {
                sRect(fx, fgy - 7, 2, 9, fenceDark);
                sRect(fx, fgy - 7, 1, 8, fenceHi);
            }
            sRect(fx, fgy - 5, 1, 1, fenceDark);
            sRect(fx, fgy - 2, 1, 1, fenceDark);
        }

        const leftTree1X = 24;
        const leftTree2X = Math.round(pw * 0.19);
        drawOrchardTree(leftTree2X, getGroundY(leftTree2X, 'meadow', pw, ph) + 2, 90, 9, 1, true, '#fbbf24');
        drawOrchardTree(leftTree1X, getGroundY(leftTree1X, 'meadow', pw, ph) + 3, 116, 13, 1, true, '#fda4af');

        const rightTreeX = pw - 20;
        drawOrchardTree(rightTreeX, getGroundY(rightTreeX, 'meadow', pw, ph) + 3, 102, 11, -1, true, '#fda4af');

        const turfHighlight = isLightMode ? '#4ade80' : '#1f6f54';
        const turfTop = isLightMode ? '#16a34a' : '#0f392b';
        const turfMid = isLightMode ? '#15803d' : '#0b2b21';
        const turfDeep = isLightMode ? '#14532d' : '#071f18';
        const soilLoam = isLightMode ? '#3f2e21' : '#051410';

        for (let x = 0; x < pw; x++) {
            const gy = getGroundY(x, 'meadow', pw, ph);
            sRect(x, gy, 1, ph - gy, turfDeep);
            sRect(x, gy + 5, 1, Math.max(1, ph - gy - 5), soilLoam);
            sRect(x, gy + 2, 1, 3, turfMid);
            sRect(x, gy, 1, 2, turfTop);
            if (x % 3 === 0) {
                sRect(x, gy - 1, 1, 1, (x % 9 === 0) ? turfHighlight : turfTop);
            }
        }

        const hx = Math.round(pw * 0.84);
        const hgy = getGroundY(hx, 'meadow', pw, ph) + 1;

        [
            { bx: hx - 20, rx: 14, ry: 10, col: '#c084fc', dir: -1 },
            { bx: hx + 19, rx: 16, ry: 11, col: '#fb7185', dir: 1 }
        ].forEach(bush => {
            const bGroundY = getGroundY(bush.bx, 'meadow', pw, ph) + 1;
            const bCenterY = hgy - (bush.dir < 0 ? 11 : 13);
            sRect(bush.bx - bush.rx + 2, bGroundY - 1, (bush.rx - 2) * 2, 3, 'rgba(2, 10, 14, 0.38)');
            [-4, 0, 4].forEach(stemOff => {
                drawBranchSegment(bush.bx + stemOff * 0.5, bGroundY, bush.bx + stemOff, bCenterY + 2, 2, 1);
            });
            drawLeafCluster(bush.bx, bCenterY, bush.rx, bush.ry, true, bush.col);
        });

        const stoneDark = isLightMode ? '#475569' : '#1e293b';
        const stoneMid = isLightMode ? '#64748b' : '#334155';
        const stoneHi = isLightMode ? '#94a3b8' : '#475569';
        sRect(hx - 21, hgy, 42, 3, 'rgba(2, 10, 14, 0.48)');
        sRect(hx - 18, hgy - 5, 36, 6, stoneDark);
        for (let sx = hx - 16; sx <= hx + 12; sx += 6) {
            sRect(sx, hgy - 4, 5, 2, stoneMid);
            sRect(sx, hgy - 4, 4, 1, stoneHi);
            sRect(sx + 1, hgy - 2, 4, 2, stoneMid);
        }
        sRect(hx - 16, hgy - 5, 5, 1, leafMid);
        sRect(hx + 11, hgy - 5, 4, 1, leafMid);

        sRect(hx - 16, hgy - 7, 32, 2, trunkDark);
        sRect(hx - 15, hgy - 7, 30, 1, trunkHi);

        const boxLight = isLightMode ? '#fef3c7' : '#eab308';
        const boxMid = isLightMode ? '#fde68a' : '#ca8a04';
        const boxShadow = isLightMode ? '#f59e0b' : '#a16207';
        const bodyTop = hgy - 37;
        const bodyH = 30;

        sRect(hx - 13, bodyTop, 26, bodyH, boxLight);
        sRect(hx + 6, bodyTop, 7, bodyH, boxMid);
        sRect(hx - 13, bodyTop, 2, bodyH, trunkMid);
        sRect(hx + 11, bodyTop, 2, bodyH, trunkDark);

        for (let dy = 2; dy < bodyH; dy += 4) {
            sRect(hx - 11, bodyTop + dy, 1, 2, boxShadow);
            sRect(hx + 10, bodyTop + dy, 1, 2, trunkMid);
        }

        [hgy - 17, hgy - 27].forEach(seamY => {
            sRect(hx - 14, seamY, 28, 2, trunkDark);
            sRect(hx - 13, seamY, 26, 1, trunkHi);
            sRect(hx - 13, seamY + 2, 26, 1, boxShadow);
            sRect(hx - 4, seamY + 4, 7, 2, trunkMid);
            sRect(hx - 4, seamY + 4, 7, 1, trunkHi);
        });

        sRect(hx - 5, hgy - 24, 8, 5, trunkDark);
        sRect(hx - 4, hgy - 23, 6, 3, '#f59e0b');
        sRect(hx - 3, hgy - 22, 4, 1, '#fef08a');

        sRect(hx - 6, hgy - 10, 10, 3, '#181014');
        sRect(hx - 8, hgy - 8, 14, 2, trunkMid);
        sRect(hx - 7, hgy - 8, 12, 1, trunkHi);
        sRect(hx - 4, hgy - 8, 6, 1, '#fef08a');

        sRect(hx - 15, bodyTop, 30, 1, 'rgba(2, 10, 14, 0.35)');
        for (let r = 0; r <= 12; r++) {
            const halfW = 18 - Math.floor(r * 1.4);
            const ry = bodyTop - 1 - r;
            const roofCol = r % 3 === 0 ? trunkDark : (r % 2 === 0 ? trunkHi : trunkMid);
            sRect(hx - halfW, ry, halfW * 2, 1, roofCol);
            if (r > 0 && r < 10 && r % 2 === 0) {
                for (let sx = -halfW + 2; sx < halfW - 2; sx += 4) {
                    sRect(hx + sx, ry, 1, 1, trunkDark);
                }
            }
        }
        sRect(hx - 1, bodyTop - 16, 2, 4, trunkDark);
        sRect(hx, bodyTop - 16, 1, 3, '#fbbf24');

        sRect(hx - 19, bodyTop + 2, 7, 2, trunkDark);
        sRect(hx - 19, bodyTop + 2, 6, 1, trunkHi);
        for (let b = 0; b < 4; b++) {
            sRect(hx - 14 - b, bodyTop + 4 + (3 - b), 1, 1, trunkMid);
        }

        const potX = hx + 14;
        const potY = hgy - 7;
        sRect(potX - 2, potY - 3, 5, 4, '#b45309');
        sRect(potX - 3, potY - 4, 7, 1, '#d97706');
        sRect(potX - 2, potY - 5, 5, 1, '#fbbf24');
        // BÖLÜM SONU: ÇAYIR STATİK ÇEVRESİ
    }

   else if (hab.sceneProfile === 'wetland') {
        // BÖLÜM BAŞI: SULAK ALAN STATİK ÇEVRESİ
        const waterHorizonY = ph - 52;
        const distantHillCol = isLightMode ? 'rgba(15, 62, 52, 0.16)' : 'rgba(4, 24, 24, 0.38)';
        const farTreeCol = isLightMode ? 'rgba(15, 62, 52, 0.25)' : 'rgba(4, 32, 30, 0.52)';
        const farReedCol = isLightMode ? 'rgba(20, 83, 45, 0.34)' : 'rgba(6, 46, 38, 0.62)';

        for (let x = 0; x < pw; x++) {
            const nx = x / Math.max(1, pw);
            const hillH = Math.round(16 + Math.sin(nx * Math.PI * 2.1 + 0.5) * 7 + Math.cos(x * 0.03) * 3);
            sRect(x, waterHorizonY - hillH, 1, hillH, distantHillCol);
        }

        for (let x = 0; x < pw; x += 2) {
            const nx = x / Math.max(1, pw);
            const shoreMask = Math.abs(nx - 0.5) > 0.16 ? 1.0 : 0.42;
            const rh = Math.round((10 + Math.sin(x * 0.09) * 5 + Math.cos(x * 0.23) * 3) * shoreMask);
            sRect(x, waterHorizonY - rh, 2, rh + 2, farReedCol);
            if ((x % 12 === 0) && (nx < 0.38 || nx > 0.62)) {
                const treeH = 18 + (x % 11);
                sRect(x, waterHorizonY - 6, 2, 6, isLightMode ? '#3b281e' : '#091817');
                for (let dy = -treeH; dy <= 0; dy++) {
                    const ratio = 1 - (dy * dy) / (treeH * treeH);
                    const span = Math.round((8 + (x % 5)) * Math.sqrt(Math.max(0, ratio)));
                    sRect(x - span, waterHorizonY - 6 + dy, span * 2, 1, farTreeCol);
                }
            }
        }

        const waterTop = isLightMode ? '#0e7490' : '#082f49';
        const waterMid = isLightMode ? '#115e59' : '#062830';
        const waterDeep = isLightMode ? '#134e4a' : '#03171e';
        const waterSteps = 26;
        for (let s = 0; s < waterSteps; s++) {
            const t = s / (waterSteps - 1);
            const wy = Math.floor(waterHorizonY + t * (ph - waterHorizonY));
            const wh = Math.ceil((ph - waterHorizonY) / waterSteps) + 1;
            const col = t < 0.5 ? lerpHex(waterTop, waterMid, t * 2) : lerpHex(waterMid, waterDeep, (t - 0.5) * 2);
            sRect(0, wy, pw, wh, col);
        }
        sRect(0, waterHorizonY, pw, 1, isLightMode ? 'rgba(186, 230, 253, 0.48)' : 'rgba(45, 212, 191, 0.20)');
        for (let x = 0; x < pw; x += 3) {
            const nx = x / Math.max(1, pw);
            if (nx < 0.36 || nx > 0.64) {
                sRect(x, waterHorizonY + 1, 2, 4, isLightMode ? 'rgba(20, 83, 45, 0.18)' : 'rgba(4, 24, 24, 0.35)');
            }
        }

        const islands = [
            { cx: Math.round(pw * 0.44), y: ph - 21, rx: 22, ry: 5 },
            { cx: Math.round(pw * 0.58), y: ph - 25, rx: 19, ry: 4 }
        ];
        islands.forEach(isl => {
            sRect(isl.cx - isl.rx + 1, isl.y + 2, (isl.rx - 1) * 2, 5, 'rgba(2, 12, 18, 0.46)');
            sRect(isl.cx - isl.rx, isl.y + 1, isl.rx * 2, 2, isLightMode ? '#451a03' : '#14141b');
            for (let dy = -isl.ry; dy <= 1; dy++) {
                const span = Math.round(isl.rx * Math.sqrt(Math.max(0, 1 - (dy * dy) / ((isl.ry + 2) * (isl.ry + 2)))));
                const col = dy < -1 ? (isLightMode ? '#16a34a' : '#0f5138') : (isLightMode ? '#14532d' : '#082f24');
                sRect(isl.cx - span, isl.y + dy, span * 2, 1, col);
                if (dy === -isl.ry && span > 4) {
                    sRect(isl.cx - Math.floor(span * 0.6), isl.y + dy, Math.floor(span * 1.2), 1, isLightMode ? '#4ade80' : '#10b981');
                }
            }
            sRect(isl.cx - isl.rx + 2, isl.y + 2, (isl.rx - 2) * 2, 1, isLightMode ? 'rgba(186, 230, 253, 0.32)' : 'rgba(45, 212, 191, 0.14)');
        });

        const willowDark = isLightMode ? '#3b281e' : '#14141b';
        const willowMid = isLightMode ? '#573b2c' : '#24222c';
        const willowHi = isLightMode ? '#78523d' : '#363240';
        const canopyDark = isLightMode ? '#14532d' : '#062e24';
        const canopyMid = isLightMode ? '#15803d' : '#0b4635';
        const canopyHi = isLightMode ? '#22c55e' : '#136348';
        const reach = Math.min(145, Math.round(pw * 0.26));

        [
            { isLeft: true, dir: 1 },
            { isLeft: false, dir: -1 }
        ].forEach(wTree => {
            const edgeX = wTree.isLeft ? 0 : pw - 1;
            const bankY = getGroundY(edgeX, 'wetland', pw, ph) + 4;

            for (let y = 0; y < bankY; y++) {
                const prog = y / bankY;
                const lean = Math.sin((1 - prog) * Math.PI * 0.5) * 12 * wTree.dir;
                const rootFlare = prog > 0.70 ? Math.pow((prog - 0.70) / 0.30, 2) * 18 : 0;
                const tw = Math.round(13 + prog * 6 + rootFlare);
                const tx = wTree.isLeft ? Math.max(0, Math.round(lean)) : Math.min(pw - tw, Math.round(pw - tw + lean));
                sRect(tx, y, tw, 1, willowDark);
                sRect(tx + (wTree.isLeft ? tw - 5 : 2), y, 3, 1, willowMid);
                sRect(tx + (wTree.isLeft ? tw - 2 : 0), y, 1, 1, willowHi);
                if (prog > 0.74 && y % 2 === 0) {
                    sRect(tx + (wTree.isLeft ? 1 : tw - 3), y, 2, 1, canopyMid);
                }
            }

            [0.08, 0.30, 0.52, 0.74, 0.92].forEach(tNode => {
                const cx = Math.round(wTree.isLeft ? (tNode * reach) : (pw - tNode * reach));
                const branchY = Math.round(6 + Math.pow(tNode, 1.2) * 14);
                const rx = Math.round(28 * (1 - tNode * 0.32));
                const bottomY = branchY + Math.round(9 * (1 - tNode * 0.28));

                for (let y = 0; y <= bottomY; y++) {
                    const normY = (y - branchY * 0.5) / Math.max(1, bottomY - branchY * 0.5);
                    const ellipse = Math.max(0, 1 - normY * normY);
                    const scallop = Math.sin(y * 0.8 + tNode * 10) * 1.5;
                    const span = Math.round(rx * (y < branchY * 0.5 ? 1 : Math.sqrt(ellipse)) + scallop);
                    const col = y < branchY * 0.35 ? canopyHi : (y > branchY ? canopyDark : canopyMid);
                    sRect(cx - span, y, span * 2, 1, col);
                }
            });

            for (let s = 0; s <= reach; s++) {
                const t = s / Math.max(1, reach);
                const bx = wTree.isLeft ? s : (pw - 1 - s);
                const by = Math.round(6 + Math.pow(t, 1.2) * 14 + Math.sin(bx * 0.08) * 1.5);
                const thick = Math.max(2, Math.round(9 * (1 - t * 0.75)));
                sRect(bx, by - Math.floor(thick * 0.5), 1, thick, willowDark);
                sRect(bx, by + Math.ceil(thick * 0.5) - 1, 1, 1, willowHi);
            }
        });

        const bankMud = isLightMode ? '#451a03' : '#091513';
        const bankDeep = isLightMode ? '#14532d' : '#052019';
        const bankTop = isLightMode ? '#16a34a' : '#0d4a38';
        const bankHi = isLightMode ? '#4ade80' : '#10b981';

        for (let x = 0; x < pw; x++) {
            const nx = x / Math.max(1, pw);
            if (nx > 0.36 && nx < 0.64) continue;
            const gy = getGroundY(x, 'wetland', pw, ph);
            sRect(x, gy + 3, 1, 4, 'rgba(2, 10, 16, 0.45)');
            sRect(x, gy, 1, ph - gy, bankDeep);
            sRect(x, gy + 2, 1, 2, bankMud);
            sRect(x, gy, 1, 2, bankTop);
            if (x % 4 === 0) sRect(x, gy - 1, 1, 1, bankHi);
        }

        const snagX = Math.round(pw * 0.66);
        const snagBankY = getGroundY(snagX + 8, 'wetland', pw, ph) + 1;
        sRect(snagX - 18, snagBankY + 1, 30, 3, 'rgba(2, 10, 16, 0.45)');
        sRect(snagX - 19, snagBankY + 2, 9, 1, isLightMode ? 'rgba(186, 230, 253, 0.35)' : 'rgba(45, 212, 191, 0.16)');
        for (let s = 0; s < 28; s++) {
            const t = s / 27;
            const sx = snagX - 16 + s;
            const arch = Math.sin(t * Math.PI * 0.92) * 8;
            const sy = Math.round(snagBankY + 1 - arch - t * 2);
            const thick = Math.max(2, 6 - Math.floor((1 - t) * 3.5));
            sRect(sx, sy, 1, thick, willowDark);
            sRect(sx, sy, 1, 1, willowHi);
            if (s > 5 && s < 20 && s % 3 === 0) {
                sRect(sx, sy - 1, 2, 1, isLightMode ? '#22c55e' : '#10b981');
            }
        }
        // BÖLÜM SONU: SULAK ALAN STATİK ÇEVRESİ
    }
       
    else if (hab.sceneProfile === 'betta-aquarium') {
        // BÖLÜM BAŞI: BETTA AKVARYUMU STATİK ÇEVRESİ
        const soilY = (x) => {
            const nx = x / Math.max(1, pw);
            const mound = Math.pow(Math.abs(nx - 0.50) * 1.95, 1.45) * 18;
            return Math.round(ph - 4 - mound - Math.sin(x * 0.04) * 2);
        };

        sRect(0, 0, pw, 2, isLightMode ? 'rgba(186, 230, 253, 0.38)' : 'rgba(56, 189, 248, 0.16)');
        sRect(0, 2, pw, 1, isLightMode ? 'rgba(255, 255, 255, 0.45)' : 'rgba(125, 211, 252, 0.22)');

        const farSilhouetteCol = isLightMode ? 'rgba(11, 61, 56, 0.16)' : 'rgba(4, 34, 34, 0.38)';
        const bgPlantCol = isLightMode ? 'rgba(15, 82, 72, 0.26)' : 'rgba(6, 48, 44, 0.52)';
        for (let x = 0; x < pw; x += 3) {
            const nx = x / Math.max(1, pw);
            const base = soilY(x);
            if (nx < 0.42 || nx > 0.58) {
                const stemH = Math.round((38 + Math.sin(x * 0.14) * 14 + Math.cos(x * 0.27) * 8) * (0.62 + Math.abs(nx - 0.5)));
                sRect(x, base - stemH, 2, stemH, bgPlantCol);
                if (x % 6 === 0) {
                    sRect(x - 1, base - Math.floor(stemH * 0.7), 4, 1, bgPlantCol);
                }
            }
            const farH = Math.round(20 + Math.sin(x * 0.05) * 8);
            sRect(x, base - farH, 3, farH, farSilhouetteCol);
        }

        const stoneDark = isLightMode ? '#1e293b' : '#09111e';
        const stoneMid = isLightMode ? '#334155' : '#132033';
        const stoneHi = isLightMode ? '#64748b' : '#243854';
        const stoneRim = isLightMode ? '#94a3b8' : '#38bdf8';
        const mossPocket = isLightMode ? '#16a34a' : '#0d9488';

        const dragonStones = [
            { bx: 38, topY: ph - 46, baseW: 26, lean: 0.24 },
            { bx: pw - 58, topY: ph - 70, baseW: 40, lean: -0.22 },
            { bx: pw - 84, topY: ph - 46, baseW: 28, lean: -0.30 },
            { bx: pw - 28, topY: ph - 54, baseW: 30, lean: 0.15 }
        ];
        dragonStones.forEach((st, sIdx) => {
            const bY = ph;
            const h = bY - st.topY;
            for (let y = 0; y < h; y++) {
                const prog = y / h;
                const w = Math.round(6 + prog * st.baseW + Math.sin(y * 0.25 + sIdx) * 2);
                const cx = st.bx + Math.round((1 - prog) * h * st.lean);
                const left = cx - Math.floor(w * 0.5);
                sRect(left, st.topY + y, w, 1, stoneDark);
                sRect(left + 1, st.topY + y, Math.max(2, Math.floor(w * 0.58)), 1, stoneMid);
                sRect(left + 1, st.topY + y, 2, 1, stoneHi);
                if (y < 6 && prog < 0.2) {
                    sRect(left + 1, st.topY + y, 1, 1, stoneRim);
                }
                if (y > 6 && y % 6 === 0 && w > 12) {
                    const holeX = left + 4 + ((y * 3 + sIdx * 5) % Math.max(2, w - 9));
                    sRect(holeX, st.topY + y, 4, 2, '#040811');
                    sRect(holeX, st.topY + y - 1, 3, 1, mossPocket);
                    if (!isLightMode && y % 12 === 0) {
                        sRect(holeX + 1, st.topY + y - 1, 2, 1, 'rgba(45, 212, 191, 0.55)');
                    }
                }
            }
        });

        const woodShadow = isLightMode ? '#271105' : '#0f080b';
        const woodDark = isLightMode ? '#3f1d0b' : '#1a1014';
        const woodMid = isLightMode ? '#5c2d16' : '#2c1a21';
        const woodHi = isLightMode ? '#854d0e' : '#4a2c36';
        const maxTrunkX = Math.min(190, Math.floor(pw * 0.46));

        for (let x = 0; x < maxTrunkX; x++) {
            const t = x / maxTrunkX;
            const archY = Math.round(ph - 18 - Math.sin(t * Math.PI * 0.88) * 54 + Math.cos(t * 4) * 3);
            const thick = Math.max(2, Math.floor(15 * (1 - t * 0.74)));
            sRect(x, archY, 2, thick, woodDark);
            sRect(x, archY + thick - 1, 2, 1, woodShadow);
            sRect(x, archY + 1, 2, Math.max(1, thick - 3), woodMid);
            sRect(x, archY, 2, 2, woodHi);

            if (t > 0.18 && t < 0.84) {
                const subT = (t - 0.18) / 0.66;
                const upperY = Math.round(archY - 12 - Math.sin(subT * Math.PI) * 24);
                const uThick = Math.max(2, Math.floor(6 * (1 - subT * 0.68)));
                if (subT < 0.14) {
                    const joinH = Math.max(1, archY - (upperY + uThick) + 2);
                    sRect(x, upperY + uThick - 1, 2, joinH, woodDark);
                }
                sRect(x, upperY, 2, uThick, woodDark);
                sRect(x, upperY, 2, 1, woodHi);
                if (x % 2 === 0) {
                    sRect(x, upperY - 2, 2, 2, isLightMode ? '#16a34a' : '#0d9488');
                    sRect(x, upperY - 3, 1, 1, isLightMode ? '#4ade80' : '#2dd4bf');
                }
            }

            if (t > 0.12 && t < 0.48) {
                const legT = (t - 0.12) / 0.36;
                const targetFloor = soilY(x) + 3;
                const legY = Math.round(archY + thick + legT * (targetFloor - (archY + thick)));
                const legW = Math.max(2, Math.floor(7 * (1 - legT * 0.5)));
                sRect(x, legY, legW, 3, woodDark);
                sRect(x, legY, 2, 1, woodHi);
            }

            if (t > 0.62) {
                const propT = (t - 0.62) / 0.38;
                const groundTarget = soilY(x) + 2;
                const branchY = Math.round(archY + Math.pow(propT, 1.15) * (groundTarget - archY));
                sRect(x, branchY, 2, 3, woodDark);
                sRect(x, branchY, 2, 1, woodHi);
            }
        }

        const rightRootSpan = Math.min(95, Math.floor(pw * 0.24));
        for (let s = 0; s < rightRootSpan; s++) {
            const t = s / rightRootSpan;
            const rx = pw - 42 - s;
            const anchorY = soilY(rx) + 2;
            const arch = Math.round((ph - 28 - Math.sin(t * Math.PI * 0.78) * 24) * (1 - Math.pow(t, 1.6)) + anchorY * Math.pow(t, 1.6));
            const rThick = Math.max(2, Math.floor(8 * (1 - t * 0.72)));
            sRect(rx, arch, 2, rThick, woodDark);
            sRect(rx, arch, 2, 1, woodHi);
            if (s % 3 === 0 && t < 0.72) {
                sRect(rx, arch - 2, 2, 2, isLightMode ? '#16a34a' : '#0d9488');
            }
        }

        const soilDark = isLightMode ? '#1e1b18' : '#090d16';
        const soilMid = isLightMode ? '#292524' : '#131c2b';
        const soilRim = isLightMode ? '#15803d' : '#0f5138';
        const sandShadow = isLightMode ? '#94a3b8' : '#1e293b';
        const sandBase = isLightMode ? '#cbd5e1' : '#334155';
        const sandHi = isLightMode ? '#f1f5f9' : '#475569';

        for (let x = 0; x < pw; x++) {
            const nx = x / Math.max(1, pw);
            const gy = soilY(x);
            const inSandCanyon = Math.abs(nx - 0.50) < 0.085;

            if (inSandCanyon) {
                const sandY = ph - 5 - Math.round(Math.cos((nx - 0.50) * 18) * 2);
                sRect(x, sandY, 1, ph - sandY, sandBase);
                sRect(x, sandY, 1, 2, sandHi);
                if (Math.abs(nx - 0.50) > 0.068) {
                    sRect(x, sandY, 1, 2, sandShadow);
                }
            } else {
                sRect(x, gy, 1, ph - gy, soilDark);
                sRect(x, gy + 2, 1, Math.max(1, Math.floor((ph - gy) * 0.5)), soilMid);
                sRect(x, gy, 1, 2, soilRim);
                if ((x * 7) % 5 === 0 && ph - gy > 5) {
                    sRect(x, gy + 3 + (x % 4), 1, 1, stoneDark);
                }
            }
        }

        [Math.round(pw * 0.415), Math.round(pw * 0.585)].forEach((bx, bIdx) => {
            const by = soilY(bx);
            sRect(bx - 5, by - 2, 10, 5, stoneDark);
            sRect(bx - 4, by - 3, 8, 3, stoneMid);
            sRect(bx - 3, by - 3, 5, 1, stoneHi);
            sRect(bx - 2 + bIdx, by - 4, 3, 1, mossPocket);
        });

        const marimoBalls = [
            { x: Math.round(pw * 0.35), r: 5 },
            { x: Math.round(pw * 0.38), r: 4 },
            { x: Math.round(pw * 0.62), r: 5 },
            { x: Math.round(pw * 0.65), r: 3 }
        ];
        marimoBalls.forEach(mb => {
            const my = soilY(mb.x) - mb.r + 2;
            sRect(mb.x - mb.r, my + mb.r - 1, mb.r * 2, 2, 'rgba(2, 8, 16, 0.5)');
            for (let dy = -mb.r; dy <= mb.r; dy++) {
                const span = Math.round(mb.r * Math.sqrt(Math.max(0, 1 - (dy * dy) / (mb.r * mb.r))));
                const col = dy < -1 ? '#22c55e' : (dy > 1 ? '#14532d' : '#15803d');
                sRect(mb.x - span, my + dy, span * 2, 1, col);
                if (dy === -mb.r + 1 && span > 2) {
                    sRect(mb.x - Math.floor(span * 0.5), my + dy, Math.max(1, span), 1, '#4ade80');
                }
            }
        });

        [Math.round(pw * 0.44), Math.round(pw * 0.55)].forEach((lx, idx) => {
            const ly = ph - 5;
            sRect(lx - 5, ly, 10, 1, 'rgba(2, 8, 16, 0.38)');
            sRect(lx - 5, ly - 1, 10, 2, '#78350f');
            sRect(lx - 4, ly - 2, 8, 1, '#b45309');
            sRect(lx - 3 + idx * 2, ly - 1, 5, 1, '#d97706');
            sRect(lx - 6, ly - 1, 2, 1, '#451a03');
        });
        // BÖLÜM SONU: BETTA AKVARYUMU STATİK ÇEVRESİ
    }

   else if (hab.sceneProfile === 'botanical') {
        // BÖLÜM BAŞI: BOTANİK BAHÇE STATİK ÇEVRESİ
        const reach = Math.min(155, Math.round(pw * 0.30));

        const farHedgeCol = isLightMode ? 'rgba(20, 83, 45, 0.20)' : 'rgba(15, 23, 52, 0.48)';
        const midHedgeCol = isLightMode ? 'rgba(21, 101, 52, 0.28)' : 'rgba(13, 42, 40, 0.62)';
        for (let x = 0; x < pw; x++) {
            const nx = x / Math.max(1, pw);
            const gy = getGroundY(x, 'botanical', pw, ph);
            const farH = Math.round(18 + Math.sin(nx * Math.PI * 3 + 0.4) * 6 + Math.cos(x * 0.05) * 2);
            sRect(x, gy - farH, 1, farH, farHedgeCol);
            const midH = Math.round(10 + Math.cos(nx * Math.PI * 4) * 3 + Math.sin(x * 0.08) * 1.5);
            sRect(x, gy - midH, 1, midH, midHedgeCol);
        }

        const glassFrameCol = isLightMode ? 'rgba(30, 58, 95, 0.28)' : 'rgba(49, 46, 129, 0.58)';
        const glassHiCol = isLightMode ? 'rgba(255, 255, 255, 0.38)' : 'rgba(165, 180, 252, 0.20)';
        const glassPaneCol = isLightMode ? 'rgba(224, 242, 254, 0.20)' : 'rgba(129, 140, 248, 0.07)';
        const domeCx = Math.round(pw * 0.50);
        const domeBaseY = getGroundY(domeCx, 'botanical', pw, ph) - 1;
        const domeRx = Math.min(76, Math.round(pw * 0.16));
        const domeRy = 42;

        for (let dy = -domeRy; dy <= 0; dy++) {
            const span = Math.round(domeRx * Math.sqrt(Math.max(0, 1 - (dy * dy) / (domeRy * domeRy))));
            sRect(domeCx - span, domeBaseY - 18 + dy, span * 2, 1, glassPaneCol);
            sRect(domeCx - span, domeBaseY - 18 + dy, 1, 1, glassFrameCol);
            sRect(domeCx + span - 1, domeBaseY - 18 + dy, 1, 1, glassFrameCol);
            if (dy % 10 === 0) {
                sRect(domeCx - span, domeBaseY - 18 + dy, span * 2, 1, glassFrameCol);
            } else if (dy % 10 === -1 && span > 6) {
                sRect(domeCx - span + 2, domeBaseY - 18 + dy, Math.max(2, Math.floor(span * 0.5)), 1, glassHiCol);
            }
        }
        sRect(domeCx - domeRx, domeBaseY - 18, domeRx * 2, 18, glassPaneCol);

        const indoorFoliage = isLightMode ? 'rgba(22, 101, 52, 0.18)' : 'rgba(16, 185, 129, 0.10)';
        [-0.55, -0.28, 0.28, 0.55].forEach((pos, idx) => {
            const px = Math.round(domeCx + pos * domeRx);
            const phIn = 12 + (idx % 2) * 5;
            for (let y = 0; y < phIn; y++) {
                const w = Math.max(1, Math.round((1 - y / phIn) * 6));
                sRect(px - w, domeBaseY - 4 - y, w * 2, 1, indoorFoliage);
            }
        });

        [-0.6, -0.3, 0, 0.3, 0.6].forEach(rib => {
            const rx = Math.round(domeCx + rib * domeRx);
            const rh = Math.round(domeRy * Math.sqrt(Math.max(0, 1 - rib * rib)));
            sRect(rx, domeBaseY - 18 - rh, 1, rh + 18, glassFrameCol);
        });
        sRect(domeCx - domeRx, domeBaseY - 18, domeRx * 2, 1, glassFrameCol);
        sRect(domeCx - domeRx - 1, domeBaseY - 4, domeRx * 2 + 2, 4, isLightMode ? '#475569' : '#1e1b4b');
        sRect(domeCx - domeRx, domeBaseY - 4, domeRx * 2, 1, glassHiCol);

        for (let dy = -12; dy <= 0; dy++) {
            const dw = dy < -8 ? Math.round(6 * Math.sqrt(Math.max(0, 1 - ((dy + 8) * (dy + 8)) / 16))) : 6;
            sRect(domeCx - dw, domeBaseY + dy, dw * 2, 1, isLightMode ? 'rgba(254, 249, 195, 0.28)' : 'rgba(253, 224, 71, 0.12)');
            sRect(domeCx - dw, domeBaseY + dy, 1, 1, glassFrameCol);
            sRect(domeCx + dw - 1, domeBaseY + dy, 1, 1, glassFrameCol);
        }
        sRect(domeCx - 1, domeBaseY - 18 - domeRy - 7, 2, 7, glassFrameCol);
        sRect(domeCx - 2, domeBaseY - 18 - domeRy - 5, 4, 1, glassHiCol);

        const trunkDark = isLightMode ? '#3b2316' : '#161122';
        const trunkMid = isLightMode ? '#5c3724' : '#261d38';
        const trunkHi = isLightMode ? '#7c4d34' : '#3b2d54';
        const leafDark = isLightMode ? '#14532d' : '#092622';
        const leafMid = isLightMode ? '#15803d' : '#113e35';
        const leafHi = isLightMode ? '#22c55e' : '#1d5e4a';
        const blossomCrown = isLightMode ? '#d8b4fe' : '#6b21a8';

        [
            { isLeft: true, dir: 1 },
            { isLeft: false, dir: -1 }
        ].forEach(tree => {
            const edgeX = tree.isLeft ? 0 : pw - 1;
            const groundY = getGroundY(edgeX, 'botanical', pw, ph) + 4;

            for (let y = 0; y < groundY; y++) {
                const prog = y / groundY;
                const twist = Math.sin(y * 0.06) * 2.5 + Math.sin((1 - prog) * Math.PI * 0.5) * 10 * tree.dir;
                const rootFlare = prog > 0.72 ? Math.pow((prog - 0.72) / 0.28, 2) * 18 : 0;
                const tw = Math.round(13 + prog * 5 + rootFlare);
                const tx = tree.isLeft ? Math.max(0, Math.round(twist)) : Math.min(pw - tw, Math.round(pw - tw + twist));
                sRect(tx, y, tw, 1, trunkDark);
                sRect(tx + (tree.isLeft ? tw - 5 : 2), y, 3, 1, trunkMid);
                sRect(tx + (tree.isLeft ? tw - 2 : 0), y, 2, 1, trunkHi);
                if (prog > 0.76 && y % 2 === 0) {
                    sRect(tx + (tree.isLeft ? 1 : tw - 3), y, 2, 1, leafMid);
                }
            }

            [0.06, 0.28, 0.50, 0.72, 0.90].forEach((tNode, idx) => {
                const cx = Math.round(tree.isLeft ? (tNode * reach) : (pw - tNode * reach));
                const branchY = Math.round(5 + Math.pow(tNode, 1.2) * 15);
                const rx = Math.round(30 * (1 - tNode * 0.30));
                const bottomY = branchY + Math.round(8 * (1 - tNode * 0.28));

                for (let y = 0; y <= bottomY; y++) {
                    const normY = (y - branchY * 0.5) / Math.max(1, bottomY - branchY * 0.5);
                    const ellipse = Math.max(0, 1 - normY * normY);
                    const scallop = Math.sin(y * 0.8 + idx) * 1.6;
                    const span = Math.round(rx * (y < branchY * 0.5 ? 1 : Math.sqrt(ellipse)) + scallop);
                    let col = y < branchY * 0.35 ? leafHi : (y > branchY ? leafDark : leafMid);
                    if ((y + idx) % 5 === 0 && y > branchY * 0.4) col = blossomCrown;
                    sRect(cx - span, y, span * 2, 1, col);
                }
            });

            for (let s = 0; s <= reach; s++) {
                const t = s / Math.max(1, reach);
                const bx = tree.isLeft ? s : (pw - 1 - s);
                const by = Math.round(5 + Math.pow(t, 1.2) * 15 + Math.sin(bx * 0.09) * 1.5);
                const thick = Math.max(2, Math.round(9 * (1 - t * 0.75)));
                sRect(bx, by - Math.floor(thick * 0.5), 1, thick, trunkDark);
                sRect(bx, by + Math.ceil(thick * 0.5) - 1, 1, 1, trunkHi);
            }
        });

        const gx = pw - 68;
        const archBaseY = getGroundY(gx + 16, 'botanical', pw, ph) + 2;
        const pillarH = 44;
        const archTopY = archBaseY - pillarH;
        const stoneDark = isLightMode ? '#475569' : '#171c2e';
        const stoneMid = isLightMode ? '#64748b' : '#242c46';
        const stoneHi = isLightMode ? '#94a3b8' : '#384366';

        [gx, gx + 28].forEach(px => {
            const pGroundY = getGroundY(px + 3, 'botanical', pw, ph) + 2;
            sRect(px - 2, pGroundY - 1, 10, 3, 'rgba(2, 8, 16, 0.42)');
            sRect(px - 1, pGroundY - 4, 8, 5, stoneDark);
            sRect(px, archTopY, 6, pGroundY - archTopY, stoneMid);
            sRect(px, archTopY, 2, pGroundY - archTopY, stoneHi);
            sRect(px + 4, archTopY, 2, pGroundY - archTopY, stoneDark);
            for (let sy = archTopY + 6; sy < pGroundY - 5; sy += 7) {
                sRect(px, sy, 6, 1, stoneDark);
            }
            sRect(px - 1, archTopY - 2, 8, 2, stoneHi);
        });

        const archCx = gx + 17;
        for (let a = 0; a <= 180; a += 2) {
            const rad = (a * Math.PI) / 180;
            for (let r = 12; r <= 17; r++) {
                const ax = Math.round(archCx + Math.cos(rad) * r);
                const ay = Math.round(archTopY - Math.sin(rad) * (r * 0.85));
                sRect(ax, ay, 2, 2, r >= 16 ? stoneHi : (r <= 13 ? stoneDark : stoneMid));
            }
        }
        sRect(archCx - 1, archTopY - 16, 3, 4, stoneHi);

        [gx + 2, gx + 30].forEach((stemBaseX, sIdx) => {
            const pGroundY = getGroundY(stemBaseX, 'botanical', pw, ph) + 1;
            for (let vy = pGroundY; vy >= archTopY - 2; vy--) {
                const vx = stemBaseX + Math.round(Math.sin(vy * 0.22 + sIdx * 2) * 1.6);
                sRect(vx, vy, 1, 1, '#14532d');
                if (vy % 4 === 0) {
                    const lSide = (vy % 8 === 0) ? -2 : 1;
                    sRect(vx + lSide, vy, 3, 2, '#15803d');
                    sRect(vx + lSide, vy, 2, 1, '#22c55e');
                }
                if (vy % 7 === 0 && vy < pGroundY - 4) {
                    const rSide = (vy % 14 === 0) ? 1 : -2;
                    sRect(vx + rSide, vy - 1, 2, 2, sIdx === 0 ? '#f472b6' : '#c084fc');
                    sRect(vx + rSide, vy - 1, 1, 1, '#fef08a');
                }
            }
        });
        for (let a = 25; a <= 155; a += 8) {
            const rad = (a * Math.PI) / 180;
            const vx = Math.round(archCx + Math.cos(rad) * 15);
            const vy = Math.round(archTopY - Math.sin(rad) * 12.5);
            sRect(vx - 1, vy, 3, 2, '#15803d');
            if (a % 24 === 1) {
                sRect(vx, vy - 1, 2, 2, '#f472b6');
                sRect(vx, vy - 1, 1, 1, '#fef08a');
            }
        }

        const fx = Math.round(pw * 0.18);
        const fy = getGroundY(fx, 'botanical', pw, ph) + 1;
        sRect(fx - 16, fy, 33, 3, 'rgba(2, 8, 16, 0.45)');
        sRect(fx - 15, fy - 4, 31, 4, stoneDark);
        sRect(fx - 16, fy - 5, 33, 2, stoneHi);
        sRect(fx - 13, fy - 5, 27, 1, isLightMode ? '#38bdf8' : '#0284c7');
        sRect(fx - 6, fy - 6, 13, 2, stoneMid);
        sRect(fx - 3, fy - 18, 7, 12, stoneMid);
        sRect(fx - 2, fy - 18, 2, 12, stoneHi);
        sRect(fx + 2, fy - 18, 2, 12, stoneDark);
        sRect(fx - 13, fy - 21, 27, 3, stoneMid);
        sRect(fx - 15, fy - 23, 31, 2, stoneHi);
        sRect(fx - 12, fy - 23, 25, 1, isLightMode ? '#38bdf8' : '#7dd3fc');
        sRect(fx - 2, fy - 28, 5, 5, stoneMid);
        sRect(fx - 1, fy - 28, 2, 5, stoneHi);
        sRect(fx - 4, fy - 29, 9, 1, stoneHi);
        sRect(fx - 1, fy - 31, 3, 2, stoneHi);

        const mossTop = isLightMode ? '#16a34a' : '#0f3d32';
        const mossMid = isLightMode ? '#15803d' : '#0a2922';
        const mossDeep = isLightMode ? '#14532d' : '#061a17';
        for (let x = 0; x < pw; x++) {
            const gy = getGroundY(x, 'botanical', pw, ph);
            sRect(x, gy, 1, ph - gy, mossDeep);
            sRect(x, gy + 2, 1, 3, mossMid);
            sRect(x, gy, 1, 2, mossTop);
            if (x % 4 === 0) {
                sRect(x, gy - 1, 1, 1, isLightMode ? '#4ade80' : '#10b981');
            }
        }

        for (let i = 0; i < 16; i++) {
            const progress = i / 15;
            const pathX = Math.round(pw * 0.5 + Math.sin(i * 0.45) * (14 + progress * 10));
            const pathY = ph - 2 - Math.round((1 - progress) * 9);
            const stoneW = 3 + (i % 3) * 2;
            sRect(pathX - stoneW - 1, pathY + 1, (stoneW + 1) * 2, 2, 'rgba(2, 8, 16, 0.35)');
            sRect(pathX - stoneW, pathY, stoneW * 2, 2, stoneDark);
            sRect(pathX - stoneW + 1, pathY, stoneW * 2 - 2, 1, stoneHi);
        }
        // BÖLÜM SONU: BOTANİK BAHÇE STATİK ÇEVRESİ
    }
       
    else if (hab.sceneProfile === 'reef') {
        // BÖLÜM BAŞI: MERCAN RESİFİ STATİK ÇEVRESİ
        const rockDark = isLightMode ? '#0f2942' : '#090d24';
        const rockMid = isLightMode ? '#163e5c' : '#13193b';
        const rockHi = isLightMode ? '#1e5678' : '#232d5e';
        const rockRim = isLightMode ? '#38bdf8' : '#3b4c8a';

        const reefFloorY = (x) => {
            const nx = x / Math.max(1, pw);
            const sideMound = nx < 0.26 ? Math.pow((0.26 - nx) / 0.26, 1.5) * 34
                            : (nx > 0.74 ? Math.pow((nx - 0.74) / 0.26, 1.5) * 34 : 0);
            return Math.round(getGroundY(x, 'reef', pw, ph) - sideMound);
        };

        const farAtollCol = isLightMode ? 'rgba(12, 42, 68, 0.22)' : 'rgba(8, 12, 36, 0.48)';
        const midAtollCol = isLightMode ? 'rgba(15, 52, 82, 0.34)' : 'rgba(12, 18, 50, 0.65)';
        for (let x = 0; x < pw; x += 2) {
            const nx = x / Math.max(1, pw);
            const lagoonOpen = 0.45 + Math.pow(Math.abs(nx - 0.5) * 1.9, 1.3) * 0.85;
            const gy = getGroundY(x, 'reef', pw, ph);
            const farH = Math.round((42 + Math.sin(x * 0.022 + 0.5) * 12 + Math.cos(x * 0.05) * 6) * lagoonOpen);
            sRect(x, gy - farH, 2, farH, farAtollCol);
            const midH = Math.round((26 + Math.cos(x * 0.032 - 0.4) * 9 + Math.sin(x * 0.08) * 4) * lagoonOpen);
            sRect(x, gy - midH, 2, midH, midAtollCol);
        }

        const colShade = isLightMode ? 'rgba(15, 42, 68, 0.48)' : 'rgba(17, 14, 48, 0.72)';
        const colMid = isLightMode ? 'rgba(22, 62, 92, 0.52)' : 'rgba(28, 25, 68, 0.75)';
        const colHi = isLightMode ? 'rgba(56, 189, 248, 0.28)' : 'rgba(139, 92, 246, 0.26)';
        const colMoss = isLightMode ? 'rgba(20, 184, 166, 0.45)' : 'rgba(192, 132, 252, 0.32)';
        const ruinX = Math.round(pw * 0.26);

        [
            { cx: ruinX - 15, ch: 52, broken: false },
            { cx: ruinX + 15, ch: 38, broken: true },
            { cx: Math.round(pw * 0.76), ch: 44, broken: true }
        ].forEach(col => {
            const cy = reefFloorY(col.cx + 4) + 3;
            sRect(col.cx - 3, cy - 3, 15, 4, colShade);
            sRect(col.cx - 2, cy - 5, 13, 2, colMid);
            sRect(col.cx - 2, cy - 5, 11, 1, colHi);

            sRect(col.cx, cy - col.ch, 9, col.ch - 4, colShade);
            sRect(col.cx + 1, cy - col.ch, 6, col.ch - 4, colMid);
            sRect(col.cx + 1, cy - col.ch, 2, col.ch - 4, colHi);
            sRect(col.cx + 5, cy - col.ch + 3, 1, col.ch - 7, colHi);

            for (let sy = cy - col.ch + 8; sy < cy - 8; sy += 10) {
                sRect(col.cx, sy, 9, 1, colShade);
                sRect(col.cx + 6, sy - 1, 3, 2, colMoss);
            }

            if (!col.broken) {
                sRect(col.cx - 2, cy - col.ch - 2, 13, 3, colShade);
                sRect(col.cx - 2, cy - col.ch - 2, 11, 1, colHi);
                sRect(col.cx - 4, cy - col.ch - 5, 17, 3, colShade);
                sRect(col.cx - 4, cy - col.ch - 5, 15, 1, colHi);
                sRect(col.cx - 3, cy - col.ch - 6, 8, 1, colMoss);
            } else {
                sRect(col.cx, cy - col.ch - 2, 6, 2, colShade);
                sRect(col.cx + 1, cy - col.ch - 3, 3, 1, colHi);
                sRect(col.cx + 4, cy - col.ch - 1, 4, 1, colMoss);
            }
        });

        // Kırık sağ sütundan düşüp resif tabanına oturmuş antik taş blok (havada durmaz)
        const fallenX = ruinX - 2;
        const fallenY = reefFloorY(fallenX + 6);
        sRect(fallenX - 1, fallenY - 3, 14, 4, colShade);
        sRect(fallenX, fallenY - 4, 12, 2, colMid);
        sRect(fallenX, fallenY - 4, 10, 1, colHi);
        sRect(fallenX + 3, fallenY - 5, 5, 1, colMoss);

        const bommies = [
            { cx: Math.round(pw * 0.06), rx: Math.round(pw * 0.18), h: 52 },
            { cx: Math.round(pw * 0.17), rx: Math.round(pw * 0.12), h: 32 },
            { cx: Math.round(pw * 0.83), rx: Math.round(pw * 0.12), h: 34 },
            { cx: Math.round(pw * 0.94), rx: Math.round(pw * 0.18), h: 54 }
        ];
        bommies.forEach((bm, bIdx) => {
            const baseY = ph;
            const topY = ph - bm.h;
            for (let y = topY; y < baseY; y++) {
                const prog = (y - topY) / bm.h;
                const strata = Math.sin(y * 0.22 + bIdx) * 3;
                const halfW = Math.round(bm.rx * Math.pow(prog, 0.65) + strata);
                const left = Math.max(0, bm.cx - halfW);
                const right = Math.min(pw, bm.cx + halfW);
                const w = Math.max(1, right - left);

                sRect(left, y, w, 1, rockDark);
                sRect(left + 2, y, Math.max(1, w - 4), 1, prog < 0.32 ? rockHi : rockMid);
                if (y === topY || (y % 7 === 0 && w > 10)) {
                    sRect(left + 3, y, Math.max(2, w - 6), 1, prog < 0.25 ? rockRim : rockHi);
                }
                if (!isLightMode && y % 11 === 0 && w > 14) {
                    sRect(left + 5 + (bIdx * 3), y, 4, 1, 'rgba(56, 189, 248, 0.28)');
                }
            }
        });

        const sandDark = isLightMode ? '#1e4e68' : '#111a3a';
        const sandHi = isLightMode ? '#38bdf8' : '#1e2952';

        for (let x = 0; x < pw; x++) {
            const nx = x / Math.max(1, pw);
            const gy = reefFloorY(x);
            const inCenterSand = nx > 0.30 && nx < 0.70;

            sRect(x, gy, 1, ph - gy, rockDark);
            sRect(x, gy + 1, 1, Math.max(1, Math.floor((ph - gy) * 0.45)), inCenterSand ? sandDark : rockMid);
            sRect(x, gy, 1, 2, x % 9 === 0 ? '#38bdf8' : (inCenterSand ? sandHi : rockHi));
            if (!isLightMode && (x % 17 === 0)) {
                sRect(x, gy + 4 + (x % 5), 3, 1, 'rgba(56, 189, 248, 0.35)');
            }
        }
        // BÖLÜM SONU: MERCAN RESİFİ STATİK ÇEVRESİ
    }
        
    else if (hab.sceneProfile === 'koi-pond') {
        // BÖLÜM BAŞI: KOİ GÖLETİ STATİK ÇEVRESİ
        const stoneDark = isLightMode ? '#334155' : '#0f172a';
        const stoneMid = isLightMode ? '#475569' : '#1e293b';
        const stoneHi = isLightMode ? '#64748b' : '#334155';
        const stoneRim = isLightMode ? '#94a3b8' : '#475569';
        const mossDark = isLightMode ? '#14532d' : '#062e22';
        const mossMid = isLightMode ? '#15803d' : '#0d4a36';
        const mossHi = isLightMode ? '#22c55e' : '#10b981';

        const waterTop = isLightMode ? '#0f766e' : '#082230';
        const waterMid = isLightMode ? '#115e59' : '#061a26';
        const waterDeep = isLightMode ? '#134e4a' : '#04121b';
        const waterSteps = 28;
        for (let s = 0; s < waterSteps; s++) {
            const t = s / (waterSteps - 1);
            const wy = Math.floor(18 + t * (ph - 18));
            const wh = Math.ceil((ph - 18) / waterSteps) + 1;
            const col = t < 0.5 ? lerpHex(waterTop, waterMid, t * 2) : lerpHex(waterMid, waterDeep, (t - 0.5) * 2);
            sRect(0, wy, pw, wh, col);
        }

        for (let x = 0; x < pw; x++) {
            const bankH = Math.round(18 + Math.sin(x * 0.03) * 4 + Math.cos(x * 0.08) * 2);
            sRect(x, 0, 1, bankH, isLightMode ? '#1e293b' : '#09131c');
            sRect(x, 0, 1, Math.max(2, bankH - 5), mossDark);
            if (x % 3 === 0) sRect(x, bankH - 6, 2, 2, mossMid);
            if (x % 7 === 0) sRect(x, bankH - 7, 2, 1, mossHi);
            sRect(x, bankH - 4, 1, 3, stoneDark);
            if (x % 8 < 5) sRect(x, bankH - 3, 1, 2, stoneMid);
            sRect(x, bankH - 1, 1, 1, stoneHi);
            sRect(x, bankH, 1, 4, 'rgba(2, 8, 16, 0.48)');
            sRect(x, bankH + 4, 1, 1, isLightMode ? 'rgba(186, 230, 253, 0.35)' : 'rgba(56, 189, 248, 0.16)');
        }

        const brStart = Math.round(pw * 0.60);
        const brWidth = Math.min(88, Math.round(pw * 0.20));
        const redDark = isLightMode ? '#7f1d1d' : '#450a0a';
        const redMid = isLightMode ? '#dc2626' : '#991b1b';
        const redHi = isLightMode ? '#f87171' : '#ef4444';

        [brStart - 2, brStart + brWidth - 2].forEach(pierX => {
            sRect(pierX - 1, 15, 6, 11, stoneDark);
            sRect(pierX, 16, 4, 8, stoneMid);
            sRect(pierX, 15, 4, 1, stoneRim);
            sRect(pierX - 1, 25, 6, 2, 'rgba(2, 8, 16, 0.45)');
        });

        for (let bx = 0; bx <= brWidth; bx++) {
            const t = bx / brWidth;
            const arch = Math.round(Math.sin(t * Math.PI) * 9);
            const wx = brStart + bx;
            const wy = 21 - arch;

            sRect(wx, 25 + Math.floor(arch * 0.45), 1, 2, 'rgba(220, 38, 38, 0.18)');
            if (bx % 9 === 0 || bx === brWidth) {
                sRect(wx, wy + 2, 2, Math.max(2, 24 - wy), '#3b1806');
            }
            sRect(wx, wy + 3, 1, 3, '#451a03');
            sRect(wx, wy + 3, 1, 1, '#78350f');
            sRect(wx, wy, 1, 2, redMid);
            sRect(wx, wy - 3, 1, 1, redMid);
            sRect(wx, wy - 4, 1, 1, redHi);

            if (bx % 9 === 0 || bx === brWidth) {
                sRect(wx, wy - 5, 2, 8, redDark);
                sRect(wx, wy - 5, 1, 7, redMid);
                sRect(wx, wy - 6, 2, 1, '#fbbf24');
                sRect(wx, wy - 7, 1, 1, '#fef08a');
            }
        }

        const mapleReach = Math.min(150, Math.round(pw * 0.30));
        const trunkDark = isLightMode ? '#3b1d14' : '#181014';
        const trunkMid = isLightMode ? '#5c2d1e' : '#291b21';
        const trunkHi = isLightMode ? '#7c3f2a' : '#3d2830';
        const mapleDark = isLightMode ? '#7f1d1d' : '#4c0d14';
        const mapleMid = isLightMode ? '#dc2626' : '#991b1b';
        const mapleHi = isLightMode ? '#f87171' : '#ef4444';
        const mapleGold = '#f59e0b';

        const leftBankY = getGroundY(0, 'koi-pond', pw, ph) + 2;
        for (let y = 0; y < leftBankY; y++) {
            const prog = y / leftBankY;
            const lean = Math.sin((1 - prog) * Math.PI * 0.5) * 10;
            const rootFlare = prog > 0.72 ? Math.pow((prog - 0.72) / 0.28, 2) * 16 : 0;
            const tw = Math.round(12 + prog * 5 + rootFlare);
            const tx = Math.max(0, Math.round(lean));
            sRect(tx, y, tw, 1, trunkDark);
            sRect(tx + tw - 5, y, 3, 1, trunkMid);
            sRect(tx + tw - 2, y, 2, 1, trunkHi);
            if (prog > 0.75 && y % 2 === 0) {
                sRect(tx + 1, y, 3, 1, mossMid);
            }
        }

        [0.06, 0.28, 0.50, 0.72, 0.90].forEach((tNode, idx) => {
            const cx = Math.round(tNode * mapleReach);
            const branchY = Math.round(6 + Math.pow(tNode, 1.2) * 14);
            const rx = Math.round(29 * (1 - tNode * 0.28));
            const bottomY = branchY + Math.round(9 * (1 - tNode * 0.26));

            for (let y = 0; y <= bottomY; y++) {
                const normY = (y - branchY * 0.5) / Math.max(1, bottomY - branchY * 0.5);
                const ellipse = Math.max(0, 1 - normY * normY);
                const scallop = Math.sin(y * 0.9 + idx) * 2;
                const span = Math.round(rx * (y < branchY * 0.5 ? 1 : Math.sqrt(ellipse)) + scallop);
                let col = y < branchY * 0.35 ? mapleHi : (y > branchY ? mapleDark : mapleMid);
                if ((y + idx) % 5 === 0 && span > 6) col = mapleGold;
                sRect(cx - span, y, span * 2, 1, col);
            }
        });

        for (let s = 0; s <= mapleReach; s++) {
            const t = s / Math.max(1, mapleReach);
            const by = Math.round(6 + Math.pow(t, 1.2) * 14 + Math.sin(s * 0.09) * 1.5);
            const thick = Math.max(2, Math.round(8 * (1 - t * 0.75)));
            sRect(s, by - Math.floor(thick * 0.5), 1, thick, trunkDark);
            sRect(s, by - Math.floor(thick * 0.5), 1, 1, trunkMid);
            sRect(s, by + Math.ceil(thick * 0.5) - 1, 1, 1, trunkHi);
            if (s > 18 && s % 26 === 0 && s < mapleReach - 14) {
                for (let sub = 0; sub < 10; sub++) {
                    sRect(s + sub, by - 2 - Math.floor(sub * 0.5), 1, 2, trunkDark);
                }
            }
        }

        for (let x = 0; x < pw; x++) {
            const nx = x / Math.max(1, pw);
            if (nx > 0.28 && nx < 0.70) continue;
            const gy = getGroundY(x, 'koi-pond', pw, ph);
            sRect(x, gy - 3, 1, 4, 'rgba(2, 8, 16, 0.48)');
            sRect(x, gy - 1, 1, 2, stoneDark);
            sRect(x, gy, 1, ph - gy, mossDark);
            sRect(x, gy, 1, 2, mossMid);
            if (x % 4 === 0) sRect(x, gy - 1, 2, 1, mossHi);
        }

        [
            { cx: 22, cy: ph - 10, rx: 14, ry: 7 },
            { cx: 46, cy: ph - 6, rx: 11, ry: 5 },
            { cx: 68, cy: ph - 4, rx: 8, ry: 4 },
            { cx: pw - 68, cy: ph - 8, rx: 13, ry: 6 }
        ].forEach(rock => {
            sRect(rock.cx - rock.rx - 1, rock.cy + 2, (rock.rx + 1) * 2, 4, 'rgba(2, 8, 16, 0.48)');
            for (let dy = -rock.ry; dy <= 2; dy++) {
                const span = Math.round(rock.rx * Math.sqrt(Math.max(0, 1 - (dy * dy) / ((rock.ry + 2) * (rock.ry + 2)))));
                sRect(rock.cx - span, rock.cy + dy, span * 2, 1, dy < -2 ? stoneHi : (dy > 0 ? stoneDark : stoneMid));
                if (dy === -rock.ry) sRect(rock.cx - Math.floor(span * 0.5), rock.cy + dy, Math.max(2, span), 1, stoneRim);
                if (dy === -rock.ry + 1) sRect(rock.cx - Math.floor(span * 0.6), rock.cy + dy, Math.floor(span * 1.2), 1, mossHi);
            }
        });

        const bx = pw - 42;
        const by = ph - 18;
        sRect(bx - 22, by + 7, 58, 11, 'rgba(2, 8, 16, 0.52)');
        sRect(bx - 20, by + 5, 56, 12, stoneDark);
        for (let sx = bx - 18; sx <= bx + 28; sx += 7) {
            sRect(sx, by + 5, 5, 3, stoneMid);
            sRect(sx, by + 5, 4, 1, stoneHi);
        }
        sRect(bx - 16, by + 3, 46, 4, mossDark);
        sRect(bx - 14, by + 2, 42, 2, mossMid);
        sRect(bx - 12, by + 1, 36, 2, mossHi);

        sRect(bx - 7, by, 3, 3, stoneDark);
        sRect(bx + 5, by, 3, 3, stoneDark);
        sRect(bx - 6, by - 2, 13, 3, stoneMid);
        sRect(bx - 5, by - 2, 11, 1, stoneHi);
        sRect(bx - 3, by - 10, 7, 8, stoneMid);
        sRect(bx - 2, by - 10, 2, 8, stoneHi);
        sRect(bx - 5, by - 11, 11, 2, stoneHi);

        sRect(bx - 5, by - 17, 11, 6, stoneDark);
        sRect(bx - 3, by - 16, 7, 4, '#fef08a');
        sRect(bx, by - 16, 1, 4, stoneDark);
        sRect(bx - 11, by - 19, 23, 2, stoneDark);
        sRect(bx - 12, by - 18, 2, 1, stoneHi);
        sRect(bx + 11, by - 18, 2, 1, stoneHi);
        sRect(bx - 9, by - 21, 19, 2, stoneMid);
        sRect(bx - 6, by - 23, 13, 2, stoneHi);
        sRect(bx - 3, by - 24, 7, 1, mossMid);
        sRect(bx - 1, by - 26, 3, 2, stoneRim);

        sRect(bx - 14, by - 9, 2, 12, '#3f6212');
        sRect(bx - 14, by - 9, 1, 12, '#65a30d');
        sRect(bx - 11, by - 6, 2, 9, '#365314');
        sRect(bx - 22, by - 4, 13, 2, '#65a30d');
        sRect(bx - 22, by - 4, 12, 1, '#a3e635');
        sRect(bx - 15, by - 5, 3, 4, '#451a03');
        // BÖLÜM SONU: KOİ GÖLETİ STATİK ÇEVRESİ
    }

   else if (hab.sceneProfile === 'arctic-tundra') {
        // BÖLÜM BAŞI: KUTUP TUNDURASI STATİK ÇEVRESİ
        const rockDeep = isLightMode ? '#1e293b' : '#070d19';
        const rockDark = isLightMode ? '#334155' : '#0f172a';
        const rockMid = isLightMode ? '#475569' : '#1e293b';
        const rockHi = isLightMode ? '#64748b' : '#334155';
        const iceVein = isLightMode ? '#bae6fd' : '#164e63';
        const snowTop = isLightMode ? '#ffffff' : '#e0f2fe';
        const snowMid = isLightMode ? '#e2e8f0' : '#bae6fd';
        const snowShadow = isLightMode ? '#94a3b8' : '#38bdf8';

        const drawSnowPine = (cx, baseY, h) => {
            sRect(cx - Math.round(h * 0.24), baseY - 1, Math.round(h * 0.48), 3, 'rgba(7, 13, 25, 0.42)');
            sRect(cx - 2, baseY - 9, 4, 10, '#271712');
            sRect(cx - 1, baseY - 9, 1, 9, '#5c3a21');
            sRect(cx - 4, baseY - 2, 8, 2, snowMid);
            sRect(cx - 3, baseY - 3, 6, 1, snowTop);

            const needleDark = isLightMode ? '#0f3d3e' : '#042022';
            const needleMid = isLightMode ? '#134e4a' : '#083335';
            const needleHi = isLightMode ? '#0f766e' : '#115e59';
            const tiers = 6;

            for (let t = 0; t < tiers; t++) {
                const prog = t / tiers;
                const ty = baseY - 6 - Math.round(prog * (h - 9));
                const th = Math.max(4, Math.round((h / tiers) * 1.48));
                const maxW = Math.round(3 + (1 - prog * 0.82) * (h * 0.28));

                for (let dy = 0; dy < th; dy++) {
                    const ratio = dy / th;
                    const scallop = Math.sin(dy * 1.2 + t) * 0.8;
                    const w = Math.max(1, Math.round(ratio * maxW + scallop));
                    const py = ty - th + dy;

                    if (dy <= 1) {
                        sRect(cx - w, py, w * 2 + 1, 1, snowTop);
                    } else if (dy === 2) {
                        sRect(cx - w, py, w * 2 + 1, 1, snowMid);
                    } else {
                        sRect(cx - w, py, w * 2 + 1, 1, dy > th - 2 ? needleDark : needleMid);
                        sRect(cx - Math.max(1, Math.floor(w * 0.65)), py, Math.max(2, w), 1, needleHi);
                        if (dy === th - 2 && w > 3) {
                            sRect(cx - w, py, 2, 1, snowTop);
                            sRect(cx + w - 1, py, 2, 1, snowMid);
                        }
                    }
                }
            }
            sRect(cx, baseY - h - 2, 1, 3, snowTop);
        };

        const drawCliffMassif = (ledge, tierDepth, attachSide) => {
            const spanX1 = attachSide === 'left' ? 0 : ledge.x1;
            const spanX2 = attachSide === 'right' ? pw - 1 : ledge.x2;
            const darken = tierDepth === 'high' ? rockDeep : rockDark;
            const midCol = tierDepth === 'high' ? rockDark : rockMid;
            const hiCol = tierDepth === 'high' ? rockMid : rockHi;

            for (let x = spanX1; x <= spanX2; x++) {
                const clampedX = Math.max(ledge.x1, Math.min(ledge.x2, x));
                const ly = ledge.yFn(clampedX);
                const valleyY = getGroundY(x, 'arctic-tundra', pw, ph);
                const outerDist = attachSide === 'left' ? (spanX2 - x) : (attachSide === 'right' ? (x - spanX1) : Math.min(x - spanX1, spanX2 - x));
                const shoulderDrop = outerDist < 7 ? Math.round(Math.pow(7 - outerDist, 1.35) * 0.9) : 0;
                const topY = ly + shoulderDrop;
                const cliffH = Math.max(6, valleyY - topY + 3);

                sRect(x, topY, 1, cliffH, darken);

                for (let y = topY + 2; y < topY + cliffH - 2; y += 2) {
                    const strata = Math.sin(x * 0.14 + y * 0.08) + Math.cos(y * 0.22 - x * 0.05);
                    if (strata > 0.45) {
                        sRect(x, y, 1, 2, midCol);
                    }
                    if (strata > 1.15 && outerDist > 4) {
                        sRect(x, y, 1, 1, hiCol);
                    }
                }

                if ((x + ledge.id * 5) % 17 === 0 && outerDist > 6 && cliffH > 18) {
                    const creviceH = Math.min(cliffH - 8, 10 + (x % 9));
                    sRect(x, topY + 5, 1, creviceH, rockDeep);
                    sRect(x + 1, topY + 6, 1, Math.max(2, creviceH - 3), iceVein);
                }

                sRect(x, topY + cliffH - 3, 1, 3, snowMid);
                sRect(x, topY + cliffH - 4, 1, 1, snowShadow);

                if (x >= ledge.x1 && x <= ledge.x2) {
                    const overhang = 2 + (x % 3 === 0 ? 1 : 0);
                    sRect(x, ly + 1, 1, overhang, snowShadow);
                    sRect(x, ly - 1, 1, 2, snowMid);
                    sRect(x, ly - 2, 1, 2, snowTop);

                    if (x % 9 === 0 && outerDist > 5) {
                        const icicleLen = 3 + ((x * 3) % 5);
                        sRect(x, ly + overhang + 1, 1, icicleLen, '#7dd3fc');
                        sRect(x, ly + overhang + 1, 1, Math.max(1, icicleLen - 2), '#e0f2fe');
                    }
                }
            }
        };

        const drawNordicCabin = (cabX, cabY) => {
            sRect(cabX - 15, cabY - 1, 30, 3, 'rgba(7, 13, 25, 0.48)');
            sRect(cabX - 13, cabY - 3, 26, 3, rockDark);
            for (let sx = cabX - 12; sx <= cabX + 8; sx += 5) {
                sRect(sx, cabY - 3, 3, 2, rockHi);
            }

            const chX = cabX + 5;
            sRect(chX, cabY - 23, 5, 12, rockDark);
            sRect(chX + 1, cabY - 23, 3, 11, rockMid);
            sRect(chX, cabY - 24, 5, 1, rockHi);
            sRect(chX + 1, cabY - 25, 3, 1, snowTop);

            const logDark = '#3b1806';
            const logMid = '#6b2f0e';
            const logHi = '#92400e';
            sRect(cabX - 12, cabY - 14, 24, 11, logDark);
            for (let ly = cabY - 13; ly < cabY - 3; ly += 2) {
                sRect(cabX - 11, ly, 22, 1, logMid);
                sRect(cabX - 10, ly, 14, 1, logHi);
                sRect(cabX - 13, ly, 2, 1, '#b45309');
                sRect(cabX + 11, ly, 2, 1, '#78350f');
            }

            for (let g = 1; g <= 7; g++) {
                const gw = Math.max(1, 12 - Math.floor(g * 1.5));
                sRect(cabX - gw, cabY - 14 - g, gw * 2, 1, g % 2 === 0 ? logMid : logDark);
            }

            sRect(cabX - 8, cabY - 10, 4, 7, '#271105');
            sRect(cabX - 7, cabY - 9, 2, 5, '#451a03');
            sRect(cabX - 6, cabY - 6, 1, 1, '#fbbf24');

            sRect(cabX - 2, cabY - 11, 9, 6, '#271105');
            sRect(cabX - 1, cabY - 10, 7, 4, '#f59e0b');
            sRect(cabX, cabY - 9, 5, 2, '#fef08a');
            sRect(cabX + 2, cabY - 10, 1, 4, '#271105');
            sRect(cabX - 1, cabY - 8, 7, 1, '#271105');
            sRect(cabX - 2, cabY - 5, 9, 1, snowTop);

            for (let wx = 0; wx < 4; wx++) {
                sRect(cabX + 8 + wx, cabY - 5 - (wx % 2), 2, 2, '#451a03');
                sRect(cabX + 8 + wx, cabY - 5 - (wx % 2), 1, 1, '#d97706');
            }

            for (let r = 0; r <= 9; r++) {
                const rw = 16 - Math.floor(r * 1.5);
                const ry = cabY - 14 - r;
                sRect(cabX - rw, ry, rw * 2, 1, '#1e130c');
                sRect(cabX - rw - 1, ry - 1, rw * 2 + 2, 1, snowMid);
                sRect(cabX - rw, ry - 2, rw * 2, 1, snowTop);
            }
            sRect(cabX - 16, cabY - 13, 1, 2, '#bae6fd');
            sRect(cabX + 15, cabY - 13, 1, 3, '#bae6fd');

            sRect(cabX - 14, cabY - 2, 5, 2, snowTop);
            sRect(cabX + 9, cabY - 2, 6, 2, snowTop);
        };

        const farMountCol = isLightMode ? 'rgba(100, 116, 139, 0.28)' : 'rgba(15, 28, 52, 0.55)';
        const midMountCol = isLightMode ? 'rgba(71, 85, 105, 0.42)' : 'rgba(17, 36, 64, 0.78)';
        const mountSnowCol = isLightMode ? 'rgba(255, 255, 255, 0.75)' : 'rgba(186, 230, 253, 0.32)';
        const mountShadowSnow = isLightMode ? 'rgba(203, 213, 225, 0.55)' : 'rgba(56, 189, 248, 0.16)';

        for (let x = 0; x < pw; x++) {
            const nx = x / Math.max(1, pw);
            const gy = getGroundY(x, 'arctic-tundra', pw, ph);
            const valleyOpen = 0.36 + Math.pow(Math.abs(nx - 0.5) * 1.92, 1.35) * 0.92;

            const farRidge = Math.abs(Math.sin(x * 0.017 + 0.8)) * 34 + Math.abs(Math.cos(x * 0.041)) * 12;
            const farH = Math.round((24 + farRidge) * valleyOpen);
            sRect(x, gy - farH, 1, farH, farMountCol);
            if (farH > 32) {
                sRect(x, gy - farH, 1, 4, mountShadowSnow);
            }

            const midRidge = Math.abs(Math.sin(x * 0.024 - 0.3)) * 26 + Math.cos(x * 0.058) * 7;
            const midH = Math.round((18 + midRidge) * valleyOpen);
            sRect(x, gy - midH, 1, midH, midMountCol);
            if (midH > 24) {
                const snowCapH = 4 + Math.round(Math.max(0, Math.sin(x * 0.024 - 0.3)) * 6);
                sRect(x, gy - midH, 1, snowCapH, (x % 14 < 7) ? mountSnowCol : mountShadowSnow);
            }
        }

        const ledges = getArcticLedges(pw, ph);

        // 1. Üst Teraslar (Ledge 3 ve Ledge 6) + Üst Ağaçlar
        drawCliffMassif(ledges[3], 'high', 'left');
        drawCliffMassif(ledges[6], 'high', 'right');
        drawSnowPine(22, ledges[3].yFn(22) + 1, 46);
        drawSnowPine(Math.round(pw * 0.12), ledges[3].yFn(Math.round(pw * 0.12)) + 1, 36);
        drawSnowPine(pw - 24, ledges[6].yFn(pw - 24) + 1, 48);
        drawSnowPine(Math.round(pw * 0.86), ledges[6].yFn(Math.round(pw * 0.86)) + 1, 38);

        // 2. Orta Teraslar (Ledge 2 ve Ledge 5) + Kuzey Kulübesi ve Orta Ağaçlar
        drawCliffMassif(ledges[2], 'mid', 'none');
        drawCliffMassif(ledges[5], 'mid', 'none');
        drawSnowPine(Math.round(pw * 0.29), ledges[2].yFn(Math.round(pw * 0.29)) + 1, 40);
        const cabX = Math.round(pw * 0.73);
        const cabY = ledges[5].yFn(cabX) + 1;
        drawNordicCabin(cabX, cabY);
        drawSnowPine(Math.round(pw * 0.66), ledges[5].yFn(Math.round(pw * 0.66)) + 1, 34);

        // 3. Alt Teraslar (Ledge 1 ve Ledge 4) + Ön Plan Ağaçları
        drawCliffMassif(ledges[1], 'low', 'left');
        drawCliffMassif(ledges[4], 'low', 'right');
        drawSnowPine(Math.round(pw * 0.14), ledges[1].yFn(Math.round(pw * 0.14)) + 1, 52);
        drawSnowPine(Math.round(pw * 0.88), ledges[4].yFn(Math.round(pw * 0.88)) + 1, 54);

        // 4. Ana Vadi Kar Tabanı (Ledge 0) ve Buzul Kıyısı
        for (let x = 0; x < pw; x++) {
            const nx = x / Math.max(1, pw);
            const gy = getGroundY(x, 'arctic-tundra', pw, ph);
            const inFrozenCreek = Math.abs(nx - 0.50) < 0.09;

            if (inFrozenCreek) {
                sRect(x, gy, 1, ph - gy, isLightMode ? '#7dd3fc' : '#0c4a6e');
                sRect(x, gy, 1, 2, isLightMode ? '#e0f2fe' : '#38bdf8');
                if ((x + 3) % 7 === 0) {
                    sRect(x, gy + 2, 2, 1, '#bae6fd');
                }
            } else {
                sRect(x, gy, 1, ph - gy, snowMid);
                sRect(x, gy, 1, 3, snowTop);
                sRect(x, gy + 3, 1, 2, snowShadow);
            }
        }
        // BÖLÜM SONU: KUTUP TUNDURASI STATİK ÇEVRESİ
    }

   else if (hab.sceneProfile === 'rainforest') {
        // BÖLÜM BAŞI: YAĞMUR ORMANI STATİK ÇEVRESİ (YAŞAYAN PİKSEL SANAT DİORAMASI)
        const canopyShades = isLightMode
            ? ['#063125', '#0b4d37', '#116b46', '#1e8c54', '#3ab56d']
            : ['#031a16', '#062c24', '#0b4232', '#135c42', '#1d7a55'];

        const farTepuiCol = isLightMode ? 'rgba(13, 74, 62, 0.22)' : 'rgba(6, 30, 28, 0.45)';
        const farTepuiRim = isLightMode ? 'rgba(167, 243, 208, 0.24)' : 'rgba(45, 212, 191, 0.14)';
        const valleyMistCol = isLightMode ? 'rgba(236, 253, 245, 0.28)' : 'rgba(20, 83, 75, 0.18)';
        const farJungleCol = isLightMode ? 'rgba(11, 61, 46, 0.28)' : 'rgba(4, 24, 21, 0.52)';
        const midJungleCol = isLightMode ? 'rgba(13, 74, 56, 0.44)' : 'rgba(5, 34, 28, 0.72)';
        const understoryCol = isLightMode ? 'rgba(15, 82, 58, 0.58)' : 'rgba(6, 40, 31, 0.84)';

        // 1. Uzak sisli Tepui masa dağları (atmosferik perspektif derinliği)
        const tepuis = [
            { cx: pw * 0.30, topW: pw * 0.11, baseW: pw * 0.22, h: Math.round(ph * 0.44) },
            { cx: pw * 0.68, topW: pw * 0.13, baseW: pw * 0.25, h: Math.round(ph * 0.48) }
        ];
        tepuis.forEach(tp => {
            const topY = ph - tp.h;
            for (let y = topY; y < ph - 20; y++) {
                const prog = (y - topY) / Math.max(1, tp.h - 20);
                const halfW = Math.round(tp.topW * 0.5 + (tp.baseW - tp.topW) * 0.5 * Math.pow(prog, 0.75) + Math.sin(y * 0.22) * 1.4);
                sRect(tp.cx - halfW, y, halfW * 2, 1, farTepuiCol);
                if (y <= topY + 2) {
                    sRect(tp.cx - halfW + 1, y, Math.max(2, halfW - 2), 1, farTepuiRim);
                }
            }
        });
        sRect(0, ph - 66, pw, 16, valleyMistCol);

        // 2. Katmanlı uzak & orta yağmur ormanı sırtları
        for (let x = 0; x < pw; x += 2) {
            const nx = x / Math.max(1, pw);
            const valleyDip = 0.46 + Math.pow(Math.abs(nx - 0.5) * 1.92, 1.35) * 0.88;
            const farH = Math.round((58 + Math.sin(x * 0.018 + 0.6) * 14 + Math.cos(x * 0.045) * 6) * valleyDip);
            sRect(x, ph - farH, 2, farH, farJungleCol);

            const h = Math.round((40 + Math.sin(x * 0.025) * 10 + Math.cos(x * 0.07) * 6) * valleyDip);
            sRect(x, ph - h, 2, h, midJungleCol);

            const bushH = Math.round(18 + Math.sin(x * 0.09) * 5 + Math.cos(x * 0.19) * 3);
            sRect(x, ph - bushH, 2, bushH, understoryCol);
        }

        const drawFoliageDome = (cx, cy, rx, ry, shadeIdx) => {
            const maxIdx = canopyShades.length - 1;
            const baseCol = canopyShades[Math.min(maxIdx, Math.max(0, shadeIdx))];
            const hiCol = canopyShades[Math.min(maxIdx, shadeIdx + 1)];
            const tipCol = canopyShades[Math.min(maxIdx, shadeIdx + 2)];
            const shadowCol = canopyShades[Math.max(0, shadeIdx - 1)];
            for (let dy = -ry; dy <= ry; dy++) {
                const ratio = 1 - (dy * dy) / (ry * ry);
                if (ratio <= 0) continue;
                const scallop = Math.sin(dy * 0.68 + cx * 0.1) * 2.4 + Math.cos(dy * 1.25) * 1.1;
                const span = Math.max(1, Math.round(rx * Math.sqrt(ratio) + scallop));
                let col = baseCol;
                if (dy < -ry * 0.52) col = tipCol;
                else if (dy < -ry * 0.18) col = hiCol;
                else if (dy > ry * 0.34) col = shadowCol;
                sRect(cx - span, cy + dy, span * 2, 1, col);
                if (dy > -ry * 0.6 && dy < ry * 0.25 && dy % 3 === 0 && span > 5) {
                    const clusterW = Math.max(3, Math.floor(span * 0.45));
                    const shift = ((Math.abs(Math.round(cx)) + dy) % 5) - 2;
                    sRect(cx - Math.floor(span * 0.52) + shift, cy + dy, clusterW, 1, dy < 0 ? tipCol : hiCol);
                }
            }
        };

        const drawWoodyLimb = (x0, y0, x1, y1, thickStart, thickEnd, colDark, colHi, mossCol) => {
            const steps = Math.max(1, Math.round(Math.hypot(x1 - x0, y1 - y0)));
            for (let s = 0; s <= steps; s++) {
                const t = s / steps;
                const bx = Math.round(x0 + (x1 - x0) * t);
                const by = Math.round(y0 + (y1 - y0) * t - Math.sin(t * Math.PI) * 2);
                const th = Math.max(2, Math.round(thickStart + (thickEnd - thickStart) * t));
                sRect(bx, by, 2, th, colDark);
                sRect(bx, by, 2, 1, (s % 4 === 0 && t > 0.2 && t < 0.8) ? mossCol : colHi);
            }
        };

        const midgroundTrees = [
            { x: Math.floor(pw * 0.14), top: Math.floor(ph * 0.24), rx: 36, ry: 16, perchDir: 1 },
            { x: Math.floor(pw * 0.27), top: Math.floor(ph * 0.36), rx: 30, ry: 14, perchDir: 1 },
            { x: Math.floor(pw * 0.42), top: Math.floor(ph * 0.32), rx: 28, ry: 13, depth: 'far', perchDir: -1 },
            { x: Math.floor(pw * 0.58), top: Math.floor(ph * 0.30), rx: 29, ry: 13, depth: 'far', perchDir: 1 },
            { x: Math.floor(pw * 0.75), top: Math.floor(ph * 0.34), rx: 31, ry: 14, perchDir: -1 },
            { x: Math.floor(pw * 0.86), top: Math.floor(ph * 0.22), rx: 38, ry: 16, perchDir: -1 },
        ];
        midgroundTrees.forEach((tree, idx) => {
            const isFarTree = tree.depth === 'far';
            const trunkCol = isFarTree
                ? (isLightMode ? '#29352f' : '#0b1816')
                : (isLightMode ? '#2c201b' : '#0e1b19');
            const barkCol = isFarTree
                ? (isLightMode ? '#3e4e46' : '#152925')
                : (isLightMode ? '#523a2e' : '#1f3630');
            const barkRim = isLightMode ? '#735342' : '#2d4d44';
            const mossCol = isLightMode ? '#16a34a' : '#0f766e';
            const fungiCol = isLightMode ? '#f59e0b' : '#b45309';
            const groundBase = ph;

            for (let y = tree.top + 4; y < groundBase; y++) {
                const prog = (y - tree.top) / Math.max(1, groundBase - tree.top);
                const curve = Math.sin(prog * Math.PI * 1.1 + idx) * 2.5;
                const crownFlare = prog < 0.18 ? Math.pow((0.18 - prog) / 0.18, 1.5) * 6 : 0;
                const rootFlare = prog > 0.78 ? Math.pow((prog - 0.78) / 0.22, 2) * 14 : 0;
                const w = Math.round(6 + prog * 6 + crownFlare + rootFlare);
                const tx = Math.round(tree.x + curve - w * 0.5);
                sRect(tx, y, w, 1, trunkCol);
                sRect(tx + 1, y, Math.max(1, Math.floor(w * 0.40)), 1, barkCol);
                if (!isFarTree && w >= 7) {
                    sRect(tx + 1, y, 1, 1, barkRim);
                }
                if (!isFarTree && ((y + idx * 3) % 10 === 0) && prog > 0.20 && prog < 0.84) {
                    const vineOffset = Math.round(Math.sin(y * 0.12 + idx) * (w * 0.3));
                    sRect(tree.x + vineOffset, y, 2, 2, mossCol);
                }
                if (!isFarTree && ((y + idx * 7) % 23 === 0) && prog > 0.42 && prog < 0.78) {
                    const fSide = (idx % 2 === 0) ? tx + w - 1 : tx - 2;
                    sRect(fSide, y, 3, 1, fungiCol);
                }
            }

            // Üst taç yapraklarını taşıyan ana çatal dallar
            [-1, 1].forEach(dir => {
                const limbReach = Math.round(tree.rx * 0.62);
                drawWoodyLimb(
                    tree.x,
                    tree.top + 14,
                    tree.x + dir * limbReach,
                    tree.top + 4,
                    5,
                    2,
                    trunkCol,
                    barkCol,
                    mossCol
                );
            });

            // Papağanların, Tukan'ın, Tembel Hayvan'ın ve epifitlerin tutunduğu gerçek yosunlu yan dal
            const pDir = tree.perchDir || 1;
            const perchY = tree.top + 22;
            const perchStartX = tree.x + Math.round(Math.sin(0.2 * Math.PI * 1.1 + idx) * 2);
            const perchEndX = tree.x + pDir * 24;
            drawFoliageDome(perchEndX + pDir * 4, perchY - 1, Math.round(tree.rx * 0.42), Math.round(tree.ry * 0.48), 1);
            for (let s = 0; s <= 24; s++) {
                const t = s / 24;
                const lx = perchStartX + pDir * s;
                const ly = perchY + Math.round((1 - t) * 4 - Math.sin(t * Math.PI) * 1.5);
                const lThick = Math.max(2, Math.round(4 * (1 - t * 0.45)));
                sRect(lx, ly, 2, lThick, trunkCol);
                sRect(lx, ly, 2, 1, (s % 4 === 0 && s > 4 && s < 20) ? mossCol : barkCol);
            }

            // Çok katmanlı, güneş benekli yağmur ormanı tacı
            drawFoliageDome(tree.x - Math.round(tree.rx * 0.55), tree.top + 7, Math.round(tree.rx * 0.78), Math.round(tree.ry * 0.78), 1);
            drawFoliageDome(tree.x + Math.round(tree.rx * 0.55), tree.top + 8, Math.round(tree.rx * 0.78), Math.round(tree.ry * 0.78), 1);
            drawFoliageDome(tree.x, tree.top, tree.rx, tree.ry, isFarTree ? 1 : 2);
            drawFoliageDome(tree.x - pDir * 6, tree.top - 5, Math.round(tree.rx * 0.68), Math.round(tree.ry * 0.65), isFarTree ? 2 : 3);
        });

        // 3. Zeminle Bütünleşik İki Kademeli Yosunlu Kireçtaşı Falez & Turkuaz Orman Lagünü (Havada durmaz!)
        const wfX = Math.round(pw * 0.50);
        const poolSurfY = ph - 8;
        const cliffH = Math.min(72, Math.max(48, Math.round(ph * 0.25)));
        const cliffTopY = poolSurfY - cliffH;
        const midShelfY = poolSurfY - Math.round(cliffH * 0.46);
        const cliffBaseHalfW = Math.min(38, Math.max(24, Math.round(pw * 0.068)));
        const cliffTopHalfW = Math.round(cliffBaseHalfW * 0.60);
        const poolHalfW = Math.round(cliffBaseHalfW * 0.94);

        const rockDark = isLightMode ? '#1e293b' : '#091119';
        const rockMid = isLightMode ? '#334155' : '#13202d';
        const rockWet = isLightMode ? '#0f2933' : '#06151c';
        const rockHi = isLightMode ? '#64748b' : '#263a4d';
        const mossDeep = isLightMode ? '#064e3b' : '#052e22';
        const mossMid = isLightMode ? '#15803d' : '#0d593d';
        const mossBright = isLightMode ? '#4ade80' : '#10b981';

        for (let y = cliffTopY; y <= poolSurfY + 2; y++) {
            const prog = (y - cliffTopY) / Math.max(1, cliffH);
            const ledgeStep = Math.sin(y * 0.24) * 2.4 + (prog > 0.48 && prog < 0.60 ? 3 : 0);
            const halfW = Math.round(cliffTopHalfW + (cliffBaseHalfW - cliffTopHalfW) * Math.pow(prog, 0.72) + ledgeStep);
            const leftX = wfX - halfW;
            const totalW = halfW * 2;
            sRect(leftX, y, totalW, 1, rockDark);
            const litW = Math.max(2, Math.floor(totalW * 0.34));
            sRect(leftX + 1, y, litW, 1, rockMid);
            if (y % 5 === 0) {
                sRect(leftX + 2, y, Math.max(2, Math.floor(litW * 0.7)), 1, rockHi);
            }
            if (y % 9 === 0 && totalW > 14) {
                sRect(leftX + 4, y, totalW - 8, 1, rockDark);
            }
            // Merkezdeki ıslak koyu şelale oluğu (arka falez oyuğu)
            const gorgeHalf = prog < 0.45 ? 4 : 6;
            sRect(wfX - gorgeHalf, y, gorgeHalf * 2, 1, rockWet);
        }

        // Üst kaynak yarığı + kayanın zirvesinden sarkan gür yosun yastıkları
        sRect(wfX - 4, cliffTopY + 1, 8, 4, '#020617');
        for (let dx = -cliffTopHalfW - 1; dx <= cliffTopHalfW + 1; dx++) {
            const x = wfX + dx;
            const droop = 2 + Math.abs(Math.round(Math.sin(dx * 0.45) * 3));
            const crownOff = Math.round((dx * dx) / Math.max(1, cliffTopHalfW * cliffTopHalfW) * 3);
            const topEdge = cliffTopY - 2 + crownOff;
            sRect(x, topEdge, 1, droop, mossDeep);
            sRect(x, topEdge, 1, 2, mossMid);
            if (Math.abs(dx) < cliffTopHalfW - 2) sRect(x, topEdge, 1, 1, mossBright);
        }

        // Orta kademedeki ıslak çıkıntı kaya rafı & yosunlu basamak (şelaleyi doğal olarak iki kola ayırır)
        sRect(wfX - 10, midShelfY, 21, 5, rockDark);
        sRect(wfX - 9, midShelfY - 1, 18, 3, rockMid);
        sRect(wfX - 8, midShelfY - 1, 12, 1, rockHi);
        sRect(wfX - 10, midShelfY - 2, 7, 2, mossMid);
        sRect(wfX + 4, midShelfY - 2, 7, 2, mossMid);
        sRect(wfX - 9, midShelfY - 2, 4, 1, mossBright);

        // Turkuaz orman lagünü havzası (zemine gömülü kaya kenarlı gölet)
        const lagoonTop = isLightMode ? '#0e7490' : '#083344';
        const lagoonMid = isLightMode ? '#0f766e' : '#064e3b';
        const lagoonDeep = isLightMode ? '#064e3b' : '#022c22';
        for (let y = poolSurfY; y < ph; y++) {
            const t = (y - poolSurfY) / Math.max(1, ph - poolSurfY);
            const edgeTrim = Math.round(t * 2);
            const span = Math.max(6, poolHalfW - edgeTrim);
            const col = t < 0.45 ? lerpHex(lagoonTop, lagoonMid, t * 2) : lerpHex(lagoonMid, lagoonDeep, (t - 0.45) * 2);
            sRect(wfX - span, y, span * 2, 1, col);
        }
        sRect(wfX - poolHalfW + 3, poolSurfY, (poolHalfW - 3) * 2, 2, 'rgba(2, 16, 24, 0.35)');
        sRect(wfX - poolHalfW + 1, poolSurfY - 1, 4, 3, mossDeep);
        sRect(wfX + poolHalfW - 5, poolSurfY - 1, 4, 3, mossDeep);

        const edgeGiants = [
            { x: 0, width: 20, side: 1 },
            { x: pw - 22, width: 22, side: -1 }
        ];
        edgeGiants.forEach((giant) => {
            const trunkDark = isLightMode ? '#2b1812' : '#111014';
            const trunkMid = isLightMode ? '#4a2c20' : '#211b21';
            const trunkHi = isLightMode ? '#6d4330' : '#352b31';
            const mossCol = isLightMode ? '#15803d' : '#0d593d';

            for (let y = 0; y < ph; y++) {
                const prog = y / ph;
                const rootFlare = prog > 0.68 ? Math.pow((prog - 0.68) / 0.32, 2) * 26 : 0;
                const w = Math.round(giant.width + prog * 6 + rootFlare);
                const left = giant.side === 1 ? 0 : pw - w;
                sRect(left, y, w, 1, trunkDark);
                sRect(left + (giant.side === 1 ? w - 6 : 2), y, 4, 1, trunkMid);
                sRect(left + (giant.side === 1 ? w - 2 : 0), y, 2, 1, trunkHi);

                if (y % 16 === 0 && y > 24 && y < ph - 20) {
                    const mx = giant.side === 1 ? w - 4 : pw - w;
                    sRect(mx, y, 4, 2, mossCol);
                }
                if (y % 37 === 0 && y > 40 && y < ph - 28) {
                    const fx = giant.side === 1 ? w - 1 : pw - w - 2;
                    sRect(fx, y, 3, 1, '#d97706');
                }
            }

            // Kenar dev ağaçlardan üst kubbelere uzanan ana taşıyıcı dallar
            const topBoughReach = Math.round(pw * 0.52);
            for (let s = 0; s <= topBoughReach; s++) {
                const t = s / Math.max(1, topBoughReach);
                const bx = giant.side === 1 ? s : (pw - 1 - s);
                const by = Math.round(4 + Math.sin(t * Math.PI * 0.85) * 8 + Math.cos(s * 0.06) * 1.5);
                const thick = Math.max(3, Math.round(9 * (1 - t * 0.65)));
                sRect(bx, by, 1, thick, trunkDark);
                sRect(bx, by, 1, 1, mossCol);
                sRect(bx, by + thick - 1, 1, 1, trunkHi);
            }
        });

        const canopyDomes = [
            { cx: pw * 0.05, cy: 10, rx: 52, ry: 22, s: 1 },
            { cx: pw * 0.16, cy: 8,  rx: 48, ry: 20, s: 2 },
            { cx: pw * 0.28, cy: 6,  rx: 46, ry: 18, s: 3 },
            { cx: pw * 0.40, cy: 9,  rx: 46, ry: 19, s: 2 },
            { cx: pw * 0.50, cy: 6,  rx: 48, ry: 19, s: 3 },
            { cx: pw * 0.60, cy: 9,  rx: 46, ry: 19, s: 2 },
            { cx: pw * 0.72, cy: 6,  rx: 46, ry: 18, s: 3 },
            { cx: pw * 0.84, cy: 8,  rx: 48, ry: 20, s: 2 },
            { cx: pw * 0.95, cy: 10, rx: 52, ry: 22, s: 1 }
        ];
        canopyDomes.forEach(d => drawFoliageDome(Math.round(d.cx), d.cy, d.rx, d.ry, d.s));

        // Yaprak dokusu parıltıları yalnızca kubbelerin kendi sınırları içinde çizilir (gökyüzüne taşmaz!)
        canopyDomes.forEach((d, dIdx) => {
            for (let k = -2; k <= 2; k++) {
                const hx = Math.round(d.cx + k * (d.rx * 0.28));
                const hy = Math.max(1, Math.round(d.cy + ((Math.abs(k) + dIdx) % 3) * 3 - 2));
                const shade = (k + dIdx) % 2 === 0 ? canopyShades[4] : canopyShades[1];
                sRect(hx, hy, 3, 2, shade);
            }
        });

        const floorDeep = isLightMode ? '#0b3b2b' : '#041713';
        const floorLoam = isLightMode ? '#291d16' : '#081110';
        const floorMoss = isLightMode ? '#15803d' : '#0c4a37';
        const floorHi = isLightMode ? '#22c55e' : '#10b981';

        for (let x = 0; x < pw; x++) {
            // Lagün havzası zemini açık tutulur; falez havuzu tam olarak suya iner
            if (Math.abs(x - wfX) < poolHalfW - 2) continue;
            const gy = getGroundY(x, 'rainforest', pw, ph);
            sRect(x, gy, 1, ph - gy, floorDeep);
            sRect(x, gy + 3, 1, Math.max(1, ph - gy - 3), floorLoam);
            sRect(x, gy, 1, 2, floorMoss);
            if (x % 4 === 0) {
                sRect(x, gy - 1, 1, 1, floorHi);
            }
        }

        // Havuz kıyısındaki ıslak yosunlu nehir kayaları (sol kurbağa taşı & sağ kıyıda kaya)
        const frogRockX = wfX - poolHalfW - 3;
        const frogRockY = getGroundY(frogRockX, 'rainforest', pw, ph);
        sRect(frogRockX - 6, frogRockY - 3, 12, 5, rockDark);
        sRect(frogRockX - 5, frogRockY - 4, 10, 3, rockMid);
        sRect(frogRockX - 4, frogRockY - 4, 8, 1, mossMid);
        sRect(frogRockX - 3, frogRockY - 5, 5, 1, mossBright);

        const rightRockX = wfX + poolHalfW - 1;
        const rightRockY = getGroundY(rightRockX, 'rainforest', pw, ph);
        sRect(rightRockX - 4, rightRockY - 3, 9, 5, rockDark);
        sRect(rightRockX - 3, rightRockY - 4, 7, 3, rockMid);
        sRect(rightRockX - 2, rightRockY - 4, 5, 1, mossMid);

        // Sol kıyıda devrilmiş yosunlu kütük & mantar detayları
        const logX = Math.round(pw * 0.21);
        const logY = getGroundY(logX, 'rainforest', pw, ph);
        sRect(logX - 10, logY - 3, 18, 4, isLightMode ? '#3e2723' : '#1a1412');
        sRect(logX - 9, logY - 3, 16, 1, isLightMode ? '#5d4037' : '#2d221e');
        sRect(logX - 6, logY - 4, 10, 1, mossMid);
        sRect(logX - 2, logY - 5, 2, 1, '#facc15');
        sRect(logX + 2, logY - 5, 2, 1, '#fb923c');

        // Payanda kökleri orman zemininin üzerinde oturur
        midgroundTrees.filter(tree => tree.depth !== 'far').forEach(tree => {
            const groundY = getGroundY(tree.x, 'rainforest', pw, ph);
            const rootCol = isLightMode ? '#2c201b' : '#0e1b19';
            const rootHi = isLightMode ? '#523a2e' : '#1f3630';
            [-1, 1].forEach(dir => {
                for (let step = 0; step <= 16; step++) {
                    const t = step / 16;
                    const x = tree.x + dir * step;
                    const topY = groundY - Math.round((1 - t) * 9);
                    const botY = groundY + Math.round(t * 4) + 2;
                    sRect(x, topY, 2, Math.max(2, botY - topY), rootCol);
                    sRect(x, topY, 1, 1, step < 6 ? floorMoss : rootHi);
                }
            });
        });
        // BÖLÜM SONU: YAĞMUR ORMANI STATİK ÇEVRESİ
    }
    
    
    return off;
}

// ============================================================================
// BÖLÜM SONU: STATİK HABİTAT KATMANLARI
// ============================================================================


// ============================================================================
// MODULE: js/habitat-flora-renderer.js
// ============================================================================



function createOffscreenSprite(w, h) {
    try {
        const off = document.createElement('canvas');
        off.width = Math.max(1, Math.ceil(w));
        off.height = Math.max(1, Math.ceil(h));
        const sctx = off.getContext('2d');
        return sctx ? { off, sctx } : null;
    } catch {
        return null;
    }
}

/* HABITAT FLORA RENDERER — animated drawing for habitat plants and small scenery details. */

// ============================================================================
// BÖLÜM BAŞI: FLORA VE BİTKİ KÜMELERİNİN HAREKETLİ ÇİZİMİ
// Bitki verileri initHabitat tarafından hazırlanır; bu modül yalnızca her karede çizer.
// ============================================================================

function drawHabitatFlora(time, hab) {
    flora.forEach(f => {
        const baseGroundY = f.baseY !== undefined ? f.baseY : getGroundY(f.x, hab.sceneProfile, pw, ph);

        if (f.type === 'pebble') {
            // BÖLÜM BAŞI: ZEMİN VE KUTUP DETAYLARI
            pRect(f.x, f.y, f.w, f.h, isLightMode ? 'rgba(15, 55, 65, 0.35)' : f.shade);

} else if (f.type === 'cotton_grass') {
            const sway = Math.sin(time * 0.0016 + f.phase) * 1.6;
            const culmCol = isLightMode ? '#115e59' : '#0f766e';
            const bractCol = '#78350f';
            pRect(f.x - 2, baseGroundY - 1, 5, 2, '#134e4a');
            [-1, 1, 0].forEach((offset, idx) => {
                const ch = Math.max(6, Math.round(f.h * (offset === 0 ? 1 : 0.78)));
                const tipX = Math.round(f.x + offset * 2 + sway * (offset === 0 ? 1 : 0.75));
                const tipY = baseGroundY - ch;
                for (let y = 0; y < ch; y++) {
                    const prog = y / ch;
                    const sx = f.x + offset + (tipX - (f.x + offset)) * prog;
                    pRect(sx, baseGroundY - y, 1, 1, culmCol);
                }
                pRect(tipX - 1, tipY, 3, 1, bractCol);
                pRect(tipX - 2, tipY - 2, 5, 2, '#f8fafc');
                pRect(tipX - 1, tipY - 3, 3, 3, '#ffffff');
                if (idx === 2) pRect(tipX, tipY - 4, 1, 1, '#e0f2fe');
            });

        } else if (f.type === 'arctic_crystal') {
            const rockDark = isLightMode ? '#334155' : '#0f172a';
            const rockMid = isLightMode ? '#475569' : '#1e293b';
            const rockHi = isLightMode ? '#64748b' : '#334155';
            const lichenCol = f.col === '#38bdf8' ? '#f97316' : '#84cc16';

            pRect(f.x - 4, baseGroundY, 9, 2, 'rgba(7, 13, 25, 0.38)');
            pRect(f.x - 4, baseGroundY - 3, 8, 3, rockDark);
            pRect(f.x - 3, baseGroundY - 5, 6, 3, rockMid);
            pRect(f.x - 2, baseGroundY - 6, 4, 2, rockHi);
            pRect(f.x - 2, baseGroundY - 6, 3, 1, '#f8fafc');
            pRect(f.x - 1, baseGroundY - 4, 2, 1, lichenCol);
            pRect(f.x + 1, baseGroundY - 3, 2, 1, lichenCol);

            const twigH = Math.max(5, Math.round(f.h * 0.65));
            for (let y = 0; y < twigH; y++) {
                const bx = f.x + 2 + Math.round((y / twigH) * 2);
                const by = baseGroundY - 2 - y;
                pRect(bx, by, 1, 1, '#451a03');
                if (y % 2 === 1) {
                    pRect(bx + 1, by, 1, 1, '#bae6fd');
                }
            }

        } else if (f.type === 'arctic_berry_bush') {
            const sway = Math.sin(time * 0.0014 + f.phase) * 0.6;
            const leafDark = isLightMode ? '#134e4a' : '#062e2b';
            const leafMid = isLightMode ? '#0f766e' : '#115e59';
            pRect(f.x - f.r, baseGroundY, f.r * 2, 2, 'rgba(7, 13, 25, 0.35)');
            pRect(f.x - 1, baseGroundY - 2, 3, 2, '#451a03');
            for (let dy = -4; dy <= -1; dy++) {
                const span = Math.max(2, f.r - Math.abs(dy + 2));
                pRect(f.x - span + sway, baseGroundY + dy, span * 2, 1, dy < -2 ? leafMid : leafDark);
            }
            pRect(f.x - f.r + 2 + sway, baseGroundY - 5, Math.max(2, f.r * 2 - 4), 1, '#e0f2fe');
            pRect(f.x - 2 + sway, baseGroundY - 3, 2, 2, '#f97316');
            pRect(f.x - 2 + sway, baseGroundY - 3, 1, 1, '#fde047');
            pRect(f.x + 1 + sway, baseGroundY - 2, 2, 2, '#ef4444');

            // BÖLÜM SONU: ZEMİN VE KUTUP DETAYLARI
        } else if (f.type === 'maple_bough') {
            // BÖLÜM BAŞI: AĞAÇ, SARMAŞIK VE ORMAN FLORASI
            for (let y = 0; y < f.len; y += 2) {
                const prog = y / f.len;
                const sway = Math.sin(time * 0.0015 + f.phase + y * 0.07) * (1.0 + prog * 3.0);
                const px = Math.round(f.x + sway);
                const py = f.branchY + y;
                pRect(px, py, 1, 2, '#3b1806');
                if (y > 2 && y % 4 === 0) {
                    const span = Math.max(1, Math.round((1 - prog * 0.45) * 3));
                    pRect(px - span, py, span * 2 + 1, 1, f.col);
                    pRect(px - span + 1, py - 1, Math.max(1, span * 2 - 1), 3, f.col);
                    pRect(px, py - 1, 1, 1, '#fde047');
                    pRect(px - 1, py, 1, 1, '#fca5a5');
                }
            }

        } else if (f.type === 'bamboo_stalk') {
            const culmDark = isLightMode ? '#14532d' : '#063726';
            const culmCol = isLightMode ? '#15803d' : '#0d593d';
            const nodeCol = isLightMode ? '#86efac' : '#34d399';
            const leafCol = isLightMode ? '#22c55e' : '#10b981';

            pRect(f.x - 1, baseGroundY - 1, 4, 2, culmDark);
            for (let y = 0; y < f.h; y += 2) {
                const prog = y / f.h;
                const sway = Math.sin(time * 0.0012 + f.phase) * prog * 3.2 + f.lean * y;
                const px = Math.round(f.x + sway);
                const py = baseGroundY - y;
                pRect(px, py, 2, 2, culmCol);
                pRect(px + 1, py, 1, 2, culmDark);
                if (y > 6 && y % 12 === 0) {
                    pRect(px - 1, py, 4, 1, nodeCol);
                    const side = (y % 24 === 0) ? -1 : 1;
                    const leafStartX = side > 0 ? px + 2 : px - 1;
                    pRect(leafStartX, py - 1, 4 * side, 1, leafCol);
                    pRect(leafStartX + side, py - 2, 4 * side, 1, nodeCol);
                    pRect(leafStartX + side * 2, py, 3 * side, 1, culmCol);
                }
            }

        } else if (f.type === 'sea_vine') {
            for (let y = 0; y < f.len; y += 2) {
                const prog = y / f.len;
                const sway = Math.sin(time * 0.0014 + f.phase + y * 0.06) * (1.0 + prog * 3.5);
                const px = f.x + sway;
                const py = f.startY + y;
                pRect(px, py, 1, 2, '#0f766e');
                if (y % 6 === 0) {
                    pRect(px - 1, py, 3, 1, f.col);
                }
            }

        } else if (f.type === 'staghorn_coral') {
            if (!f._cols) {
                f._cols = {
                    base: `hsla(${f.hue}, 70%, 28%, 0.95)`,
                    main: `hsla(${f.hue}, 85%, 52%, 0.92)`,
                    hi: `hsla(${f.hue}, 95%, 68%, 0.95)`,
                };
            }
            const baseCol = f._cols.base;
            const mainCol = f._cols.main;
            const hiCol = f._cols.hi;
            const tipCol = '#fef08a';

            pRect(f.x - 3, baseGroundY - 1, 7, 3, baseCol);
            pRect(f.x - 2, baseGroundY - 2, 5, 2, mainCol);

            for (let b = -1; b <= 1; b++) {
                const bh = Math.round(f.h * (b === 0 ? 1 : 0.78));
                for (let y = 0; y < bh; y++) {
                    const prog = y / bh;
                    const sway = Math.sin(time * 0.001 + f.phase) * prog * 0.8;
                    const px = Math.round(f.x + b * Math.pow(prog, 1.15) * 6.5 + sway);
                    const py = baseGroundY - y;
                    const col = y >= bh - 2 ? tipCol : (y < 4 ? baseCol : (y % 2 === 0 ? hiCol : mainCol));
                    pRect(px, py, 2, 1, col);

                    if (b !== 0 && y >= Math.floor(bh * 0.50) && y <= Math.floor(bh * 0.50) + 4) {
                        const subStep = y - Math.floor(bh * 0.50);
                        const sx = px + b * (1 + Math.floor(subStep * 0.6));
                        const sy = py - subStep;
                        pRect(sx, sy, 2, 1, subStep >= 3 ? tipCol : hiCol);
                    }
                }
            }
            
        } else if (f.type === 'willow_frond') {
            const stemCol = isLightMode ? '#15803d' : '#0b4635';
            const leafCol = isLightMode ? '#22c55e' : '#10b981';
            const tipCol = isLightMode ? '#86efac' : '#34d399';
            pRect(f.x - 1, f.startY - 1, 3, 2, '#3b281e');
            for (let y = 0; y < f.len; y += 2) {
                const prog = y / f.len;
                const sway = Math.sin(time * 0.0014 + f.phase + y * 0.05) * (1.2 + prog * 4.5);
                const px = Math.round(f.x + sway);
                const py = f.startY + y;
                pRect(px, py, 1, 2, stemCol);
                if (y > 3 && y % 4 === 0) {
                    const side = (y % 8 === 0) ? -1 : 1;
                    pRect(px + side, py, 2, 1, prog > 0.72 ? tipCol : leafCol);
                    pRect(px + side * 2, py + 1, 1, 1, prog > 0.60 ? tipCol : leafCol);
                }
            }

       } else if (f.type === 'canopy_vine') {
            for (let y = 0; y < f.len; y += 2) {
                const progress = y / f.len;
                const sway = Math.sin(time * 0.0011 + f.phase + y * 0.035) * (1.0 + progress * 3.2);
                const px = Math.round(f.x + sway);
                const py = f.startY + y;
                pRect(px, py, 1, 2, f.hue);
                if (y > 6 && y % 8 === 0) {
                    const side = (y % 16 === 0) ? 1 : -1;
                    pRect(px + side, py, 2 * side, 2, '#22c55e');
                    pRect(px + side * 2, py + 1, 1, 1, '#15803d');
                }
            }

        } else if (f.type === 'tropical_leaf') {
            const stem = isLightMode ? '#166534' : '#0b4636';
            const sway = Math.sin(time * 0.0013 + f.phase) * 1.8;
            for (let blade = -1; blade <= 1; blade++) {
                const length = Math.round(f.h * (blade === 0 ? 1 : 0.76));
                const spread = blade * 7 + f.dir * 2;
                for (let step = 0; step < length; step++) {
                    const t = step / length;
                    const cx = Math.round(f.x + (spread + sway) * Math.pow(t, 1.15));
                    const cy = baseGroundY - step;
                    const halfW = Math.max(1, Math.round(Math.sin(t * Math.PI) * 3.5));
                    pRect(cx - halfW, cy, halfW * 2 + 1, 1, step % 4 === 0 ? f.hue : (isLightMode ? '#15803d' : '#0c6246'));
                    pRect(cx, cy, 1, 1, isLightMode ? '#4ade80' : '#2dd4a0');
                }
            }
            pRect(f.x - 1, baseGroundY - 3, 3, 4, stem);

        } else if (f.type === 'monstera') {
            const sway = Math.sin(time * 0.0012 + f.phase) * 1.3;
            const stemCol = isLightMode ? '#0f5e35' : '#073d2b';
            const leafDark = isLightMode ? '#15803d' : '#0b5838';
            const leafLight = isLightMode ? '#22a65a' : '#1b8250';
            for (let blade = -2; blade <= 2; blade++) {
                const length = f.h * (blade === 0 ? 1 : (Math.abs(blade) === 1 ? 0.82 : 0.66));
                const lateralReach = blade * 8.5 * f.dir;
                for (let step = 0; step < length; step += 2) {
                    const progress = step / length;
                    const centerX = f.x + lateralReach * Math.pow(progress, 1.15) + sway * progress;
                    const py = baseGroundY - step;
                    const halfW = Math.max(1, Math.round(Math.sin(progress * Math.PI) * 5.5));
                    const leafCol = (blade + Math.floor(step / 12)) % 2 === 0 ? leafLight : leafDark;
                    pRect(centerX - halfW, py, halfW * 2 + 1, 2, leafCol);
                    pRect(centerX, py, 1, 2, stemCol);

                    if (step > 8 && step < length - 8 && step % 12 === 0 && halfW >= 3) {
                        const cut = Math.max(1, Math.floor(halfW * 0.48));
                        const shadow = isLightMode ? '#0b3b2b' : '#041713';
                        pRect(centerX - cut, py, 1, 2, shadow);
                        pRect(centerX + cut, py, 1, 2, shadow);
                    }
                    if (step % 10 === 0 && halfW > 2) {
                        pRect(centerX - Math.sign(lateralReach || f.dir) * (halfW - 1), py - 1, 1, 2, isLightMode ? '#4ade80' : '#2bb46f');
                    }
                }
            }
            pRect(f.x - 3, baseGroundY - 5, 7, 5, stemCol);
            pRect(f.x - 1, baseGroundY - 7, 3, 2, leafLight);

        } else if (f.type === 'jungle_fern') {
            const stemCol = isLightMode ? '#14532d' : '#093829';
            const leafletLight = isLightMode ? '#22c55e' : '#148f5a';
            const leafletDark = isLightMode ? '#15803d' : '#0d6340';
            pRect(f.x - 2, baseGroundY - 1, 5, 2, stemCol);
            for (let frond = -2; frond <= 2; frond++) {
                const direction = frond === 0 ? (f.dir || 1) : Math.sign(frond);
                const length = Math.round(f.h * (0.65 + (2 - Math.abs(frond)) * 0.16));
                const spread = frond === 0 ? direction * 3 : frond * 5.5;
                for (let step = 0; step < length; step++) {
                    const t = step / length;
                    const sway = Math.sin(time * 0.0014 + f.phase + frond) * t * 1.4;
                    const px = Math.round(f.x + spread * Math.pow(t, 1.35) + sway);
                    const py = baseGroundY - step + Math.round(Math.pow(t, 2.2) * 3);
                    pRect(px, py, 1, 1, stemCol);
                    if (step > 2 && step % 2 === 0) {
                        const pinna = Math.max(1, Math.round(Math.sin(t * Math.PI) * 3.2));
                        pRect(px - pinna, py, pinna * 2 + 1, 1, Math.abs(frond) % 2 === 0 ? leafletLight : leafletDark);
                    }
                }
            }

        } else if (f.type === 'heliconia') {
            const sway = Math.sin(time * 0.0015 + f.phase) * 1.8;
            const stemCol = isLightMode ? '#166534' : '#0d4a36';
            const leafCol = isLightMode ? '#15803d' : '#116345';
            const dir = f.dir || 1;

            // Geniş kavisli taban yaprakları
            [-1, 1].forEach(side => {
                const lh = Math.round(f.h * 0.72);
                for (let s = 0; s < lh; s++) {
                    const t = s / lh;
                    const lx = Math.round(f.x + side * Math.pow(t, 1.2) * 6 + sway * t * 0.6);
                    const ly = baseGroundY - s;
                    const lw = Math.max(1, Math.round(Math.sin(t * Math.PI) * 2.4));
                    pRect(lx - lw, ly, lw * 2 + 1, 1, leafCol);
                }
            });

            // Kavisli ana sap ve uçtan sarkan Heliconia (ıstakoz kıskacı) çiçek salkımı
            let topX = f.x;
            const topY = Math.round(baseGroundY - f.h);
            for (let y = 0; y < f.h; y++) {
                const prog = y / f.h;
                topX = Math.round(f.x + dir * Math.pow(prog, 1.4) * 4 + sway * prog);
                pRect(topX, baseGroundY - y, 1, 1, stemCol);
            }
            for (let b = 0; b < 4; b++) {
                const bx = topX + dir * (2 + (b % 2));
                const by = topY + 2 + b * 3;
                pRect(topX + dir, by - 1, 2, 2, stemCol);
                pRect(bx, by, 3 * dir, 2, f.hue);
                pRect(bx + dir * 2, by, 1, 1, '#facc15');
            }

        } else if (f.type === 'epiphyte') {
            const x = f.x;
            const y = f.y;
            const sway = Math.sin(time * 0.0015 + f.phase) * 0.6;
            const leafDark = isLightMode ? '#14532d' : '#063726';
            const leafMid = isLightMode ? '#16a34a' : '#0f6b48';

            // Dal çatalını kavrayan ince kavisli epifit yaprakları
            [-2, -1, 0, 1, 2].forEach(blade => {
                for (let s = 0; s < 5; s++) {
                    const lx = Math.round(x + blade * (1 + s * 0.45) + sway * (s / 5));
                    const ly = y - s + Math.floor(Math.abs(blade) * 0.5);
                    pRect(lx, ly, 1, 1, s < 2 ? leafDark : leafMid);
                }
            });
            // Merkezden yükselen zarif çiçek başağı
            const flX = Math.round(x + sway);
            pRect(flX - 1, y - 4, 3, 2, f.hue);
            pRect(flX, y - 6, 1, 2, f.hue);
            pRect(flX, y - 6, 1, 1, '#fef08a');

        } else if (f.type === 'bromeliad') {
            const centerX = f.x;
            const leafDark = isLightMode ? '#14532d' : '#093829';
            const leafMid = isLightMode ? '#15803d' : '#0f5e42';
            const leafHi = isLightMode ? '#22c55e' : '#168058';

            for (let blade = -3; blade <= 3; blade++) {
                const bh = Math.round(f.h * (0.58 + (3 - Math.abs(blade)) * 0.12));
                const dir = blade === 0 ? 1 : Math.sign(blade);
                for (let y = 0; y < bh; y++) {
                    const prog = y / bh;
                    const arch = blade * 2.8 * Math.pow(prog, 1.25);
                    const droop = prog > 0.72 ? Math.round((prog - 0.72) * 6) : 0;
                    const px = Math.round(centerX + arch);
                    const py = baseGroundY - y + droop;
                    const col = Math.abs(blade) % 2 === 0 ? (prog > 0.6 ? leafHi : leafMid) : leafDark;
                    pRect(px - 1, py, 2, 1, col);
                    if (prog < 0.25) pRect(px + dir, py, 1, 1, leafDark);
                }
            }
            const bractY = Math.round(baseGroundY - f.h * 0.55);
            for (let by = 0; by < 6; by++) {
                const bw = by < 2 ? 1 : (by < 5 ? 2 : 1);
                pRect(centerX - bw, bractY - by, bw * 2 + 1, 1, f.hue);
            }
            pRect(centerX, bractY - 6, 1, 2, '#facc15');

        } else if (f.type === 'orchid') {
            const stemCol = isLightMode ? '#166534' : '#115e59';
            const leafCol = isLightMode ? '#15803d' : '#0d4a36';
            pRect(f.x - 3, baseGroundY - 2, 3, 2, leafCol);
            pRect(f.x + 1, baseGroundY - 2, 3, 2, leafCol);
            let topX = f.x;
            for (let y = 0; y < f.h; y++) {
                const prog = y / f.h;
                const sway = Math.sin(time * 0.0016 + f.phase + y * 0.06) * prog * 2.2 + Math.pow(prog, 1.4) * 3;
                topX = Math.round(f.x + sway);
                pRect(topX, baseGroundY - y, 1, 1, stemCol);
            }
            const flowerY = Math.round(baseGroundY - f.h);
            pRect(topX - 2, flowerY - 1, 5, 3, f.hue);
            pRect(topX - 1, flowerY - 2, 3, 4, '#fbcfe8');
            pRect(topX, flowerY, 1, 2, '#be185d');
            pRect(topX, flowerY - 1, 1, 1, '#fef08a');

            // BÖLÜM SONU: AĞAÇ, SARMAŞIK VE ORMAN FLORASI

        } else if (f.type === 'meadow_stone') {
            // BÖLÜM BAŞI: ÇAYIR VE ÇİÇEKLİ BİTKİLER
            const stoneDark = isLightMode ? '#475569' : '#1e293b';
            const stoneMid = isLightMode ? '#64748b' : '#334155';
            const stoneHi = isLightMode ? '#94a3b8' : '#475569';
            pRect(f.x - f.rx, baseGroundY, f.rx * 2, 2, 'rgba(2, 10, 14, 0.38)');
            for (let dy = -f.ry; dy <= 0; dy++) {
                const span = Math.max(1, Math.round(f.rx * Math.sqrt(Math.max(0, 1 - (dy * dy) / ((f.ry + 1) * (f.ry + 1))))));
                pRect(f.x - span, baseGroundY + dy, span * 2, 1, dy === 0 ? stoneDark : stoneMid);
                if (dy === -f.ry) {
                    pRect(f.x - span + 1, baseGroundY + dy, Math.max(1, span * 2 - 2), 1, stoneHi);
                    if (f.hasMoss) {
                        pRect(f.x - Math.floor(span * 0.6), baseGroundY + dy, Math.max(2, Math.floor(span * 1.1)), 1, isLightMode ? '#16a34a' : '#15803d');
                    }
                }
            }

        } else if (f.type === 'meadow_tuft') {
            const bladeDark = isLightMode ? '#15803d' : '#0d3b2e';
            const bladeLight = isLightMode ? '#22c55e' : '#155e46';
            const sway = Math.sin(time * 0.0017 + f.phase) * 1.2;
            [-2, -1, 0, 1, 2].forEach((b, bIdx) => {
                const bh = Math.max(3, f.h - Math.abs(b));
                for (let y = 0; y < bh; y++) {
                    const prog = y / bh;
                    const bx = f.x + b + (b * 0.6 + sway) * prog;
                    pRect(bx, baseGroundY - y, 1, 1, bIdx % 2 === 0 ? bladeLight : bladeDark);
                }
            });
            if (f.hasClover) {
                const cx = Math.round(f.x + sway * 0.6);
                const cy = baseGroundY - Math.max(2, Math.floor(f.h * 0.55));
                pRect(cx - 1, cy, 3, 1, '#16a34a');
                pRect(cx - 1, cy - 1, 3, 1, f.cloverCol);
                pRect(cx, cy - 2, 1, 1, '#ffffff');
            }

        } else if (f.type === 'sunflower') {
            const stemShade = isLightMode ? '#15803d' : '#14532d';
            const stemHi = isLightMode ? '#22c55e' : '#1b5e3a';
            const leafCol = isLightMode ? '#16a34a' : '#15803d';
            const leafHi = isLightMode ? '#4ade80' : '#22c55e';
            let topX = f.x;
            const topY = baseGroundY - Math.floor(f.h);

            pRect(f.x - 2, baseGroundY - 1, 5, 2, stemShade);
            pRect(f.x - 3, baseGroundY - 2, 2, 1, leafCol);
            pRect(f.x + 2, baseGroundY - 2, 2, 1, leafCol);

            for (let y = 0; y < f.h; y++) {
                const sway = Math.sin(time * 0.0016 + f.phase + y * 0.05) * (y / f.h) * 3.0;
                const px = f.x + sway;
                const py = baseGroundY - y;
                if (y === Math.floor(f.h) - 1) topX = px;
                pRect(px, py, 2, 1, stemShade);
                pRect(px, py, 1, 1, stemHi);

                if (y === Math.floor(f.h * 0.32) || y === Math.floor(f.h * 0.54) || y === Math.floor(f.h * 0.74)) {
                    const side = (y === Math.floor(f.h * 0.54)) ? -1 : 1;
                    const petioleX = px + (side > 0 ? 2 : -1);
                    pRect(petioleX, py, 1, 1, stemShade);
                    pRect(petioleX + side, py - 1, 3, 2, leafCol);
                    pRect(petioleX + side * 2, py, 3, 2, leafCol);
                    pRect(petioleX + side, py - 1, 2, 1, leafHi);
                }
            }
            const hr = f.headR || 4;
            pRect(topX - 2, topY + 1, 5, 2, stemShade);
            for (let dy = -hr - 1; dy <= hr + 1; dy++) {
                for (let dx = -hr - 1; dx <= hr + 1; dx++) {
                    const d2 = dx * dx + dy * dy;
                    if (d2 <= 3) {
                        pRect(topX + dx, topY + dy, 1, 1, (dx + dy) % 2 === 0 ? '#451a03' : '#78350f');
                    } else if (d2 <= 6) {
                        pRect(topX + dx, topY + dy, 1, 1, '#92400e');
                    } else if (d2 <= hr * hr + 2) {
                        const isOuterTip = d2 > (hr - 1) * (hr - 1);
                        const petalCol = isOuterTip ? '#fde047' : ((dx + dy) % 2 === 0 ? '#facc15' : '#f59e0b');
                        pRect(topX + dx, topY + dy, 1, 1, petalCol);
                    }
                }
            }
            f.tipX = topX;
            f.tipY = topY;

        } else if (f.type === 'foxglove' || f.type === 'loosestrife') {
            const stemShade = isLightMode ? '#15803d' : '#115e59';
            const rosetteCol = isLightMode ? '#16a34a' : '#0f5138';
            let topX = f.x;

            pRect(f.x - 3, baseGroundY - 1, 7, 2, stemShade);
            pRect(f.x - 4, baseGroundY - 2, 3, 1, rosetteCol);
            pRect(f.x + 2, baseGroundY - 2, 3, 1, rosetteCol);

            for (let y = 0; y < f.h; y++) {
                const prog = y / f.h;
                const sway = Math.sin(time * 0.0017 + f.phase + y * 0.05) * prog * 2.8;
                const px = f.x + sway;
                const py = baseGroundY - y;
                topX = px;
                pRect(px, py, 1, 1, stemShade);

                if (y === Math.floor(f.h * 0.22) || y === Math.floor(f.h * 0.34)) {
                    const lSide = y % 2 === 0 ? -2 : 1;
                    pRect(px + lSide, py, 2, 1, rosetteCol);
                }

                if (prog > 0.38 && y % 3 === 0) {
                    const side = (y % 6 === 0) ? -1 : 1;
                    pRect(px + side, py, 1, 1, stemShade);
                    if (prog > 0.86) {
                        pRect(px + side, py, 2, 1, f.hue);
                    } else {
                        const bellX = px + (side < 0 ? -3 : 1);
                        pRect(bellX, py, 3, 2, f.hue);
                        pRect(bellX + (side < 0 ? 0 : 2), py + 1, 1, 1, '#fdf4ff');
                    }
                }
            }
            pRect(topX, baseGroundY - f.h - 1, 1, 2, f.hue);
            f.tipX = topX;
            f.tipY = baseGroundY - f.h;

       } else if (f.type === 'buddleia') {
            const woodyCol = isLightMode ? '#451a03' : '#1e1b2e';
            const stemCol = isLightMode ? '#15803d' : '#0d4a3a';
            const leafCol = isLightMode ? '#22c55e' : '#10b981';
            let tipX = f.x;
            let tipY = baseGroundY - f.h;

            pRect(f.x - 3, baseGroundY - 1, 7, 2, stemCol);
            pRect(f.x - 1, baseGroundY - 3, 3, 3, woodyCol);

            for (let y = 0; y < f.h; y++) {
                const prog = y / f.h;
                const sway = Math.sin(time * 0.0016 + f.phase + y * 0.05) * prog * 3.2 + (f.tilt || 0) * y * 0.7;
                const px = Math.round(f.x + sway);
                const py = baseGroundY - y;
                tipX = px;
                tipY = py;
                pRect(px, py, 1, 1, y < 5 ? woodyCol : stemCol);

                if (y === Math.floor(f.h * 0.26) || y === Math.floor(f.h * 0.44)) {
                    pRect(px - 3, py, 7, 1, stemCol);
                    pRect(px - 2, py - 1, 2, 1, leafCol);
                    pRect(px + 1, py - 1, 2, 1, leafCol);
                }
                if (prog > 0.52 && y % 2 === 0) {
                    const coneW = Math.max(1, Math.round((1 - prog) * 5.5));
                    pRect(px - coneW, py, coneW * 2 + 1, 2, f.hue);
                    if (coneW >= 2) pRect(px - coneW + 1, py - 1, coneW * 2 - 1, 1, '#fdf4ff');
                    pRect(px, py, 1, 1, '#fef08a');
                }
            }
            pRect(tipX, tipY - 1, 1, 2, f.hue);
            f.tipX = tipX;
            f.tipY = tipY;

        } else if (f.type === 'hydrangea') {
            const sway = Math.sin(time * 0.0012 + f.phase) * 1.2;
            const cx = Math.round(f.x + sway);
            const cy = baseGroundY - f.r - 2;
            const bushDark = isLightMode ? '#14532d' : '#063729';
            const bushMid = isLightMode ? '#15803d' : '#064e3b';
            const bushHi = isLightMode ? '#22c55e' : '#10b981';

            pRect(f.x - f.r - 2, baseGroundY, (f.r + 2) * 2, 2, 'rgba(2, 8, 16, 0.35)');
            for (let by = 0; by < 5; by++) {
                const bw = f.r + 3 - Math.floor(by * 0.5);
                pRect(f.x - bw + sway * 0.4, baseGroundY - by, bw * 2, 1, by < 2 ? bushDark : bushMid);
            }
            [-2, 0, 2].forEach(stemOff => {
                pRect(f.x + stemOff, baseGroundY - 5, 1, 4, '#3b2316');
                pRect(f.x + stemOff * 1.5, baseGroundY - 5, 2, 1, bushHi);
            });

            for (let dy = -f.r; dy <= f.r * 0.65; dy += 2) {
                const span = Math.round(f.r * Math.sqrt(Math.max(0, 1 - (dy * dy) / (f.r * f.r))));
                for (let dx = -span; dx <= span; dx += 2) {
                    const floretCol = (dx + dy) % 4 === 0 ? '#fdf4ff' : f.hue;
                    pRect(cx + dx, cy + dy, 2, 2, floretCol);
                    if ((dx * dy) % 3 === 0) pRect(cx + dx, cy + dy, 1, 1, '#fef9c3');
                }
            }
            f.tipX = cx;
            f.tipY = cy - f.r;

        } else if (f.type === 'meadow') {
            const stemShade = isLightMode ? '#15803d' : '#14332a';
            const leafAccent = isLightMode ? '#22c55e' : '#1b4d3e';
            let topX = f.x;
            const maxH = Math.floor(f.h);

            pRect(f.x - 1, baseGroundY - 1, 3, 2, stemShade);
            pRect(f.x - 2, baseGroundY - 2, 1, 2, leafAccent);
            pRect(f.x + 2, baseGroundY - 2, 1, 2, leafAccent);

            for (let y = 0; y < maxH; y++) {
                const prog = y / Math.max(1, maxH);
                const sway = Math.sin(time * 0.0018 + f.phase + y * 0.07) * prog * 2.8;
                const px = f.x + sway;
                const py = baseGroundY - y;
                topX = px;
                pRect(px, py, 1, 1, stemShade);

                if (y === Math.floor(maxH * 0.42)) {
                    const side = (f.x % 2 === 0) ? -1 : 1;
                    pRect(px + side, py, 2 * side, 1, leafAccent);
                }

                if (f.hasBloom && f.kind === 'lavender' && y > maxH - 9 && y % 2 === 0) {
                    pRect(px - 1, py, 3, 1, y >= maxH - 3 ? '#c084fc' : '#9333ea');
                    if (y === maxH - 1) pRect(px, py - 1, 1, 1, '#e9d5ff');
                }
            }

            const headY = baseGroundY - maxH;
            if (f.hasBloom) {
                if (f.kind === 'daisy') {
                    pRect(topX - 1, headY + 1, 3, 1, stemShade);
                    pRect(topX - 3, headY - 1, 7, 2, '#f8fafc');
                    pRect(topX - 2, headY - 2, 5, 4, '#ffffff');
                    pRect(topX - 1, headY - 1, 3, 2, '#facc15');
                    pRect(topX, headY - 1, 1, 1, '#f59e0b');
                } else if (f.kind === 'poppy') {
                    pRect(topX - 1, headY + 1, 3, 1, stemShade);
                    pRect(topX - 3, headY - 2, 7, 3, '#e11d48');
                    pRect(topX - 2, headY - 3, 5, 3, '#fb7185');
                    pRect(topX - 3, headY - 3, 2, 1, '#fda4af');
                    pRect(topX + 2, headY - 3, 2, 1, '#fda4af');
                    pRect(topX - 1, headY - 1, 3, 2, '#1e1b4b');
                    pRect(topX, headY - 1, 1, 1, '#fef08a');
                } else if (f.kind === 'buttercup') {
                    pRect(topX - 1, headY + 1, 3, 1, stemShade);
                    pRect(topX - 2, headY - 1, 5, 2, '#f59e0b');
                    pRect(topX - 2, headY - 2, 5, 2, '#fde047');
                    pRect(topX - 1, headY - 2, 3, 1, '#fef9c3');
                    pRect(topX, headY - 1, 1, 1, '#d97706');
                } else if (f.kind === 'echinacea') {
                    pRect(topX - 1, headY + 1, 3, 1, stemShade);
                    pRect(topX - 3, headY, 2, 2, '#f472b6');
                    pRect(topX + 2, headY, 2, 2, '#f472b6');
                    pRect(topX - 2, headY - 1, 5, 2, '#ec4899');
                    pRect(topX - 1, headY - 2, 3, 2, '#b45309');
                    pRect(topX, headY - 2, 1, 1, '#f59e0b');
                } else if (f.kind === 'nightbloom') {
                    pRect(topX - 1, headY + 1, 3, 1, stemShade);
                    pRect(topX - 2, headY - 1, 5, 3, '#38bdf8');
                    pRect(topX - 1, headY - 2, 3, 2, '#7dd3fc');
                    pRect(topX, headY - 1, 1, 1, '#e0f2fe');
                }
            }
            f.tipX = topX;
            f.tipY = headY;

            // BÖLÜM SONU: ÇAYIR VE ÇİÇEKLİ BİTKİLER
        } else if (f.type === 'carpet_tuft') {
            // BÖLÜM BAŞI: SULAK ALAN VE AKVARYUM BİTKİLERİ
            const sway = Math.sin(time * 0.0015 + f.phase) * 0.6;
            const darkCol = isLightMode ? '#15803d' : '#064e3b';
            const midCol = isLightMode ? '#16a34a' : '#047857';
            const hiCol = isLightMode ? '#4ade80' : '#10b981';
            pRect(f.x - f.w, baseGroundY - 1, f.w * 2, 2, darkCol);
            pRect(f.x - f.w + 1 + sway, baseGroundY - f.h, f.w * 2 - 2, f.h, midCol);
            pRect(f.x - 1 + sway, baseGroundY - f.h, 2, 1, hiCol);

        } else if (f.type === 'amazon_sword') {
            const crownCol = isLightMode ? '#14532d' : '#064e3b';
            const bladeDark = isLightMode ? '#15803d' : '#047857';
            const bladeLight = isLightMode ? '#22c55e' : '#10b981';
            const veinCol = isLightMode ? '#86efac' : '#34d399';
            pRect(f.x - 2, baseGroundY - 1, 5, 2, crownCol);
            [-2, -1, 0, 1, 2].forEach(b => {
                const bh = f.h * (b === 0 ? 1 : (Math.abs(b) === 1 ? 0.86 : 0.70));
                const spread = b * 3.2;
                for (let y = 0; y < bh; y += 2) {
                    const prog = y / bh;
                    const sway = Math.sin(time * 0.0015 + f.phase + b * 0.5) * prog * 2.5;
                    const cx = f.x + spread * prog + sway;
                    const cy = baseGroundY - y;
                    const halfW = Math.max(1, Math.round(Math.sin(prog * Math.PI) * 2.2));
                    pRect(cx - halfW, cy, halfW * 2 + 1, 2, Math.abs(b) % 2 === 0 ? bladeLight : bladeDark);
                    pRect(cx, cy, 1, 2, veinCol);
                }
            });

        } else if (f.type === 'hornwort') {
            pRect(f.x - 1, baseGroundY - 1, 3, 2, isLightMode ? '#14532d' : '#064e3b');
            for (let y = 0; y < f.h; y++) {
                const sway = Math.sin(time * 0.0018 + f.phase + y * 0.06) * (y / f.h) * 4.5;
                const px = f.x + sway;
                const py = baseGroundY - y;
                if (py < 4) break;
                pRect(px, py, 1, 1, isLightMode ? '#15803d' : '#065f46');
                if (y > 4 && y % 4 === 0) {
                    const span = Math.max(2, Math.round(f.whorlSpan * (1 - (y / f.h) * 0.35)));
                    for (let wx = -span; wx <= span; wx++) {
                        if (wx === 0) continue;
                        const needleY = py - Math.abs(wx) * 0.45;
                        const isTip = Math.abs(wx) === span;
                        const col = (!isLightMode && isTip) ? f.glowCol : (isLightMode ? '#22c55e' : '#047857');
                        pRect(px + wx, needleY, 1, 1, col);
                    }
                }
                if (!isLightMode && y === Math.floor(f.h) - 1) {
                    pRect(px - 1, py - 1, 3, 2, '#6ee7b7');
                }
            }

        } else if (f.type === 'pistia') {
            const drift = Math.sin(time * 0.0012 + f.phase) * 3.5;
            const px = Math.round(f.x + drift);
            pRect(px - 5, 2, 11, 2, isLightMode ? '#16a34a' : '#0f5138');
            pRect(px - 4, 1, 9, 2, isLightMode ? '#22c55e' : '#15803d');
            pRect(px - 2, 1, 5, 1, '#86efac');
            for (let r = 0; r < f.rootLen; r++) {
                const rw = Math.sin(time * 0.002 + r * 0.25 + f.phase) * 1.4;
                const rootAlpha = (0.42 * (1 - r / f.rootLen)).toFixed(2);
                pRect(px + rw, 3 + r, 1, 1, `rgba(167, 243, 208, ${rootAlpha})`);
                if (r < f.rootLen * 0.72) {
                    pRect(px - 2 + rw * 0.8, 3 + r, 1, 1, `rgba(52, 211, 153, ${rootAlpha})`);
                    pRect(px + 2 + rw * 0.8, 3 + r, 1, 1, `rgba(52, 211, 153, ${rootAlpha})`);
                }
            }
            
       } else if (f.type === 'wisteria_cluster') {
            pRect(f.x - 1, f.branchY - 1, 3, 2, '#3b2316');
            pRect(f.x - 3, f.branchY + 1, 7, 1, isLightMode ? '#15803d' : '#0d4a36');
            pRect(f.x - 2, f.branchY + 2, 5, 1, isLightMode ? '#22c55e' : '#10b981');
            for (let y = 0; y < f.len; y++) {
                const prog = y / f.len;
                const sway = Math.sin(time * 0.0015 + f.phase + y * 0.09) * prog * 3.5;
                const px = Math.round(f.x + sway);
                const py = f.branchY + y;
                pRect(px, py, 1, 1, '#14532d');
                if (y > 2 && y % 2 === 0) {
                    const halfW = Math.max(0, Math.round((1 - prog) * 3.4));
                    for (let dx = -halfW; dx <= halfW; dx++) {
                        const petalCol = (dx === 0 && y % 4 === 0) ? '#fdf4ff' : f.hue;
                        pRect(px + dx, py, 1, 2, petalCol);
                    }
                }
            }

        } else if (f.type === 'fern') {
            pRect(f.x - 2, baseGroundY - 1, 5, 2, '#14532d');
            for (let i = 1; i <= 3; i++) {
                const side = (i === 2) ? -f.dir : f.dir;
                const fh = f.h * (0.65 + i * 0.12);
                for (let y = 0; y < fh; y++) {
                    const prog = y / fh;
                    const curve = Math.pow(prog, 1.4) * 6 * side + Math.sin(time * 0.0016 + f.phase) * prog * 1.5;
                    const px = Math.round(f.x + curve);
                    const py = baseGroundY - y;
                    pRect(px, py, 1, 1, isLightMode ? '#15803d' : '#065f46');
                    if (y % 2 === 0 && y < fh - 2) {
                        const pinna = Math.max(1, Math.round((1 - prog) * 3));
                        pRect(px - pinna, py, pinna * 2 + 1, 1, isLightMode ? '#22c55e' : '#10b981');
                    }
                }
            }

        } else if (f.type === 'glow_mushroom') {
            const sway = Math.sin(time * 0.002 + f.phase) * 0.8;
            pRect(f.x - 2, baseGroundY - 1, 5, 2, isLightMode ? '#14532d' : '#064e3b');
            for (let y = 0; y < f.h; y++) {
                pRect(f.x + sway * (y / f.h), baseGroundY - y, 1, 1, '#e2e8f0');
            }
            const cx = Math.round(f.x + sway);
            const cy = Math.round(baseGroundY - f.h);
            pRect(cx - f.capR + 1, cy + 1, Math.max(1, (f.capR - 1) * 2 + 1), 1, '#94a3b8');
            pRect(cx - f.capR, cy, f.capR * 2 + 1, 2, f.col);
            pRect(cx - f.capR + 1, cy - 1, (f.capR - 1) * 2 + 1, 1, '#e0f2fe');
            if (!isLightMode) {
                pRect(cx - f.capR - 1, cy - 2, f.capR * 2 + 3, 4, 'rgba(56, 189, 248, 0.22)');
            }

        } else if (f.type === 'iris') {
            const sheathCol = isLightMode ? '#14532d' : '#063729';
            const bladeCol = isLightMode ? '#15803d' : '#0d5946';
            const bladeHi = isLightMode ? '#22c55e' : '#10b981';
            pRect(f.x - 2, baseGroundY - 1, 5, 2, sheathCol);
            for (let blade = -1; blade <= 1; blade++) {
                const bh = f.h * (blade === 0 ? 1 : 0.78);
                for (let y = 0; y < bh; y += 2) {
                    const prog = y / bh;
                    const sway = Math.sin(time * 0.0015 + f.phase + y * 0.05) * prog * 2.4 + blade * (y * 0.15);
                    pRect(f.x + sway, baseGroundY - y, blade === 0 ? 2 : 1, 2, blade === 0 ? bladeCol : bladeHi);
                }
            }
            const topX = Math.round(f.x + Math.sin(time * 0.0015 + f.phase + f.h * 0.05) * 2.4);
            const topY = Math.round(baseGroundY - f.h);
            pRect(topX - 1, topY + 1, 3, 1, bladeCol);
            pRect(topX - 3, topY - 1, 2, 2, f.col);
            pRect(topX + 2, topY - 1, 2, 2, f.col);
            pRect(topX - 2, topY - 2, 5, 2, f.col);
            pRect(topX - 1, topY - 4, 3, 3, f.col);
            pRect(topX, topY - 2, 1, 2, '#fef9c3');

        } else if (f.type === 'papyrus') {
            const stemDark = isLightMode ? '#14532d' : '#063729';
            const stemCol = isLightMode ? '#166534' : '#0c4a38';
            const rayCol = isLightMode ? '#22c55e' : '#10b981';
            let topX = f.x;
            const topY = Math.round(baseGroundY - f.h);
            pRect(f.x - 2, baseGroundY - 1, 5, 2, stemDark);
            for (let y = 0; y < f.h; y += 2) {
                const sway = Math.sin(time * 0.0014 + f.phase + y * 0.05) * (y / f.h) * 3;
                topX = Math.round(f.x + sway);
                pRect(topX, baseGroundY - y, 2, 2, stemCol);
            }
            pRect(topX - 1, topY, 4, 2, '#78350f');
            for (let r = -5; r <= 5; r++) {
                const arch = Math.abs(r) < 3 ? 2 : 1;
                pRect(topX + r, topY - arch, 1, 2, rayCol);
                if (Math.abs(r) % 2 === 1) {
                    pRect(topX + r, topY - arch - 1, 1, 1, '#fde68a');
                }
            }

        } else if (f.type === 'val' || f.type === 'ludwigia') {
            pRect(f.x - 1, baseGroundY - 1, 3, 2, f.type === 'ludwigia' ? '#4c0519' : '#064e3b');
            if (f.type === 'val') {
                [-1, 0, 1].forEach(ribbon => {
                    const rh = f.h * (ribbon === 0 ? 1 : 0.82);
                    for (let y = 0; y < rh; y++) {
                        const prog = y / rh;
                        const sway = Math.sin(time * 0.0016 + f.phase + y * 0.06 + ribbon * 0.4) * prog * 4.5 + ribbon * prog * 2.5;
                        const px = f.x + ribbon + sway;
                        const py = baseGroundY - y;
                        if (py < 4) break;
                        pRect(px, py, 1, 1, ribbon === 0 ? (isLightMode ? '#22c55e' : '#10b981') : (isLightMode ? '#15803d' : '#0f5138'));
                    }
                });
            } else {
                for (let y = 0; y < f.h; y++) {
                    const prog = y / f.h;
                    const sway = Math.sin(time * 0.0016 + f.phase + y * 0.07) * prog * 3.8;
                    const px = f.x + sway;
                    const py = baseGroundY - y;
                    if (py < 4) break;
                    const stemCol = prog > 0.6 ? '#be123c' : '#881337';
                    const leafCol = prog > 0.65 ? '#fda4af' : (prog > 0.35 ? '#fb7185' : '#e11d48');
                    pRect(px, py, 1, 1, stemCol);
                    if (y % 4 === 0 && y > 5) {
                        const span = prog > 0.75 ? 2 : 3;
                        pRect(px - span, py, span * 2 + 1, 1, leafCol);
                        pRect(px - span + 1, py - 1, Math.max(1, span - 1), 1, leafCol);
                        pRect(px + 1, py - 1, Math.max(1, span - 1), 1, leafCol);
                    }
                }
            }

        } else if (f.type === 'reed') {
            const stemCol = isLightMode ? '#166534' : '#0d4a3a';
            const bladeCol = isLightMode ? '#15803d' : '#115e49';
            const bladeHi = isLightMode ? '#22c55e' : '#10b981';
            let tipX = f.x;
            pRect(f.x - 2, baseGroundY - 1, 5, 2, stemCol);

            for (let y = 0; y < f.h; y++) {
                const prog = y / f.h;
                const sway = Math.sin(time * 0.0015 + f.phase + y * 0.045) * prog * 3.5 + (f.tilt || 0) * y;
                const px = f.x + sway;
                const py = baseGroundY - y;
                tipX = px;
                pRect(px, py, 1, 1, stemCol);

                if (y > 4 && y < f.h * 0.68 && y % 2 === 0) {
                    const bladeSpread = Math.sin(prog * Math.PI) * 3.8;
                    pRect(px - bladeSpread, py, 1, 2, bladeCol);
                    pRect(px + bladeSpread, py + 1, 1, 2, bladeHi);
                }

                if (f.hasCat && y > f.h - 17 && y < f.h - 5) {
                    pRect(px - 1, py, 3, 1, '#3b1806');
                    pRect(px - 1, py, 2, 1, '#5c2d16');
                    pRect(px, py, 1, 1, '#78350f');
                    if (y === Math.floor(f.h - 6)) {
                        pRect(px - 1, py - 1, 2, 1, '#fef3c7');
                    }
                }
                if (f.hasCat && y >= f.h - 5) {
                    pRect(px, py, 1, 1, '#d97706');
                }
            }
            f.tipX = tipX;
            f.tipY = baseGroundY - f.h;
            
        } else if (f.type === 'lily') {
            const driftX = Math.round(f.x + Math.sin(time * 0.001 + (f.phase || 0)) * 1.2);
            const ry = Math.max(2, Math.ceil(f.r * 0.55));
            const notchDir = f.notchDir || 1;
            const topPad = Math.max(ry, f.flower ? 5 : ry);
            const botPad = Math.max(ry, 4);

            const drawLilyPixels = (rectFn, ox, oy) => {
                const padDeep = isLightMode ? '#14532d' : '#083329';
                const padMid = isLightMode ? '#15803d' : '#0f513d';
                const padLight = isLightMode ? '#16a34a' : '#157154';
                const padRim = isLightMode ? '#4ade80' : '#2dd4bf';

                rectFn(ox - f.r + 1, oy + 2, f.r * 2 - 2, Math.max(2, Math.ceil(ry * 0.8)), 'rgba(2, 10, 18, 0.38)');
                for (let dy = -ry; dy <= ry; dy++) {
                    for (let dx = -f.r; dx <= f.r; dx++) {
                        const normDist = (dx * dx) / (f.r * f.r) + (dy * dy) / (ry * ry);
                        if (normDist <= 1) {
                            const ndx = dx * notchDir;
                            if (ndx > 1 && Math.abs(dy) <= Math.floor((ndx - 1) * 0.35)) continue;
                            let col = padMid;
                            if (normDist > 0.72 && dy <= 0) {
                                col = padRim;
                            } else if (normDist < 0.24) {
                                col = padDeep;
                            } else if (Math.abs(Math.abs(dx) - Math.abs(dy) * 2) <= 1 && normDist < 0.82) {
                                col = dy < 0 ? padLight : padDeep;
                            } else if (dy < 0 && normDist > 0.45) {
                                col = padLight;
                            }
                            rectFn(ox + dx, oy + dy, 1, 1, col);
                        }
                    }
                }
                if (f.flower) {
                    const flCol = f.flowerCol || '#f472b6';
                    rectFn(ox - 3, oy - 1, 7, 1, padDeep);
                    rectFn(ox - 3, oy - 2, 7, 1, flCol);
                    rectFn(ox - 2, oy - 3, 5, 2, flCol);
                    rectFn(ox - 2, oy - 3, 1, 1, '#ffffff');
                    rectFn(ox + 1, oy - 3, 1, 1, '#ffffff');
                    rectFn(ox - 1, oy - 4, 3, 2, '#ffffff');
                    rectFn(ox, oy - 2, 1, 1, '#facc15');
                }
            };

            if (!f._sprite || f._spriteLight !== isLightMode || f._spriteR !== f.r || f._spriteNotch !== notchDir) {
                const sp = createOffscreenSprite(f.r * 2 + 4, topPad + botPad + 2);
                if (sp) {
                    const { off, sctx } = sp;
                    drawLilyPixels((rx, ryPos, rw, rh, col) => {
                        sctx.fillStyle = col;
                        sctx.fillRect(rx, ryPos, rw, rh);
                    }, f.r + 1, topPad);
                    f._sprite = off;
                    f._spriteLight = isLightMode;
                    f._spriteR = f.r;
                    f._spriteNotch = notchDir;
                }
            }

            if (f._sprite) {
                ctx.drawImage(f._sprite, driftX - f.r - 1, Math.round(f.y) - topPad);
            } else {
                drawLilyPixels(pRect, driftX, f.y);
            }

            // BÖLÜM SONU: SULAK ALAN VE AKVARYUM BİTKİLERİ
            
       } else if (f.type === 'brain_coral') {
            // BÖLÜM BAŞI: RESİF VE DENİZ CANLILARI
            if (!f._sprite || f._spriteR !== f.r) {
                const sp = createOffscreenSprite((f.r + 1) * 2 + 1, f.r + 3);
                if (sp) {
                    const { off, sctx } = sp;
                    const ox = f.r + 1;
                    const oy = f.r;
                    sctx.fillStyle = 'rgba(5, 4, 23, 0.48)';
                    sctx.fillRect(ox - f.r - 1, oy, (f.r + 1) * 2, 2);
                    sctx.fillStyle = '#1e1b4b';
                    sctx.fillRect(ox - f.r, oy - 1, f.r * 2, 2);
                    for (let dy = -f.r; dy <= 0; dy++) {
                        const span = Math.round(f.r * Math.sqrt(Math.max(0, 1 - (dy * dy) / (f.r * f.r))));
                        for (let dx = -span; dx <= span; dx++) {
                            const groove = Math.sin(dx * 1.35 + Math.cos(dy * 1.2) * 1.5) > 0.15;
                            const isRim = dy < -f.r * 0.6 && Math.abs(dx) < span * 0.6;
                            const lightness = groove ? (isRim ? 74 : 64) : 26;
                            sctx.fillStyle = `hsla(${f.hue}, 90%, ${lightness}%, 0.92)`;
                            sctx.fillRect(ox + dx, oy + dy, 1, 1);
                        }
                    }
                    f._sprite = off;
                    f._spriteR = f.r;
                }
            }
            if (f._sprite) {
                ctx.drawImage(f._sprite, Math.round(f.x - f.r - 1), Math.round(baseGroundY - f.r));
            } else {
                pRect(f.x - f.r - 1, baseGroundY, (f.r + 1) * 2, 2, 'rgba(5, 4, 23, 0.48)');
                pRect(f.x - f.r, baseGroundY - 1, f.r * 2, 2, '#1e1b4b');
                for (let dy = -f.r; dy <= 0; dy++) {
                    const span = Math.round(f.r * Math.sqrt(Math.max(0, 1 - (dy * dy) / (f.r * f.r))));
                    for (let dx = -span; dx <= span; dx++) {
                        const groove = Math.sin(dx * 1.35 + Math.cos(dy * 1.2) * 1.5) > 0.15;
                        const isRim = dy < -f.r * 0.6 && Math.abs(dx) < span * 0.6;
                        const lightness = groove ? (isRim ? 74 : 64) : 26;
                        const col = `hsla(${f.hue}, 90%, ${lightness}%, 0.92)`;
                        pRect(f.x + dx, baseGroundY + dy, 1, 1, col);
                    }
                }
            }

        } else if (f.type === 'tube_sponge') {
            if (!f._cols) {
                const steps = 8;
                const walls = [];
                const shades = [];
                for (let s = 0; s < steps; s++) {
                    const lum = Math.round(32 + (s / (steps - 1)) * 28);
                    walls.push(`hsla(${f.hue}, 88%, ${lum}%, 0.90)`);
                    shades.push(`hsla(${f.hue}, 78%, ${Math.max(20, lum - 12)}%, 0.90)`);
                }
                f._cols = { baseShade: `hsla(${f.hue}, 75%, 24%, 0.92)`, walls, shades };
            }
            const baseShade = f._cols.baseShade;
            pRect(f.x - 5, baseGroundY, 11, 2, 'rgba(5, 4, 23, 0.45)');
            pRect(f.x - 5, baseGroundY - 2, 11, 3, baseShade);

            [-3, 0, 3].forEach((ox, idx) => {
                const th = Math.round(f.h * (idx === 1 ? 1 : (idx === 0 ? 0.76 : 0.84)));
                for (let y = 0; y < th; y++) {
                    const prog = y / th;
                    const sway = Math.sin(time * 0.0012 + f.phase + idx) * prog * 0.8;
                    const tx = Math.round(f.x + ox + sway);
                    const ty = baseGroundY - y;
                    const isTop = y >= th - 2;
                    const stepIdx = Math.min(7, Math.floor(prog * 8));
                    const wallCol = isTop ? '#fef08a' : f._cols.walls[stepIdx];
                    const shadeCol = f._cols.shades[stepIdx];
                    pRect(tx - 1, ty, 3, 1, shadeCol);
                    pRect(tx - 1, ty, 2, 1, wallCol);
                    if (y === th - 1) {
                        pRect(tx, ty, 1, 1, '#1e1b4b');
                    }
                }
            });

        } else if (f.type === 'sea_fan') {
            if (!f._cols) {
                f._cols = {
                    vein: `hsla(${f.hue}, 85%, 45%, 0.90)`,
                    mesh: `hsla(${f.hue}, 92%, 64%, 0.78)`,
                };
            }
            const stalkCol = '#311042';
            const veinCol = f._cols.vein;
            const meshCol = f._cols.mesh;
            const polypCol = '#fef08a';

            pRect(f.x - 2, baseGroundY - 1, 5, 2, stalkCol);
            pRect(f.x - 1, baseGroundY - 4, 3, 4, stalkCol);

            for (let y = 3; y < f.h; y++) {
                const prog = y / f.h;
                const sway = Math.sin(time * 0.0014 + f.phase + y * 0.08) * prog * 2.5;
                const spread = Math.round(Math.sin(prog * Math.PI * 0.92) * 7);
                const px = Math.round(f.x + sway);
                const py = baseGroundY - y;

                pRect(px, py, 1, 1, y < f.h * 0.45 ? stalkCol : veinCol);
                for (let dx = -spread; dx <= spread; dx++) {
                    const isEdge = Math.abs(dx) === spread;
                    const isMainVein = Math.abs(dx) === Math.round(spread * 0.5);
                    if (isEdge) {
                        pRect(px + dx, py, 1, 1, (y % 3 === 0) ? polypCol : meshCol);
                    } else if (isMainVein || (dx + y) % 2 === 0) {
                        pRect(px + dx, py, 1, 1, isMainVein ? veinCol : meshCol);
                    }
                }
            }

        } else if (f.type === 'kelp') {
            const holdfastCol = '#134e4a';
            const stipeCol = '#0f766e';
            const bladeDark = '#0d9488';
            const bladeLight = '#2dd4bf';

            pRect(f.x - 2, baseGroundY - 1, 5, 2, holdfastCol);
            for (let y = 0; y < f.h; y++) {
                const prog = y / f.h;
                const sway = Math.sin(time * 0.0015 + f.phase + y * 0.07) * prog * 5;
                const px = Math.round(f.x + sway);
                const py = baseGroundY - y;
                pRect(px, py, 1, 1, stipeCol);

                if (y > 5 && y % 5 === 0) {
                    const isLeft = (y % 10 === 0);
                    const bladeLen = Math.max(2, Math.round((1 - prog * 0.35) * 4));
                    pRect(px + (isLeft ? -1 : 1), py, 1, 1, '#5eead4');
                    for (let b = 1; b <= bladeLen; b++) {
                        const bx = px + (isLeft ? -b : b);
                        const by = py + Math.floor(b * 0.4);
                        pRect(bx, by, 1, 2, b === bladeLen ? bladeLight : bladeDark);
                    }
                }
            }

        } else if (f.type === 'anemone') {
            if (!f._cols) {
                const grad = [];
                for (let s = 0; s < 5; s++) {
                    grad.push(`hsla(${f.hue}, 92%, ${56 + s * 4}%, 0.88)`);
                }
                f._cols = { grad };
            }
            pRect(f.x - 4, baseGroundY, 9, 2, 'rgba(5, 4, 23, 0.45)');
            pRect(f.x - 4, baseGroundY - 2, 9, 2, '#3b0764');
            pRect(f.x - 3, baseGroundY - 4, 7, 3, '#581c87');
            pRect(f.x - 4, baseGroundY - 5, 9, 2, '#701a75');

            for (let t = -3; t <= 3; t++) {
                const tLen = Math.round(f.h * (1 - Math.abs(t) * 0.06));
                const sway = Math.sin(time * 0.003 + f.phase + t * 0.7) * 1.8;
                for (let y = 5; y <= tLen; y++) {
                    const prog = (y - 5) / Math.max(1, tLen - 5);
                    const tx = Math.round(f.x + t * (1.1 + prog * 0.5) + sway * prog);
                    const ty = baseGroundY - y;
                    const col = y >= tLen - 1 ? '#fef08a' : f._cols.grad[Math.min(4, Math.floor(prog * 5))];
                    pRect(tx, ty, 1, 1, col);
                }
            }
            // BÖLÜM SONU: RESİF VE DENİZ CANLILARI
        }
    });
}

// ============================================================================
// BÖLÜM SONU: FLORA VE BİTKİ KÜMELERİNİN HAREKETLİ ÇİZİMİ
// ============================================================================


// ============================================================================
// MODULE: js/09-scenery.js
// ============================================================================









const isArcticChristmasEnabled = () => (typeof window === 'undefined' ? false : window.__weArcticChristmas !== false);

// BÖLÜM BAŞI: ANİMASYONLU SAHNE VE HABİTAT EFEKTLERİ
// ============================================================================

let fallbackSunSprite = null;
let fallbackMoonSprite = null;
let auroraColCapacity = 0;
let auroraAy = null;
let auroraAh = null;
let auroraRayHalf = null;

function getFallbackSunSprite() {
    if (fallbackSunSprite) return fallbackSunSprite;
    try {
        const off = document.createElement('canvas');
        off.width = 21;
        off.height = 21;
        const sctx = off.getContext('2d');
        if (!sctx) return null;
        for (let dy = -10; dy <= 10; dy++) {
            for (let dx = -10; dx <= 10; dx++) {
                const d2 = dx * dx + dy * dy;
                if (d2 <= 49) {
                    sctx.fillStyle = '#fef08a';
                    sctx.fillRect(10 + dx, 10 + dy, 1, 1);
                } else if (d2 <= 95) {
                    sctx.fillStyle = 'rgba(253, 224, 71, 0.45)';
                    sctx.fillRect(10 + dx, 10 + dy, 1, 1);
                }
            }
        }
        fallbackSunSprite = off;
    } catch {
        fallbackSunSprite = null;
    }
    return fallbackSunSprite;
}

function getFallbackMoonSprite() {
    if (fallbackMoonSprite) return fallbackMoonSprite;
    try {
        const off = document.createElement('canvas');
        off.width = 19;
        off.height = 19;
        const mctx = off.getContext('2d');
        if (!mctx) return null;
        mctx.fillStyle = 'rgba(254, 249, 195, 0.78)';
        for (let dy = -9; dy <= 9; dy++) {
            for (let dx = -9; dx <= 9; dx++) {
                if (dx * dx + dy * dy <= 81 && (dx - 3) * (dx - 3) + (dy - 2) * (dy - 2) > 58) {
                    mctx.fillRect(9 + dx, 9 + dy, 1, 1);
                }
            }
        }
        fallbackMoonSprite = off;
    } catch {
        fallbackMoonSprite = null;
    }
    return fallbackMoonSprite;
}

function drawHabitatEnvironment(time) {
    resetFillStyleCache();
    const hab = HABITATS[currentHabitatIdx];
    beginAmbientWildlifeFrame(hab.sceneProfile, time);
    const topCol = isLightMode ? hab.lightTop : hab.skyTop;
    const midCol = isLightMode ? hab.lightMid : hab.skyMid;
    const botCol = isLightMode ? hab.lightBot : hab.skyBot;

    if (!sceneCache.bgCache || sceneCache.bgCache.hab !== hab.id || sceneCache.bgCache.light !== isLightMode || sceneCache.bgCache.w !== pw || sceneCache.bgCache.h !== ph) {
        const off = document.createElement('canvas');
        off.width = pw; off.height = ph;
        const o = off.getContext('2d');
        const steps = 48;
        for (let s = 0; s < steps; s++) {
            const t = s / (steps - 1);
            o.fillStyle = t < 0.5 ? lerpHex(topCol, midCol, t * 2) : lerpHex(midCol, botCol, (t - 0.5) * 2);
            o.fillRect(0, Math.floor(t * ph), pw, Math.ceil(ph / steps) + 1);
        }
        sceneCache.bgCache = { img: off, hab: hab.id, light: isLightMode, w: pw, h: ph };
        sceneCache.staticEnvCache = null;
    }
    ctx.drawImage(sceneCache.bgCache.img, 0, 0, pw, ph);

    if (!wxFxOn() && (hab.sceneProfile === 'botanical' || hab.sceneProfile === 'meadow' || hab.sceneProfile === 'wetland')) {
        const mx = Math.round(pw * 0.80);
        const my = 32;
        if (isLightMode) {
            const sunSp = getFallbackSunSprite();
            if (sunSp) {
                ctx.drawImage(sunSp, mx - 10, my - 10);
            } else {
                for (let dy = -10; dy <= 10; dy++) {
                    for (let dx = -10; dx <= 10; dx++) {
                        const d2 = dx * dx + dy * dy;
                        if (d2 <= 49) pRect(mx + dx, my + dy, 1, 1, '#fef08a');
                        else if (d2 <= 95) pRect(mx + dx, my + dy, 1, 1, 'rgba(253, 224, 71, 0.45)');
                    }
                }
            }
            for (let c = 0; c < 4; c++) {
                const cx = Math.round(((c * 115 + time * 0.004 * (c + 1)) % (pw + 50)) - 25);
                const cy = 22 + (c % 2) * 14;
                pRect(cx - 10, cy, 20, 4, 'rgba(255, 255, 255, 0.55)');
                pRect(cx - 6, cy - 3, 12, 3, 'rgba(255, 255, 255, 0.65)');
            }
        } else {
            const moonSp = getFallbackMoonSprite();
            if (moonSp) {
                ctx.drawImage(moonSp, mx - 9, my - 9);
            } else {
                for (let dy = -9; dy <= 9; dy++) {
                    for (let dx = -9; dx <= 9; dx++) {
                        if (dx * dx + dy * dy <= 81 && (dx - 3) * (dx - 3) + (dy - 2) * (dy - 2) > 58) {
                            pRect(mx + dx, my + dy, 1, 1, 'rgba(254, 249, 195, 0.78)');
                        }
                    }
                }
            }
            if (frameChance(0.002) && shootingStars.length === 0) {
                shootingStars.push({ x: Math.random() * pw * 0.65, y: 12 + Math.random() * 40, vx: 2.6, vy: 0.9, life: 28 });
            }
            for (let i = shootingStars.length - 1; i >= 0; i--) {
                const st = shootingStars[i];
                st.x += st.vx * frameScale; st.y += st.vy * frameScale; st.life -= frameScale;
                for (let t = 0; t < 5; t++) {
                    pRect(st.x - st.vx * t * 0.6, st.y - st.vy * t * 0.6, 1, 1, `rgba(255,255,255,${(1 - t / 5) * 0.7})`);
                }
                if (st.life <= 0) shootingStars.splice(i, 1);
            }
        }
    }

    drawWxSky(time, hab.weatherSky === true, hab.sceneProfile === 'rainforest');

    if (!sceneCache.staticEnvCache || sceneCache.staticEnvCache.hab !== hab.id || sceneCache.staticEnvCache.light !== isLightMode || sceneCache.staticEnvCache.w !== pw || sceneCache.staticEnvCache.h !== ph) {
        sceneCache.staticEnvCache = {
            img: buildStaticEnvironmentLayer(hab),
            hab: hab.id,
            light: isLightMode,
            w: pw,
            h: ph
        };
    }
    ctx.drawImage(sceneCache.staticEnvCache.img, 0, 0, pw, ph);

    if (hab.sceneProfile === 'betta-aquarium' || hab.sceneProfile === 'reef' || isLightMode) {
        setSceneFill(isLightMode ? 'rgba(255, 255, 255, 0.045)' : 'rgba(125, 211, 252, 0.024)');
        for (let r = 0; r < 5; r++) {
            const rx = ((r * 85 + Math.sin(time * 0.0005 + r) * 16) % pw);
            for (let y = 0; y < ph * 0.76; y += 3) {
                ctx.fillRect(Math.round(rx + y * 0.22), y, 11, 3);
            }
        }
    }

    if (hab.sceneProfile === 'meadow') {
        for (let ray = 0; ray < 4; ray++) {
            const rx = 28 + ray * Math.round(pw * 0.22);
            for (let s = 0; s < 6; s++) {
                const ry = 18 + s * 18 + (ray % 2) * 5;
                const shiftX = rx + Math.round(ry * 0.18 + Math.sin(time * 0.0005 + ray) * 2);
                pRect(shiftX, ry, 5, 7, isLightMode ? 'rgba(254, 240, 138, 0.055)' : 'rgba(251, 191, 36, 0.025)');
            }
        }

        const hx = Math.round(pw * 0.84);
        const hgy = getGroundY(hx, 'meadow', pw, ph) + 1;
        const bodyTop = hgy - 37;
        const sway = Math.round(Math.sin(time * 0.002) * 1);
        const lx = hx - 18 + sway;
        const ly = bodyTop + 4;

        pRect(hx - 18, bodyTop + 4, 1, 2, '#475569');
        pRect(lx, bodyTop + 5, 1, 2, '#64748b');
        pRect(lx - 1, ly + 2, 3, 1, '#78350f');
        pRect(lx - 2, ly + 3, 5, 1, '#451a03');
        pRect(lx - 2, ly + 4, 5, 4, '#fef08a');
        pRect(lx - 1, ly + 5, 3, 2, '#ffffff');
        pRect(lx - 5, ly + 1, 11, 10, 'rgba(253, 224, 71, 0.14)');
        pRect(lx - 3, ly + 2, 7, 8, 'rgba(253, 224, 71, 0.24)');
        pRect(lx - 2, ly + 8, 5, 1, '#451a03');

        const winPulse = (0.65 + 0.3 * Math.sin(time * 0.003)).toFixed(2);
        const ambientGlow = (0.14 + 0.06 * Math.sin(time * 0.003)).toFixed(2);
        pRect(hx - 13, ly + 3, 2, 8, `rgba(253, 224, 71, ${ambientGlow})`);
        pRect(hx - 18, hgy - 6, 8, 2, `rgba(253, 224, 71, ${ambientGlow})`);
        pRect(hx - 4, hgy - 23, 6, 3, `rgba(254, 240, 138, ${winPulse})`);
        pRect(hx - 3, hgy - 22, 4, 1, '#ffffff');

        for (let d = 0; d < 6; d++) {
            const dx = Math.round(((d * 97 + time * (0.008 + (d % 3) * 0.002)) % (pw + 40)) - 20);
            const dy = Math.round(ph * 0.35 + (d * 19) % Math.floor(ph * 0.45) + Math.sin(time * 0.002 + d) * 8);
            const seedTilt = Math.round(Math.sin(time * 0.003 + d) * 1);
            pRect(dx, dy + 1, 1, 2, '#78350f');
            pRect(dx + seedTilt, dy, 1, 1, 'rgba(226, 232, 240, 0.75)');
            pRect(dx - 1 + seedTilt, dy - 1, 3, 1, 'rgba(255, 255, 255, 0.85)');
            pRect(dx - 2 + seedTilt, dy - 2, 1, 1, 'rgba(255, 255, 255, 0.70)');
            pRect(dx + seedTilt, dy - 2, 1, 1, 'rgba(255, 255, 255, 0.95)');
            pRect(dx + 2 + seedTilt, dy - 2, 1, 1, 'rgba(255, 255, 255, 0.70)');
        }
    }

    if (hab.sceneProfile === 'betta-aquarium') {
        for (let s = 0; s < 12; s++) {
            const sx = Math.round(((s * 79 + Math.sin(time * 0.001 + s) * 14) % (pw - 40)) + 20);
            pRect(sx, 1 + (s % 2), 10 + (s % 3) * 6, 1, isLightMode ? 'rgba(255, 255, 255, 0.58)' : 'rgba(125, 211, 252, 0.28)');
        }

        const leafSway = Math.round(Math.sin(time * 0.0012) * 1);
        const catX = 18 + leafSway;
        pRect(catX - 4, 2, 4, 1, '#78350f');
        pRect(catX, 1, 22, 2, '#92400e');
        pRect(catX + 2, 1, 17, 1, '#b45309');
        pRect(catX + 5, 2, 12, 1, '#d97706');
        pRect(catX + 3, 3, 16, 1, '#78350f');
        for (let b = 0; b < 16; b++) {
            const bx = catX + 1 + (b * 1.5) + Math.sin(time * 0.002 + b) * 0.4;
            const by = 2 + (b % 3);
            pRect(bx, by, 2, 2, 'rgba(224, 242, 254, 0.78)');
            pRect(bx, by, 1, 1, '#ffffff');
        }

        const maxTrunkX = Math.min(190, Math.floor(pw * 0.46));
        for (let x = 22; x < maxTrunkX - 16; x += 22) {
            const t = x / maxTrunkX;
            const archY = Math.round(ph - 18 - Math.sin(t * Math.PI * 0.88) * 54 + Math.cos(t * 4) * 3);
            const rhizomeY = archY - 1;
            const isBuce = (x % 44 === 0);

            pRect(x - 4, rhizomeY, 9, 2, '#064e3b');
            pRect(x - 3, rhizomeY, 7, 1, '#047857');
            [-3, 0, 3].forEach(rx => {
                pRect(x + rx, rhizomeY + 2, 1, 3, '#14532d');
            });

            [-6, -3, 0, 3, 6].forEach((lx, lIdx) => {
                const sway = Math.sin(time * 0.002 + x + lIdx) * 1.1;
                const leafX = Math.round(x + lx + sway);
                const leafY = rhizomeY - 4 - (lIdx % 2) * 2;
                const stemBaseX = x + Math.round(lx * 0.5);

                const stemSteps = Math.max(1, rhizomeY - leafY);
                for (let st = 0; st <= stemSteps; st++) {
                    const prog = st / stemSteps;
                    const sx = Math.round(stemBaseX + (leafX - stemBaseX) * prog);
                    const sy = rhizomeY - st;
                    pRect(sx, sy, 1, 1, '#14532d');
                }

                if (isBuce) {
                    pRect(leafX - 2, leafY - 2, 4, 4, isLightMode ? '#0f766e' : '#115e59');
                    pRect(leafX - 1, leafY - 3, 3, 4, isLightMode ? '#14b8a6' : '#0d9488');
                    pRect(leafX, leafY - 2, 1, 1, '#c084fc');
                    pRect(leafX - 1, leafY - 3, 1, 1, '#67e8f9');
                } else {
                    pRect(leafX - 2, leafY - 2, 5, 4, isLightMode ? '#15803d' : '#065f46');
                    pRect(leafX - 1, leafY - 3, 3, 5, isLightMode ? '#22c55e' : '#10b981');
                    pRect(leafX, leafY - 2, 1, 2, '#86efac');
                }
            });

            if (isBuce) {
                const flX = x + Math.round(Math.sin(time * 0.0025 + x) * 1.4);
                const flY = rhizomeY - 11;
                for (let sy = rhizomeY - 1; sy >= flY + 2; sy--) {
                    const prog = (rhizomeY - sy) / 10;
                    pRect(Math.round(x + (flX - x) * prog), sy, 1, 1, '#10b981');
                }
                pRect(flX - 1, flY + 2, 3, 1, '#047857');
                pRect(flX - 2, flY, 5, 2, '#f8fafc');
                pRect(flX - 1, flY - 1, 3, 3, '#ffffff');
                pRect(flX, flY - 2, 1, 2, '#fef08a');
                pRect(flX - 3, flY - 2, 7, 5, 'rgba(224, 242, 254, 0.18)');
            }
        }

        [Math.round(pw * 0.31), Math.round(pw * 0.67)].forEach((cx, cIdx) => {
            const nx = cx / Math.max(1, pw);
            const baseY = Math.round(ph - 4 - Math.pow(Math.abs(nx - 0.50) * 1.95, 1.45) * 18 - Math.sin(cx * 0.04) * 2);
            pRect(cx - 2, baseY - 1, 5, 2, '#4c0519');
            for (let blade = -2; blade <= 2; blade++) {
                const sway = Math.sin(time * 0.0018 + blade + cIdx) * 1.5;
                const bh = 10 + (2 - Math.abs(blade)) * 4;
                const tipX = Math.round(cx + blade * 3.5 + sway);
                const tipY = baseY - bh;
                for (let st = 0; st < bh - 2; st++) {
                    const prog = st / Math.max(1, bh - 2);
                    pRect(Math.round(cx + (tipX - cx) * prog), baseY - st, 1, 1, '#881337');
                }
                pRect(tipX - 2, tipY, 5, 4, blade % 2 === 0 ? '#881337' : '#9f1239');
                pRect(tipX - 1, tipY - 1, 3, 4, '#e11d48');
                pRect(tipX, tipY, 1, 2, '#fda4af');
            }
        });

        const diffX = pw - 16;
        const diffFloorY = Math.round(ph - 4 - Math.pow(Math.abs((diffX / Math.max(1, pw)) - 0.50) * 1.95, 1.45) * 18);
        const diffY = diffFloorY - 10;
        pRect(pw - 3, diffY + 2, 3, 2, 'rgba(148, 163, 184, 0.55)');
        pRect(diffX + 3, diffY + 3, Math.max(1, pw - diffX - 5), 1, 'rgba(186, 230, 253, 0.45)');
        pRect(pw - 2, 3, 1, diffY + 1, 'rgba(186, 230, 253, 0.28)');
        pRect(diffX - 2, diffY, 5, 5, 'rgba(224, 242, 254, 0.52)');
        pRect(diffX - 1, diffY + 1, 3, 3, 'rgba(186, 230, 253, 0.35)');
        pRect(diffX - 1, diffY, 3, 1, '#ffffff');
        for (let m = 0; m < 12; m++) {
            const mRise = ((time * 0.015 + m * 6.5) % Math.max(8, diffY - 4));
            const mx = diffX + Math.sin(time * 0.005 + m * 1.3) * 1.6;
            const my = diffY - 2 - mRise;
            pRect(mx, my, 1, 1, 'rgba(224, 242, 254, 0.75)');
        }

        for (let i = 0; i < 12; i++) {
            const cycle = (time * (0.006 + (i % 3) * 0.001) + i * 23) % Math.max(36, ph * 0.72);
            const bx = 18 + ((i * 41) % Math.max(24, pw - 36)) + Math.sin(time * 0.0008 + i) * 2;
            const by = ph - 18 - cycle;
            pRect(bx, by, 2, 2, 'rgba(186, 230, 253, 0.28)');
            pRect(bx, by, 1, 1, 'rgba(224, 242, 254, 0.58)');
        }
    }
    
if (hab.sceneProfile === 'wetland') {
        const waterHorizonY = ph - 52;
        for (let s = 0; s < 14; s++) {
            const wy = waterHorizonY + 4 + (s * 3.3);
            const sx = Math.round(((s * 67 + Math.sin(time * 0.0012 + s) * 14) % (pw * 0.56)) + pw * 0.22);
            const sw = 8 + (s % 4) * 5;
            pRect(sx, wy, sw, 1, isLightMode ? 'rgba(224, 242, 254, 0.38)' : 'rgba(94, 234, 212, 0.16)');
        }

        for (let r = 0; r < 3; r++) {
            const cycle = ((time * 0.014 + r * 33) % 100) / 100;
            const rx = Math.round(pw * (0.35 + r * 0.14) + Math.sin(r * 2.1) * 14);
            const ry = Math.round(ph - 34 + (r % 2) * 14);
            const radX = Math.round(2 + cycle * 14);
            const alpha = ((1 - cycle) * 0.35).toFixed(2);
            pRect(rx - radX, ry, 2, 1, `rgba(186, 230, 253, ${alpha})`);
            pRect(rx + radX - 1, ry, 2, 1, `rgba(186, 230, 253, ${alpha})`);
            pRect(rx - Math.round(radX * 0.6), ry - 1, Math.round(radX * 1.2), 1, `rgba(186, 230, 253, ${(alpha * 0.5).toFixed(2)})`);
        }

        setSceneFill(isLightMode ? 'rgba(255, 255, 255, 0.13)' : 'rgba(167, 243, 208, 0.04)');
        for (let m = 0; m < 5; m++) {
            const mx = Math.round(((m * 95 + time * 0.005 * (m + 1)) % (pw + 90)) - 45);
            const my = waterHorizonY - 4 + m * 5;
            ctx.fillRect(mx, my, 48 + (m % 3) * 14, 2);
        }

        const stoneX = pw - 74;
        const stoneY = ph - 18;
        pRect(stoneX - 13, stoneY + 7, 28, 4, 'rgba(2, 10, 16, 0.48)');
        pRect(stoneX - 12, stoneY + 8, 26, 1, isLightMode ? 'rgba(186, 230, 253, 0.35)' : 'rgba(45, 212, 191, 0.18)');
        pRect(stoneX - 11, stoneY, 24, 8, isLightMode ? '#475569' : '#1e293b');
        pRect(stoneX - 9, stoneY - 3, 19, 4, isLightMode ? '#64748b' : '#334155');
        pRect(stoneX - 8, stoneY - 3, 12, 1, isLightMode ? '#94a3b8' : '#475569');
        pRect(stoneX - 7, stoneY - 4, 14, 2, isLightMode ? '#16a34a' : '#15803d');

        pRect(stoneX - 3, stoneY - 6, 2, 2, '#15803d');
        pRect(stoneX - 2, stoneY - 7, 5, 3, '#22c55e');
        pRect(stoneX - 1, stoneY - 8, 4, 2, '#4ade80');
        pRect(stoneX + 2, stoneY - 8, 1, 1, '#fef08a');
        if (Math.sin(time * 0.006) > 0.45) {
            pRect(stoneX + 3, stoneY - 6, 2, 2, '#bbf7d0');
            pRect(stoneX + 3, stoneY - 6, 1, 1, '#ffffff');
        }

        const pierShadow = isLightMode ? '#3b2313' : '#0f0d0c';
        const pierCol = isLightMode ? '#5c3a21' : '#1c1917';
        const pierHi = isLightMode ? '#854d0e' : '#332924';
        const py = ph - 40;

        pRect(0, py + 3, 64, 2, pierShadow);
        pRect(0, py, 64, 3, pierCol);
        pRect(0, py, 64, 1, pierHi);
        for (let px = 2; px < 62; px += 5) {
            pRect(px, py - 1, 4, 1, pierHi);
            pRect(px + 3, py, 1, 2, pierShadow);
        }

        for (let b = 0; b < 18; b++) {
            const bx = 16 + b;
            const by = py + 3 + Math.round(b * 0.42);
            pRect(bx, by, 2, 1, pierShadow);
            const bx2 = 38 + b;
            const by2 = py + 3 + Math.round(b * 0.45);
            pRect(bx2, by2, 2, 1, pierShadow);
        }

        [14, 36, 58].forEach((px, pIdx) => {
            const bankSurfaceY = getGroundY(px, 'wetland', pw, ph);
            const waterLineY = Math.min(ph - 10, bankSurfaceY + 4 + pIdx * 3);
            const postH = Math.max(18, waterLineY - (py - 9));

            pRect(px, py - 9, 3, postH, pierCol);
            pRect(px, py - 9, 1, postH, pierHi);
            pRect(px + 2, py - 9, 1, postH, pierShadow);
            pRect(px, py - 10, 3, 1, '#a16207');

            pRect(px - 2, waterLineY - 1, 7, 2, 'rgba(2, 10, 16, 0.48)');
            pRect(px - 3, waterLineY, 9, 1, isLightMode ? 'rgba(186, 230, 253, 0.38)' : 'rgba(45, 212, 191, 0.20)');
            for (let ry = 1; ry <= 4; ry++) {
                pRect(px, waterLineY + ry * 2, 3, 1, 'rgba(15, 23, 42, 0.30)');
            }

            if (px === 58) {
                const sway = Math.round(Math.sin(time * 0.0025) * 1);
                pRect(px + 2, py - 9, 6, 1, pierCol);
                pRect(px + 2, py - 8, 2, 1, pierShadow);
                pRect(px + 6 + sway, py - 8, 1, 2, '#475569');
                pRect(px + 4 + sway, py - 6, 5, 1, '#451a03');
                pRect(px + 5 + sway, py - 5, 3, 4, '#fef08a');
                pRect(px + 6 + sway, py - 4, 1, 2, '#ffffff');
                pRect(px + 4 + sway, py - 1, 5, 1, '#451a03');
                pRect(px + 3 + sway, py - 7, 7, 7, 'rgba(253, 224, 71, 0.22)');
                for (let ry = 0; ry < 5; ry++) {
                    const rShift = Math.sin(time * 0.004 + ry * 1.3) * 2;
                    pRect(px + 4 + rShift, waterLineY + 1 + ry * 2, 4 - Math.floor(ry * 0.5), 1, `rgba(253, 224, 71, ${(0.38 - ry * 0.06).toFixed(2)})`);
                }
            }
        });
    }

    if (hab.sceneProfile === 'botanical') {
        const reach = Math.min(155, Math.round(pw * 0.30));
        [Math.round(reach * 0.48), Math.round(pw - reach * 0.48)].forEach((lx, idx) => {
            const t = 0.48;
            const branchY = Math.round(5 + Math.pow(t, 1.2) * 15 + Math.sin(lx * 0.09) * 1.5);
            const sway = Math.round(Math.sin(time * 0.002 + idx * 2) * 1);

            pRect(lx - 1, branchY, 3, 2, '#334155');
            for (let cy = 1; cy <= 6; cy++) {
                const cx = lx + (cy > 3 ? sway : 0);
                pRect(cx, branchY + cy, 1, 1, '#64748b');
            }
            pRect(lx - 1 + sway, branchY + 6, 3, 1, '#475569');
            pRect(lx - 2 + sway, branchY + 7, 5, 1, '#334155');
            pRect(lx - 2 + sway, branchY + 8, 5, 5, 'rgba(253, 224, 71, 0.88)');
            pRect(lx - 1 + sway, branchY + 9, 3, 3, '#ffffff');
            pRect(lx - 5 + sway, branchY + 5, 11, 11, 'rgba(253, 224, 71, 0.16)');
            pRect(lx - 2 + sway, branchY + 13, 5, 1, '#334155');
            pRect(lx - 1 + sway, branchY + 14, 3, 1, '#1e293b');
        });

        const fx = Math.round(pw * 0.18);
        const fy = getGroundY(fx, 'botanical', pw, ph) + 1;
        const plumeH = 3 + Math.round(Math.sin(time * 0.008) * 1);
        pRect(fx, fy - 31 - plumeH, 1, plumeH, '#e0f2fe');
        pRect(fx - 1, fy - 31 - plumeH, 3, 1, '#ffffff');

        const dropPhase = (time * 0.015) % 6;
        [-1, 1].forEach(side => {
            const dx = fx + side * Math.round(2 + dropPhase * 1.4);
            const dy = fy - 29 + Math.round(dropPhase * 1.1);
            pRect(dx, dy, 1, 2, '#bae6fd');
            const cascadeX = fx + side * 11;
            const cascadeY = fy - 21 + Math.floor((time * 0.02 + (side > 0 ? 3 : 0)) % 14);
            pRect(cascadeX, fy - 21, 1, 16, 'rgba(186, 230, 253, 0.30)');
            pRect(cascadeX, cascadeY, 1, 3, '#e0f2fe');
            pRect(cascadeX - 1, fy - 5, 3, 1, '#ffffff');
        });
        pRect(fx - 8 + Math.sin(time * 0.005) * 4, fy - 23, 4, 1, '#ffffff');
        pRect(fx - 9 - Math.cos(time * 0.004) * 4, fy - 5, 4, 1, '#bae6fd');

        for (let i = 0; i < 8; i++) {
            const fxPos = (i * 73 + Math.sin(time * 0.001 + i) * 12) % pw;
            const fyPos = ph * 0.36 + Math.sin(time * 0.0014 + i * 1.7) * 22;
            const glow = 0.32 + 0.40 * (0.5 + 0.5 * Math.sin(time * 0.004 + i));
            pRect(fxPos, fyPos, 2, 2, i % 3 === 0 ? `rgba(232, 121, 249, ${glow.toFixed(2)})` : `rgba(253, 224, 71, ${glow.toFixed(2)})`);
        }
    }
    
    if (hab.sceneProfile === 'reef') {
        for (let c = 0; c < 12; c++) {
            const cx = Math.round(((c * 61 + Math.sin(time * 0.001 + c) * 18) % (pw * 0.56)) + pw * 0.22);
            const cy = 2 + (c % 3) * 3;
            pRect(cx, cy, 10 + (c % 4) * 4, 1, isLightMode ? 'rgba(224, 242, 254, 0.58)' : 'rgba(103, 232, 249, 0.26)');
        }

        const clamX = Math.floor(pw * 0.72);
        const clamNx = clamX / Math.max(1, pw);
        const clamMound = clamNx > 0.74 ? Math.pow((clamNx - 0.74) / 0.26, 1.5) * 34 : 0;
        const clamY = Math.round(getGroundY(clamX, 'reef', pw, ph) - clamMound) - 1;
        const openJaw = Math.round(2 + Math.sin(time * 0.0022) * 1.2);

        // Kaya kaide ve temas gölgesi
        pRect(clamX - 11, clamY + 2, 23, 3, 'rgba(5, 4, 23, 0.55)');
        pRect(clamX - 10, clamY, 21, 3, '#1e1b4b');

        // Alt kabuk, oluklu kabuk sırtları ve menteşe bağlantısı
        pRect(clamX - 9, clamY - 3, 19, 4, '#312e81');
        for (let rx = -7; rx <= 7; rx += 3) {
            pRect(clamX + rx, clamY - 3, 2, 3, '#4338ca');
        }
        pRect(clamX - 9, clamY - openJaw - 4, 3, openJaw + 3, '#1e1b4b');

        // Alt ve üst kabuğu birbirine fiziksel olarak bağlayan biyolüminesan manto dokusu
        const mantleH = openJaw + 3;
        pRect(clamX - 7, clamY - 2 - mantleH, 15, mantleH, '#701a75');
        pRect(clamX - 8, clamY - 2, 17, 2, '#a21caf');
        pRect(clamX - 6, clamY - 1 - mantleH, 13, 2, '#d946ef');
        for (let mx = -5; mx <= 5; mx += 2) {
            pRect(clamX + mx, clamY - 2, 1, 1, '#38bdf8');
            pRect(clamX + mx, clamY - 1 - mantleH, 1, 1, '#f0abfc');
        }

        // İnci ve parıltı halesi (manto yatağının içinde oturur)
        pRect(clamX - 4, clamY - 7, 9, 7, 'rgba(240, 171, 252, 0.24)');
        pRect(clamX - 2, clamY - 5, 5, 4, '#fef08a');
        pRect(clamX - 1, clamY - 5, 3, 3, '#fef9c3');
        pRect(clamX - 1, clamY - 4, 2, 2, '#ffffff');

        // Üst kabuk ve oluklu kenarları
        pRect(clamX - 8, clamY - openJaw - 5, 16, 3, '#311042');
        pRect(clamX - 7, clamY - openJaw - 6, 14, 2, '#4c1d95');
        for (let rx = -6; rx <= 6; rx += 3) {
            pRect(clamX + rx, clamY - openJaw - 6, 2, 1, '#818cf8');
        }
        pRect(clamX - 6, clamY - openJaw - 3, 13, 1, '#e879f9');

        // Resif tabanındaki belirli yarıklardan yükselen mikro kabarcık sütunları
        const ventPositions = [0.18, 0.34, 0.48, 0.63, 0.82];
        for (let i = 0; i < 14; i++) {
            const vPos = ventPositions[i % ventPositions.length];
            const baseBx = Math.round(pw * vPos + ((i * 7) % 9) - 4);
            const floorY = getGroundY(baseBx, 'reef', pw, ph);
            const maxRise = Math.max(40, floorY - 8);
            const rise = (time * (0.0045 + (i % 3) * 0.0012) + i * 21) % maxRise;
            const bx = baseBx + Math.sin(time * 0.0015 + i) * 2;
            const by = floorY - 4 - rise;
            pRect(bx, by, 2, 2, 'rgba(103, 232, 249, 0.35)');
            pRect(bx, by, 1, 1, i % 3 === 0 ? '#f0abfc' : '#cffafe');
        }
    }
    
    if (hab.sceneProfile === 'koi-pond') {
        for (let s = 0; s < 14; s++) {
            const wy = 32 + s * Math.floor((ph - 44) / 14);
            const sx = Math.round(((s * 73 + Math.sin(time * 0.001 + s) * 16) % (pw * 0.56)) + pw * 0.20);
            pRect(sx, wy, 9 + (s % 3) * 5, 1, isLightMode ? 'rgba(224, 242, 254, 0.34)' : 'rgba(125, 211, 252, 0.14)');
        }

        const bx = pw - 42;
        const by = ph - 18;
        const streamX = bx - 23;
        pRect(streamX, by - 3, 1, 8, 'rgba(186, 230, 253, 0.52)');
        for (let d = 0; d < 3; d++) {
            const dropOffset = Math.floor((time * 0.024 + d * 2.5) % 8);
            pRect(streamX, by - 3 + dropOffset, 1, 2, '#e0f2fe');
        }
        pRect(streamX - 1, by + 4, 3, 1, '#ffffff');

        for (let ring = 0; ring < 2; ring++) {
            const rippleR = ((time * 0.014 + ring * 5) % 10);
            const rAlpha = ((1 - rippleR / 10) * 0.48).toFixed(2);
            pRect(streamX - rippleR, by + 5, 2, 1, `rgba(224, 242, 254, ${rAlpha})`);
            pRect(streamX + rippleR, by + 5, 2, 1, `rgba(224, 242, 254, ${rAlpha})`);
            pRect(streamX - Math.round(rippleR * 0.6), by + 6, Math.max(2, Math.round(rippleR * 1.2)), 1, `rgba(186, 230, 253, ${(rAlpha * 0.5).toFixed(2)})`);
        }

        const glowAlpha = (0.78 + 0.2 * Math.sin(time * 0.004)).toFixed(2);
        pRect(bx - 3, by - 16, 7, 4, `rgba(253, 224, 71, ${glowAlpha})`);
        pRect(bx - 1, by - 15, 3, 2, '#ffffff');
        pRect(bx, by - 16, 1, 4, '#1e293b');
        pRect(bx - 7, by - 18, 15, 9, 'rgba(251, 191, 36, 0.16)');
        for (let ry = 0; ry < 6; ry++) {
            const drift = Math.sin(time * 0.003 + ry * 1.4) * 2.2;
            pRect(bx - 4 + drift, by + 10 + ry * 2, 7 - ry, 1, `rgba(251, 191, 36, ${(0.34 - ry * 0.05).toFixed(2)})`);
        }
    }
    
    if (hab.sceneProfile === 'arctic-tundra') {
        const auroraAlpha = isLightMode ? 0.08 : 0.15;
        const step = 3;
        const colCount = Math.ceil(pw / step);
        if (auroraColCapacity < colCount) {
            auroraColCapacity = colCount + 16;
            auroraAy = new Int16Array(auroraColCapacity);
            auroraAh = new Int16Array(auroraColCapacity);
            auroraRayHalf = new Int16Array(auroraColCapacity);
        }

        for (let band = 0; band < 2; band++) {
            const upperCol = band === 0
                ? `rgba(16, 185, 129, ${(auroraAlpha * 0.55).toFixed(2)})`
                : `rgba(139, 92, 246, ${(auroraAlpha * 0.50).toFixed(2)})`;
            const midCol = band === 0
                ? `rgba(52, 211, 153, ${auroraAlpha})`
                : `rgba(168, 85, 247, ${(auroraAlpha * 0.85).toFixed(2)})`;
            const lowerRim = band === 0
                ? `rgba(167, 243, 208, ${(auroraAlpha * 1.45).toFixed(2)})`
                : `rgba(216, 180, 254, ${(auroraAlpha * 1.15).toFixed(2)})`;

            for (let cIdx = 0; cIdx < colCount; cIdx++) {
                const x = cIdx * step;
                const wave = Math.sin(x * 0.016 + time * 0.0007 + band * 2.1) * 9
                           + Math.cos(x * 0.038 - time * 0.0010) * 4;
                const curtainRay = Math.max(0, Math.sin(x * 0.09 + time * 0.0016 + band)) * 8;
                auroraAy[cIdx] = Math.round(12 + band * 15 + wave);
                auroraAh[cIdx] = Math.round(14 + curtainRay);
                auroraRayHalf[cIdx] = Math.floor(curtainRay * 0.5);
            }

            setSceneFill(upperCol);
            for (let cIdx = 0; cIdx < colCount; cIdx++) {
                ctx.fillRect(cIdx * step, auroraAy[cIdx] - auroraRayHalf[cIdx], step, Math.floor(auroraAh[cIdx] * 0.55));
            }
            setSceneFill(midCol);
            for (let cIdx = 0; cIdx < colCount; cIdx++) {
                ctx.fillRect(cIdx * step, auroraAy[cIdx] + Math.floor(auroraAh[cIdx] * 0.35), step, Math.floor(auroraAh[cIdx] * 0.65));
            }
            setSceneFill(lowerRim);
            for (let cIdx = 0; cIdx < colCount; cIdx++) {
                ctx.fillRect(cIdx * step, auroraAy[cIdx] + auroraAh[cIdx] - 2, step, 2);
            }
        }

        const cabBaseX = Math.round(pw * 0.73);
        const cabSurfaceY = Math.round(ph * 0.60 + Math.sin(cabBaseX * 0.06) * 1.5) + 1;
        const glowPulse = (0.72 + 0.22 * Math.sin(time * 0.003)).toFixed(2);
        const snowGlow = (0.16 + 0.08 * Math.sin(time * 0.003)).toFixed(2);

        pRect(cabBaseX - 1, cabSurfaceY - 10, 3, 1, `rgba(254, 249, 195, ${glowPulse})`);
        pRect(cabBaseX + 3, cabSurfaceY - 10, 3, 1, `rgba(254, 249, 195, ${glowPulse})`);
        pRect(cabBaseX - 3, cabSurfaceY - 2, 12, 2, `rgba(253, 224, 71, ${snowGlow})`);

        const flueX = cabBaseX + 6;
        const flueY = cabSurfaceY - 26;
        for (let s = 0; s < 6; s++) {
            const rise = ((time * 0.011 + s * 5) % 28);
            const sx = flueX + Math.sin(time * 0.002 + s * 0.9) * (0.8 + rise * 0.14);
            const sy = flueY - rise;
            const alpha = ((1 - rise / 28) * 0.42).toFixed(2);
            const size = 2 + Math.floor(rise / 10);
            pRect(sx, sy, size, 2, `rgba(226, 232, 240, ${alpha})`);
        }

        if (isArcticChristmasEnabled()) {
            drawArcticChristmasSky(time);
        }
    }
    
    if (hab.sceneProfile === 'rainforest') {
        for (let ray = 0; ray < 5; ray++) {
            const baseX = (ray * 112 + 34) % pw;
            for (let segment = 0; segment < 7; segment++) {
                const y = 18 + segment * 16 + (ray % 3) * 4;
                const x = baseX + Math.round(y * 0.16 + Math.sin(time * 0.0005 + ray) * 1.5);
                pRect(x, y, 5 + (segment % 2), 12, isLightMode ? 'rgba(254, 240, 138, 0.055)' : 'rgba(167, 243, 208, 0.032)');
            }
        }

        // Zeminle bütünleşik 2 kademeli kireçtaşı şelalesi & turkuaz lagün havuzu animasyonu
        const wfX = Math.round(pw * 0.50);
        const poolSurfY = ph - 8;
        const cliffH = Math.min(72, Math.max(48, Math.round(ph * 0.25)));
        const cliffTopY = poolSurfY - cliffH;
        const midShelfY = poolSurfY - Math.round(cliffH * 0.46);
        const cliffBaseHalfW = Math.min(38, Math.max(24, Math.round(pw * 0.068)));
        const poolHalfW = Math.round(cliffBaseHalfW * 0.94);

        const waterBaseCol = isLightMode ? 'rgba(125, 211, 252, 0.52)' : 'rgba(56, 189, 248, 0.34)';
        const waterCoreCol = isLightMode ? 'rgba(224, 242, 254, 0.82)' : 'rgba(165, 243, 252, 0.58)';
        const waterFoamCol = isLightMode ? 'rgba(240, 249, 255, 0.90)' : 'rgba(207, 250, 254, 0.65)';

        // Üst kayadan fışkıran akış (kaynak oyuğundan orta kaya rafına)
        const upperSpan = Math.max(4, midShelfY - (cliffTopY + 3));
        pRect(wfX - 3, cliffTopY + 3, 6, upperSpan, waterBaseCol);
        pRect(wfX - 2, cliffTopY + 3, 4, upperSpan, waterCoreCol);
        for (let s = 0; s < 5; s++) {
            const sy = cliffTopY + 3 + ((Math.floor(time * 0.032) + s * 6) % upperSpan);
            pRect(wfX - 2 + (s % 4), sy, 1, 3, waterFoamCol);
        }

        // Orta kaya rafında köpük patlaması
        const shelfFoam = 5 + Math.round(Math.sin(time * 0.008) * 1);
        pRect(wfX - shelfFoam, midShelfY - 2, shelfFoam * 2, 2, waterFoamCol);

        // Rafın üzerinden turkuaz lagüne dökülen ikiz alt akış
        const lowerSpan = Math.max(6, poolSurfY - (midShelfY + 1));
        pRect(wfX - 4, midShelfY + 1, 5, lowerSpan, waterBaseCol);
        pRect(wfX - 3, midShelfY + 1, 3, lowerSpan, waterCoreCol);
        pRect(wfX + 2, midShelfY + 1, 2, lowerSpan, waterBaseCol);
        for (let s = 0; s < 6; s++) {
            const sy = midShelfY + 1 + ((Math.floor(time * 0.036) + s * 5) % lowerSpan);
            pRect(wfX - 3 + (s % 3), sy, 1, 3, waterFoamCol);
            if (s % 2 === 0) pRect(wfX + 2, sy, 1, 2, waterCoreCol);
        }

        // Lagün suyunda köpük halkası ve genişleyen dalgalar
        const foamSpread = 6 + Math.round(Math.sin(time * 0.006) * 2);
        pRect(wfX - foamSpread, poolSurfY - 1, foamSpread * 2, 2, waterFoamCol);
        pRect(wfX - foamSpread - 4, poolSurfY + 1, (foamSpread + 4) * 2, 1, isLightMode ? 'rgba(186, 230, 253, 0.45)' : 'rgba(45, 212, 191, 0.25)');
        for (let rIdx = 0; rIdx < 3; rIdx++) {
            const rp = ((time * 0.0007 + rIdx * 0.33) % 1);
            const rHalf = Math.round(8 + rp * (poolHalfW - 10));
            const ry = Math.min(ph - 1, poolSurfY + 2 + Math.round(rp * 4));
            const rAlpha = ((1 - rp) * 0.32).toFixed(2);
            pRect(wfX - rHalf, ry, rHalf * 2, 1, `rgba(186, 230, 253, ${rAlpha})`);
        }
        // Havuzdan süzülen serin şelale buğusu
        for (let m = 0; m < 4; m++) {
            const mp = ((time * 0.0005 + m * 0.25) % 1);
            const mx = wfX - 7 + m * 4 + Math.round(Math.sin(time * 0.002 + m) * 2);
            const my = poolSurfY - 2 - Math.round(mp * 9);
            const mAlpha = ((1 - mp) * 0.28).toFixed(2);
            pRect(mx, my, 3, 2, `rgba(224, 242, 254, ${mAlpha})`);
        }

        // YERİNDE YAŞAYAN DURGUN CANLILAR (Tıklayınca tepki verirler; yem/uyaran düşürmezler)
        // 1. Toco Tukan (~22x24px kahraman ölçek, tıklayınca kanat açıp iki kez öter)
        const tx = Math.floor(pw * 0.22) + 8;
        const ty = Math.floor(ph * 0.36) + 22;
        const toucanReact = getAmbientReaction('rainforest_toucan', time);
        const toucanHop = toucanReact ? -Math.round(Math.abs(Math.sin(toucanReact.progress * Math.PI * 2)) * 5) : 0;
        const toucanPhase = (time % 16000) / 16000;
        const toucanBreath = toucanReact ? 0 : (Math.sin(time * 0.0018) > 0.45 ? -1 : 0);
        const toucanBlink = !toucanReact && (time % 5600) > 5440;
        const toucanAlert = toucanReact ? -1 : ((toucanPhase >= 0.68 && toucanPhase < 0.96) ? -1 : 0);
        const toucanCall = toucanReact
            ? (Math.sin(toucanReact.progress * Math.PI * 6) > 0 ? 2 : 0)
            : ((toucanPhase >= 0.80 && toucanPhase < 0.93) && Math.sin((toucanPhase - 0.80) * Math.PI * 16) > 0 ? 1 : 0);
        const toucanTailLift = (toucanReact || (toucanPhase >= 0.72 && toucanPhase < 0.90)) ? -1 : 0;
        const tBodyY = ty + toucanBreath + toucanAlert + toucanHop;

        pRect(tx - 6, ty + 1, 14, 2, '#573b26');
        pRect(tx - 5, ty + 1, 12, 1, '#714d33');
        pRect(tx - 1, ty, 2, 2, '#64748b');
        pRect(tx + 3, ty, 2, 2, '#64748b');

        pRect(tx - 7, tBodyY + 1 + toucanTailLift, 4, 8, '#090d16');
        pRect(tx - 6, tBodyY + 2 + toucanTailLift, 2, 6, '#1e293b');
        pRect(tx - 5, tBodyY - 1, 3, 2, '#dc2626');
        pRect(tx - 4, tBodyY, 2, 1, '#ef4444');

        if (toucanReact) {
            const wingLift = Math.round(Math.sin(toucanReact.progress * Math.PI * 6) * 2);
            pRect(tx - 11, tBodyY - 12 + wingLift, 8, 7, '#0f172a');
            pRect(tx - 10, tBodyY - 11 + wingLift, 6, 4, '#334155');
            pRect(tx + 11, tBodyY - 19 - Math.round(toucanReact.progress * 7), 2, 2, '#fde047');
            pRect(tx + 14, tBodyY - 21 - Math.round(toucanReact.progress * 7), 2, 1, '#fef08a');
        }

        pRect(tx - 5, tBodyY - 10, 9, 10, '#090d16');
        pRect(tx - 4, tBodyY - 11, 7, 10, '#0f172a');
        pRect(tx - 4, tBodyY - 8, 5, 6, '#1e293b');
        pRect(tx - 3, tBodyY - 7, 3, 4, '#334155');

        pRect(tx + 1, tBodyY - 14, 6, 8, '#fde047');
        pRect(tx + 2, tBodyY - 13, 5, 6, '#fef08a');
        pRect(tx + 3, tBodyY - 12, 3, 4, '#fef9c3');
        pRect(tx, tBodyY - 16, 6, 4, '#090d16');
        pRect(tx + 1, tBodyY - 17, 4, 2, '#0f172a');

        pRect(tx + 3, tBodyY - 15, 3, 2, '#38bdf8');
        if (!toucanBlink) {
            pRect(tx + 4, tBodyY - 15, 1, 1, '#020617');
            pRect(tx + 4, tBodyY - 14, 1, 1, '#090d16');
        } else {
            pRect(tx + 4, tBodyY - 15, 1, 1, '#0284c7');
        }

        pRect(tx + 6, tBodyY - 16, 8, 4, '#ea580c');
        pRect(tx + 7, tBodyY - 16, 7, 2, '#f97316');
        pRect(tx + 8, tBodyY - 15, 5, 1, '#fb923c');
        pRect(tx + 14, tBodyY - 15, 2, 3, '#c2410c');
        pRect(tx + 15, tBodyY - 15, 1, 2, '#0f172a');
        pRect(tx + 6, tBodyY - 12 + toucanCall, 7, 2, '#c2410c');
        pRect(tx + 13, tBodyY - 12 + toucanCall, 1, 1, '#0f172a');

        registerAmbientHitbox('rainforest_toucan', tx - 10, tBodyY - 19, tx + 18, ty + 4, 3);

        // 2. Üç Parmaklı Tembel Hayvan (~24x18px, tıklayınca başını kaldırıp gülümser & patisini sallar)
        const sx = Math.floor(pw * 0.78) - 4;
        const sy = Math.floor(ph * 0.34) + 23;
        const slothReact = getAmbientReaction('rainforest_sloth', time);
        const slothPhase = (time % 18000) / 18000;
        const slothSway = slothReact ? Math.round(Math.sin(slothReact.progress * Math.PI * 2) * 1.2) : Math.round(Math.sin(time * 0.00075) * 0.65);
        const slothBlink = !slothReact && (time % 6200) > 5880;
        const slothStretch = slothReact ? 1 : ((slothPhase >= 0.66 && slothPhase < 0.92) ? Math.sin(((slothPhase - 0.66) / 0.26) * Math.PI) : 0);
        const leftReach = slothReact ? 5 : Math.round(slothStretch * 4);
        const pawWaveX = slothReact ? Math.round(Math.sin(slothReact.progress * Math.PI * 5) * 3) : 0;
        const headPerkY = slothReact ? -2 : 0;
        const slX = sx + slothSway;

        pRect(sx - 10, sy - 4, 22, 2, '#573b26');
        pRect(sx - 9, sy - 4, 20, 1, '#714d33');
        if (leftReach === 0) {
            pRect(slX - 7, sy - 5, 3, 2, '#cbd5e1');
            pRect(slX - 7, sy - 5, 1, 1, '#64748b');
        }
        pRect(slX + 5, sy - 5, 3, 2, '#cbd5e1');
        pRect(slX + 7, sy - 5, 1, 1, '#64748b');

        pRect(slX - 7 + pawWaveX, sy - 3 + leftReach, 3, 7, '#6b5344');
        pRect(slX - 6 + pawWaveX, sy - 2 + leftReach, 2, 5, '#8c6d53');
        if (leftReach > 0) {
            pRect(slX - 7 + pawWaveX, sy + 4 + leftReach, 3, 2, '#cbd5e1');
        }
        pRect(slX + 4, sy - 3, 4, 7, '#6b5344');
        pRect(slX + 5, sy - 2, 2, 5, '#8c6d53');

        pRect(slX - 8, sy + 3, 16, 8, '#785c48');
        pRect(slX - 6, sy + 5, 13, 6, '#574032');
        pRect(slX - 5, sy + 4, 10, 4, '#8c6d53');
        pRect(slX - 2, sy + 7, 6, 2, '#65a30d');
        pRect(slX, sy + 8, 3, 1, '#84cc16');

        pRect(slX - 11, sy + 1 + headPerkY, 6, 6, '#fde68a');
        pRect(slX - 10, sy + 2 + headPerkY, 5, 4, '#fef3c7');
        pRect(slX - 11, sy + 3 + headPerkY, 2, 2, '#57534e');
        pRect(slX - 7, sy + 3 + headPerkY, 2, 2, '#57534e');
        pRect(slX - 10, sy + 3 + headPerkY, 1, 1, slothBlink ? '#a8a29e' : '#1c1917');
        pRect(slX - 7, sy + 3 + headPerkY, 1, 1, slothBlink ? '#a8a29e' : '#1c1917');
        pRect(slX - 9, sy + 5 + headPerkY, 2, 1, '#44403c');
        if (slothReact) {
            pRect(slX - 13, sy - 3, 2, 2, '#4ade80');
            pRect(slX - 10, sy - 6, 2, 2, '#fde047');
        }

        registerAmbientHitbox('rainforest_sloth', slX - 13, sy - 6, slX + 10, sy + 14 + leftReach, 3);

        // 3. Büyütülmüş Kırmızı Gözlü Ağaç Kurbağası (~22x16px, tıklayınca sıçrayıp ateşböceğine dil atar & geri döner)
        const fxHome = Math.max(155, Math.min(Math.round(pw * 0.34), wfX - poolHalfW - 22));
        const fBaseY = getGroundY(fxHome, 'rainforest', pw, ph);
        const leafY = fBaseY - 8;

        // Sabit dev filkulağı yaprağı & sap
        pRect(fxHome - 5, fBaseY - 7, 3, 7, '#15803d');
        pRect(fxHome - 12, leafY, 24, 3, '#166534');
        pRect(fxHome - 11, leafY - 1, 21, 2, '#15803d');
        pRect(fxHome - 9, leafY - 1, 16, 1, '#22c55e');

        const frogReact = getAmbientReaction('rainforest_frog', time);
        let fJumpX = 0;
        let fJumpY = 0;
        let reactTongue = false;
        if (frogReact) {
            const fp = frogReact.progress;
            if (fp < 0.46) {
                const u = fp / 0.46;
                fJumpX = Math.round(Math.sin(u * Math.PI * 0.5) * 20);
                fJumpY = -Math.round(Math.sin(u * Math.PI) * 16);
                reactTongue = u >= 0.72;
            } else if (fp < 0.58) {
                fJumpX = 20;
                reactTongue = fp < 0.52;
            } else {
                const u = (fp - 0.58) / 0.42;
                fJumpX = Math.round((1 - u) * 20);
                fJumpY = -Math.round(Math.sin(u * Math.PI) * 14);
            }
        }

        const fx = fxHome + fJumpX;
        const fy = leafY + fJumpY;
        const frogPhase = (time % 15000) / 15000;
        const idleBreath = Math.sin(time * 0.0022) > 0.3 ? 1 : 0;
        const isCroaking = !frogReact && (frogPhase >= 0.58 && frogPhase < 0.78)
            && Math.sin((frogPhase - 0.58) * Math.PI * 12) > 0;
        const tongueFlick = reactTongue || (!frogReact && frogPhase >= 0.82 && frogPhase < 0.86);
        const frogBlink = !frogReact && (time % 4800) > 4640;

        // Turuncu ayaklar (sıçrarken uzanır), zümrüt gövde & safir/altın yan şerit
        if (fJumpY < -3) {
            pRect(fx - 11, fy - 1, 6, 3, '#16a34a');
            pRect(fx - 13, fy + 1, 5, 2, '#f97316');
        } else {
            pRect(fx - 8, fy - 3, 5, 2, '#f97316');
        }
        pRect(fx + 3, fy - 2, 6, 1, '#fb923c');
        pRect(fx - 8, fy - 9, 14, 7, '#16a34a');
        pRect(fx - 6, fy - 10, 10, 4, '#22c55e');
        pRect(fx - 3, fy - 10, 5, 1, '#84cc16');
        pRect(fx - 3, fy - 6, 7, 2, '#2563eb');
        pRect(fx - 1, fy - 5, 4, 1, '#facc15');

        const sacDrop = isCroaking ? 3 : idleBreath;
        pRect(fx + 5, fy - 6, 6, 3 + sacDrop, '#fef3c7');
        pRect(fx + 6, fy - 5 + sacDrop, 4, 1, '#fde68a');

        // Büyük yakut gözler (5x4px)
        pRect(fx + 3, fy - 13, 5, 4, frogBlink ? '#15803d' : '#dc2626');
        pRect(fx + 4, fy - 13, 4, 3, frogBlink ? '#16a34a' : '#ef4444');
        if (!frogBlink) {
            pRect(fx + 6, fy - 12, 1, 2, '#090d16');
            pRect(fx + 4, fy - 13, 1, 1, '#fee2e2');
        }

        if (!tongueFlick && (frogReact || frogPhase < 0.86)) {
            const gnatX = fxHome + 16 + Math.round(Math.sin(time * 0.0028) * 2);
            const gnatY = leafY - 10 + Math.round(Math.cos(time * 0.0036) * 2);
            pRect(gnatX, gnatY, 2, 2, '#fde047');
            pRect(gnatX + 1, gnatY - 1, 1, 1, '#fef9c3');
        } else if (tongueFlick) {
            const tLen = frogReact ? 11 : 8;
            pRect(fx + 9, fy - 7, tLen, 2, '#fb7185');
            pRect(fx + 8 + tLen, fy - 8, 2, 2, '#fda4af');
        }

        registerAmbientHitbox('rainforest_frog', fx - 12, fy - 14, fx + 14, fBaseY + 2, 3);

        // 4. Büyütülmüş Mavi Morpho Kelebeği (~22x17px, tıklayınca parıltılı havalanıp tur atar & çiçeğe döner!)
        const mxHome = Math.min(pw - 150, Math.max(Math.round(pw * 0.66), wfX + poolHalfW + 24));
        const mBaseY = getGroundY(mxHome, 'rainforest', pw, ph);
        const flowerY = mBaseY - 19;

        // Sabit büyük tropik yapraklar & kırmızı-altın Helikonya meşalesi
        pRect(mxHome - 1, flowerY + 4, 2, 15, '#15803d');
        pRect(mxHome - 7, flowerY + 11, 6, 3, '#166534');
        pRect(mxHome + 2, flowerY + 9, 7, 3, '#15803d');
        pRect(mxHome - 5, flowerY + 2, 11, 3, '#be123c');
        pRect(mxHome - 7, flowerY, 15, 3, '#e11d48');
        pRect(mxHome - 4, flowerY - 2, 9, 3, '#fb7185');
        pRect(mxHome - 3, flowerY - 2, 7, 2, '#facc15');
        pRect(mxHome, flowerY - 3, 2, 1, '#fef08a');

        const morphoReact = getAmbientReaction('rainforest_morpho', time);
        let mx = mxHome;
        let my = flowerY;
        let isFlying = false;
        if (morphoReact) {
            const mp = morphoReact.progress;
            mx = mxHome + Math.round(Math.sin(mp * Math.PI * 2) * 15);
            my = flowerY - Math.round(Math.sin(mp * Math.PI) * 22);
            isFlying = true;
            pRect(mx - 4, my + 2, 2, 2, 'rgba(125, 211, 252, 0.72)');
            pRect(mx + 4, my + 4, 1, 1, '#fde047');
        }

        const morphoPhase = (time % 16000) / 16000;
        const antBob = Math.sin(time * 0.002) > 0.5 ? -1 : 0;

        pRect(mx, my - 7, 2, 6, '#090d16');
        pRect(mx - 1, my - 9 + antBob, 1, 2, '#334155');
        pRect(mx + 2, my - 9 + antBob, 1, 2, '#334155');

        if (isFlying) {
            const flapOpen = Math.sin(morphoReact.progress * Math.PI * 18) > 0;
            if (flapOpen) {
                pRect(mx - 11, my - 15, 11, 10, '#090d16');
                pRect(mx + 2, my - 15, 11, 10, '#090d16');
                pRect(mx - 10, my - 14, 10, 8, '#1d4ed8');
                pRect(mx + 2, my - 14, 10, 8, '#1d4ed8');
                pRect(mx - 8, my - 12, 7, 5, '#0284c7');
                pRect(mx + 3, my - 12, 7, 5, '#0284c7');
                pRect(mx - 6, my - 12, 5, 4, '#38bdf8');
                pRect(mx + 3, my - 12, 5, 4, '#38bdf8');
                pRect(mx - 4, my - 11, 3, 2, '#7dd3fc');
                pRect(mx + 3, my - 11, 3, 2, '#7dd3fc');
                pRect(mx - 11, my - 12, 1, 1, '#e0f2fe');
                pRect(mx + 12, my - 12, 1, 1, '#e0f2fe');
            } else {
                pRect(mx - 6, my - 14, 6, 9, '#0f172a');
                pRect(mx + 2, my - 14, 6, 9, '#0f172a');
                pRect(mx - 5, my - 13, 5, 7, '#2563eb');
                pRect(mx + 2, my - 13, 5, 7, '#2563eb');
                pRect(mx - 4, my - 12, 3, 4, '#38bdf8');
                pRect(mx + 3, my - 12, 3, 4, '#38bdf8');
            }
        } else if (morphoPhase < 0.48) {
            pRect(mx - 3, my - 14, 7, 9, '#451a03');
            pRect(mx - 2, my - 13, 6, 7, '#78350f');
            pRect(mx, my - 11, 3, 3, '#d97706');
            pRect(mx, my - 7, 2, 1, '#0284c7');
        } else if (morphoPhase < 0.58 || morphoPhase >= 0.88) {
            pRect(mx - 7, my - 14, 7, 9, '#0f172a');
            pRect(mx + 2, my - 14, 7, 9, '#0f172a');
            pRect(mx - 6, my - 13, 6, 7, '#1d4ed8');
            pRect(mx + 2, my - 13, 6, 7, '#1d4ed8');
            pRect(mx - 4, my - 11, 3, 4, '#38bdf8');
            pRect(mx + 3, my - 11, 3, 4, '#38bdf8');
        } else {
            pRect(mx - 11, my - 15, 11, 10, '#090d16');
            pRect(mx + 2, my - 15, 11, 10, '#090d16');
            pRect(mx - 10, my - 14, 10, 8, '#1d4ed8');
            pRect(mx + 2, my - 14, 10, 8, '#1d4ed8');
            pRect(mx - 8, my - 12, 7, 5, '#0284c7');
            pRect(mx + 3, my - 12, 7, 5, '#0284c7');
            pRect(mx - 6, my - 12, 5, 4, '#38bdf8');
            pRect(mx + 3, my - 12, 5, 4, '#38bdf8');
            pRect(mx - 4, my - 11, 3, 2, '#7dd3fc');
            pRect(mx + 3, my - 11, 3, 2, '#7dd3fc');
            pRect(mx - 11, my - 12, 1, 1, '#e0f2fe');
            pRect(mx + 12, my - 12, 1, 1, '#e0f2fe');
        }

        registerAmbientHitbox('rainforest_morpho', mx - 13, my - 17, mx + 14, my + 4, 3);
        drawAmbientTouchPulses(time);

        setSceneFill(isLightMode ? 'rgba(209, 250, 229, 0.045)' : 'rgba(45, 212, 191, 0.032)');
        for (let wisp = 0; wisp < 10; wisp++) {
            const drift = (time * (0.0018 + (wisp % 3) * 0.0005)) % (pw + 48);
            const x = (wisp * 79 + drift) % pw;
            const y = ph * (0.44 + (wisp % 4) * 0.07) + Math.sin(time * 0.0007 + wisp) * 2;
            ctx.fillRect(Math.round(x), Math.round(y), 14 + (wisp % 3) * 5, 2);
        }

        for (let sp = 0; sp < 6; sp++) {
            const sxSp = Math.round(((sp * 83 + Math.sin(time * 0.0011 + sp) * 14) % (pw - 32)) + 16);
            const sySp = Math.round(ph * 0.48 + (sp * 17) % Math.floor(ph * 0.38) + Math.cos(time * 0.0016 + sp) * 6);
            const alpha = (0.28 + 0.35 * (0.5 + 0.5 * Math.sin(time * 0.004 + sp * 1.7))).toFixed(2);
            pRect(sxSp, sySp, 1, 1, sp % 2 === 0 ? `rgba(110, 231, 183, ${alpha})` : `rgba(253, 224, 71, ${alpha})`);
        }
    }
    

    drawHabitatFlora(time, hab);
    drawHabitatAmbientWildlife(hab.sceneProfile, time);
    if (hab.sceneProfile === 'arctic-tundra' && isArcticChristmasEnabled()) {
        drawArcticChristmasGround(time);
    }

    if (hab.sceneProfile === 'koi-pond') {
        for (let idx = 0; idx < ambientParticles.length; idx++) {
            const pt = ambientParticles[idx];
            pt.y += pt.speed * 0.65 * frameScale;
            pt.x += Math.sin(time * 0.0015 + pt.phase) * 0.25 * frameScale;
            if (pt.y > ph) { pt.y = 0; pt.x = Math.random() * pw; }
            const leafCol = idx % 3 === 0 ? 'rgba(239, 68, 68, 0.78)' : 'rgba(251, 207, 232, 0.72)';
            pRect(pt.x, pt.y, 2, 1, leafCol);
        }
    } else if (ambientParticles.length > 0) {
        setSceneFill(`rgb(${hab.rgb[0]},${hab.rgb[1]},${hab.rgb[2]})`);
        for (let idx = 0; idx < ambientParticles.length; idx++) {
            const pt = ambientParticles[idx];
            pt.y -= pt.speed * frameScale;
            pt.x += Math.sin(time * 0.002 + pt.phase) * 0.12 * frameScale;
            if (pt.y < 0) { pt.y = ph; pt.x = Math.random() * pw; }
            const alpha = Math.max(0.02, 0.25 + 0.35 * Math.sin(time * 0.004 + pt.phase));
            ctx.globalAlpha = alpha;
            const ps = Math.round(pt.size);
            ctx.fillRect(Math.round(pt.x), Math.round(pt.y), ps, ps);
        }
        ctx.globalAlpha = 1;
    }

    drawHabitatStimuli();
}

