// BÖLÜM SONU: ANİMASYONLU SAHNE ÇİZİMİ
// ============================================================================


// ============================================================================
// MODULE: js/performance-monitor.js
// ============================================================================
const params = new URLSearchParams(globalThis.location?.search || '');
const enabled = params.get('debug') === 'perf';
let hud = null;
let sampleStart = 0;
let frameCount = 0;
let renderTotal = 0;
let glassTotal = 0;
let slowFrames = 0;

function ensureHud() {
  if (!enabled || hud || typeof document === 'undefined') return;
  hud = document.createElement('output');
  hud.id = 'dioramaPerfHud';
  hud.setAttribute('aria-live', 'off');
  hud.style.cssText = 'position:fixed;z-index:9999;left:8px;bottom:8px;padding:7px 9px;border:1px solid rgba(255,255,255,.2);border-radius:9px;background:rgba(0,0,0,.72);color:#fff;font:11px/1.45 ui-monospace,monospace;pointer-events:none;white-space:pre;backdrop-filter:blur(8px)';
  document.body.appendChild(hud);
}

function recordRenderFrame(now, renderMs, glassMs = 0) {
  if (!enabled) return;
  ensureHud();
  frameCount++;
  renderTotal += Math.max(0, renderMs);
  glassTotal += Math.max(0, glassMs);
  if (renderMs > 20) slowFrames++;
  if (!sampleStart) sampleStart = now;
  if (now - sampleStart < 1000) return;
  const seconds = (now - sampleStart) / 1000;
  const fps = frameCount / seconds;
  const averageRender = renderTotal / frameCount;
  const averageGlass = glassTotal / frameCount;
  const memory = performance.memory?.usedJSHeapSize;
  const memoryText = Number.isFinite(memory) ? `\nHeap ${(memory / 1048576).toFixed(1)} MB` : '';
  hud.textContent = `Diorama PERF\nFPS ${fps.toFixed(1)}\nRender ${averageRender.toFixed(1)} ms\nGlass avg ${averageGlass.toFixed(1)} ms\nSlow frames ${slowFrames}${memoryText}`;
  sampleStart = now;
  frameCount = 0;
  renderTotal = 0;
  glassTotal = 0;
  slowFrames = 0;
}


// ============================================================================
// MODULE: js/habitat-flora-generator.js
// ============================================================================



/* HABITAT FLORA GENERATOR — creates habitat-specific plant and scenery data. */

// ============================================================================
// BÖLÜM BAŞI: BİYOMA GÖRE FLORA YERLEŞİMİ
// Yalnızca bitki verisini üretir; çizim davranışı habitat-flora-renderer.js içindedir.
// ============================================================================

function canPlaceLily(placedLilies, lx, ly, r, padMarginX = 7, padMarginY = 5) {
    for (let i = 0; i < placedLilies.length; i++) {
        const p = placedLilies[i];
        if (
            Math.abs(lx - p.x) < (r + p.r + padMarginX) &&
            Math.abs(ly - p.y) < (Math.ceil((r + p.r) * 0.6) + padMarginY)
        ) {
            return false;
        }
    }
    return true;
}

function populateHabitatFlora(hab) {
if (hab.sceneProfile === 'meadow') {
        // BÖLÜM BAŞI: ÇAYIR BAŞLANGIÇ FLORASI
        const stonePositions = [0.11, 0.28, 0.47, 0.63, 0.75, 0.93];
        stonePositions.forEach((pos, idx) => {
            const sx = Math.round(pw * pos + (Math.random() - 0.5) * 8);
            const sgy = getGroundY(sx, 'meadow', pw, ph);
            flora.push({
                type: 'meadow_stone',
                x: sx,
                baseY: sgy + 1,
                rx: 4 + (idx % 3) * 2,
                ry: 2 + (idx % 2),
                hasMoss: idx % 2 === 0
            });
        });

        for (let tx = 8; tx < pw - 8; tx += 5 + Math.floor(Math.random() * 4)) {
            const tnx = tx / Math.max(1, pw);
            if (tnx > 0.79 && tnx < 0.89) continue;
            const tgy = getGroundY(tx, 'meadow', pw, ph);
            flora.push({
                type: 'meadow_tuft',
                x: tx,
                baseY: tgy + 1,
                h: 5 + Math.floor(Math.random() * 7),
                hasClover: Math.random() < 0.35,
                cloverCol: Math.random() < 0.55 ? '#f8fafc' : '#f9a8d4',
                phase: Math.random() * Math.PI * 2
            });
        }

        for (let x = 12; x < pw - 12; x += 6 + Math.floor(Math.random() * 4)) {
            const nx = x / Math.max(1, pw);
            if (nx > 0.78 && nx < 0.90) continue;
            if (Math.abs(x - Math.max(Math.round(pw * 0.27), 146)) < 24) continue;

            const baseY = getGroundY(x, 'meadow', pw, ph) + Math.round((Math.random() - 0.5) * 2);
            const r = Math.random();

            if (r < 0.18 && (nx > 0.25 && nx < 0.44 || nx > 0.64 && nx < 0.77)) {
                flora.push({
                    type: 'sunflower',
                    x,
                    baseY,
                    h: 32 + Math.random() * 22,
                    headR: 4 + Math.floor(Math.random() * 2),
                    phase: Math.random() * Math.PI * 2
                });
            } else if (r < 0.38) {
                flora.push({
                    type: 'foxglove',
                    x,
                    baseY,
                    h: 24 + Math.random() * 20,
                    hue: Math.random() < 0.5 ? '#c084fc' : '#f472b6',
                    phase: Math.random() * Math.PI * 2
                });
            } else {
                flora.push({
                    type: 'meadow',
                    x,
                    baseY,
                    h: 14 + Math.random() * 20,
                    hasBloom: Math.random() < 0.82,
                    kind: ['lavender', 'daisy', 'poppy', 'buttercup', 'echinacea'][Math.floor(Math.random() * 5)],
                    phase: Math.random() * Math.PI * 2
                });
            }
        }

        // BÖLÜM SONU: ÇAYIR BAŞLANGIÇ FLORASI
   } else if (hab.sceneProfile === 'betta-aquarium') {
        // BÖLÜM BAŞI: BETTA AKVARYUMU BAŞLANGIÇ FLORASI
        const soilY = (x) => {
            const nx = x / Math.max(1, pw);
            if (Math.abs(nx - 0.50) < 0.085) {
                return ph - 5 - Math.round(Math.cos((nx - 0.50) * 18) * 2);
            }
            const mound = Math.pow(Math.abs(nx - 0.50) * 1.95, 1.45) * 18;
            return Math.round(ph - 4 - mound - Math.sin(x * 0.04) * 2);
        };

        for (let cx = 10; cx < pw - 10; cx += 6 + Math.floor(Math.random() * 4)) {
            const cnx = cx / Math.max(1, pw);
            if (Math.abs(cnx - 0.50) < 0.095) continue;
            flora.push({
                type: 'carpet_tuft',
                x: cx,
                baseY: soilY(cx) + 1,
                w: 3 + Math.floor(Math.random() * 3),
                h: 3 + Math.floor(Math.random() * 3),
                phase: Math.random() * Math.PI * 2
            });
        }

        for (let x = 10; x < pw - 10; x += 8 + Math.floor(Math.random() * 5)) {
            const nx = x / Math.max(1, pw);
            const inCenterPath = nx > 0.41 && nx < 0.59;
            if (inCenterPath) continue;
            if (Math.abs(x - Math.min(Math.round(pw * 0.69), pw - 142)) < 22) continue;

            const baseY = soilY(x) + 1;
            const moundScale = 0.72 + Math.pow(Math.abs(nx - 0.5) * 1.9, 1.2) * 0.52;
            const kindRoll = Math.random();

            if (kindRoll < 0.34) {
                flora.push({
                    type: 'hornwort',
                    x,
                    baseY,
                    h: (42 + Math.random() * 52) * moundScale,
                    whorlSpan: 4 + Math.floor(Math.random() * 3),
                    glowCol: Math.random() < 0.5 ? '#34d399' : '#2dd4bf',
                    phase: Math.random() * Math.PI * 2
                });
            } else if (kindRoll < 0.62) {
                flora.push({
                    type: 'ludwigia',
                    x,
                    baseY,
                    h: (32 + Math.random() * 44) * moundScale,
                    phase: Math.random() * Math.PI * 2
                });
            } else if (kindRoll < 0.84) {
                flora.push({
                    type: 'val',
                    x,
                    baseY,
                    h: (36 + Math.random() * 48) * moundScale,
                    phase: Math.random() * Math.PI * 2
                });
            } else {
                flora.push({
                    type: 'amazon_sword',
                    x,
                    baseY,
                    h: (28 + Math.random() * 30) * moundScale,
                    phase: Math.random() * Math.PI * 2
                });
            }
        }
        for (let fx = 44; fx < pw - 14; fx += 18 + Math.floor(Math.random() * 14)) {
            flora.push({
                type: 'pistia',
                x: fx,
                rootLen: 12 + Math.random() * 18,
                phase: Math.random() * Math.PI * 2
            });
        }
        for (let i = 0; i < 48; i++) {
            const px = 8 + Math.random() * (pw - 16);
            const nx = px / Math.max(1, pw);
            const inSand = Math.abs(nx - 0.50) < 0.085;
            const py = soilY(px) + Math.floor(Math.random() * 3);
            flora.push({
                type: 'pebble',
                x: px,
                y: py,
                w: 2 + Math.floor(Math.random() * 4),
                h: 1 + Math.floor(Math.random() * 2),
                shade: inSand ? ['#94a3b8', '#64748b'][i % 2] : ['#0f293a', '#16384c', '#1e4959', '#091d2b'][i % 4]
            });
        }

        // BÖLÜM SONU: BETTA AKVARYUMU BAŞLANGIÇ FLORASI
        
    } else if (hab.sceneProfile === 'wetland') {
        // BÖLÜM BAŞI: SULAK ALAN BAŞLANGIÇ FLORASI
        const reach = Math.min(145, Math.round(pw * 0.26));
        const willowZones = [
            { startX: 6, endX: reach - 4, isLeft: true },
            { startX: pw - reach + 4, endX: pw - 6, isLeft: false }
        ];
        willowZones.forEach(zone => {
            for (let x = zone.startX; x <= zone.endX; x += 5 + Math.floor(Math.random() * 4)) {
                const t = zone.isLeft ? (x / reach) : ((pw - x) / reach);
                const branchY = Math.round(6 + Math.pow(t, 1.2) * 14 + Math.sin(x * 0.08) * 1.5);
                const len = Math.round((1 - t * 0.55) * 48 + 14 + Math.random() * 14);
                flora.push({
                    type: 'willow_frond',
                    x: Math.round(x),
                    startY: branchY,
                    len,
                    phase: Math.random() * Math.PI * 2
                });
            }
        });

        for (let x = 6; x < pw - 6; x += 6 + Math.floor(Math.random() * 5)) {
            const nx = x / Math.max(1, pw);
            const inLeftBank = nx < 0.34;
            const inRightBank = nx > 0.66;
            const inMidIsland = (nx > 0.41 && nx < 0.48) || (nx > 0.55 && nx < 0.61);

            if (!inLeftBank && !inRightBank && !inMidIsland) continue;
            if (x > 10 && x < 64) continue;
            if (Math.abs(x - (pw - 74)) < 16) continue;

            const baseY = inMidIsland
                ? Math.round(ph - 22 + Math.sin(x * 0.2) * 2)
                : getGroundY(x, 'wetland', pw, ph) + Math.round((Math.random() - 0.5) * 3);

            const edgeScale = (nx < 0.16 || nx > 0.84) ? 1.22 : (inMidIsland ? 0.78 : 1.0);
            const r = Math.random();

            if (r < 0.42) {
                const h = Math.round((46 + Math.random() * 56) * edgeScale);
                flora.push({
                    type: 'reed',
                    x,
                    baseY,
                    h,
                    hasCat: Math.random() < 0.78,
                    tilt: (Math.random() - 0.5) * 0.10,
                    phase: Math.random() * Math.PI * 2
                });
            } else if (r < 0.65) {
                flora.push({
                    type: 'iris',
                    x,
                    baseY,
                    h: Math.round((30 + Math.random() * 32) * edgeScale),
                    col: Math.random() < 0.6 ? '#facc15' : '#c084fc',
                    phase: Math.random() * Math.PI * 2
                });
            } else if (r < 0.82) {
                flora.push({
                    type: 'loosestrife',
                    x,
                    baseY,
                    h: Math.round((32 + Math.random() * 34) * edgeScale),
                    hue: Math.random() < 0.5 ? '#e879f9' : '#f472b6',
                    phase: Math.random() * Math.PI * 2
                });
            } else {
                flora.push({
                    type: 'papyrus',
                    x,
                    baseY,
                    h: Math.round((34 + Math.random() * 38) * edgeScale),
                    phase: Math.random() * Math.PI * 2
                });
            }
        }

        const placedLilies = [];
        const isWetlandWaterClear = (lx, ly, r) => {
            if (lx < 68 || lx > pw - 68 || Math.abs(lx - (pw - 74)) < 18) return false;
            const ry = Math.ceil(r * 0.55);
            // Avoid overlapping mid-water mossy islands or right bank snag
            if (Math.abs(lx - Math.round(pw * 0.44)) < 25 + r && Math.abs(ly - (ph - 21)) < 9 + ry) return false;
            if (Math.abs(lx - Math.round(pw * 0.58)) < 22 + r && Math.abs(ly - (ph - 25)) < 8 + ry) return false;
            if (Math.abs(lx - Math.round(pw * 0.66)) < 18 + r && ly > ph - 26) return false;
            const nx = lx / Math.max(1, pw);
            if ((nx <= 0.37 || nx >= 0.63) && ly > getGroundY(lx, 'wetland', pw, ph) - ry - 4) return false;
            return true;
        };

        const wetlandLilyZones = [
            { xStart: 0.18, xEnd: 0.37, minY: ph - 45, maxYFn: (lx, r) => Math.min(ph - 16, getGroundY(lx, 'wetland', pw, ph) - Math.ceil(r * 0.55) - 5), target: 3, minR: 4, maxR: 6 },
            { xStart: 0.49, xEnd: 0.54, minY: ph - 45, maxYFn: () => ph - 30, target: 1, minR: 4, maxR: 5 },
            { xStart: 0.38, xEnd: 0.62, minY: ph - 14, maxYFn: () => ph - 6, target: 3, minR: 6, maxR: 8 },
            { xStart: 0.64, xEnd: 0.80, minY: ph - 45, maxYFn: (lx, r) => Math.min(ph - 20, getGroundY(lx, 'wetland', pw, ph) - Math.ceil(r * 0.55) - 6), target: 3, minR: 4, maxR: 6 }
        ];

        wetlandLilyZones.forEach(zone => {
            let count = 0;
            for (let attempt = 0; attempt < 32 && count < zone.target; attempt++) {
                const r = zone.minR + Math.floor(Math.random() * (zone.maxR - zone.minR + 1));
                const lx = Math.round(pw * (zone.xStart + Math.random() * (zone.xEnd - zone.xStart)));
                const maxY = zone.maxYFn(lx, r);
                if (zone.minY >= maxY - 1) continue;
                const ly = Math.round(zone.minY + Math.random() * (maxY - zone.minY));
                if (!isWetlandWaterClear(lx, ly, r)) continue;
                if (!canPlaceLily(placedLilies, lx, ly, r, 7, 5)) continue;
                placedLilies.push({ x: lx, y: ly, r });
                count++;
            }
        });

        placedLilies.sort((a, b) => a.y - b.y);
        placedLilies.forEach((pad, idx) => {
            flora.push({
                type: 'lily',
                x: pad.x,
                y: pad.y,
                r: pad.r,
                notchDir: idx % 2 === 0 ? 1 : -1,
                flower: idx % 2 === 0,
                flowerCol: ['#fde047', '#f472b6', '#f8fafc'][idx % 3],
                phase: Math.random() * Math.PI * 2
            });
        });

        // BÖLÜM SONU: SULAK ALAN BAŞLANGIÇ FLORASI
        
   } else if (hab.sceneProfile === 'botanical') {
        // BÖLÜM BAŞI: BOTANİK BAHÇE BAŞLANGIÇ FLORASI
        const reach = Math.min(155, Math.round(pw * 0.30));
        const boughZones = [
            { startX: 6, endX: reach - 4, isLeft: true },
            { startX: pw - reach + 4, endX: pw - 6, isLeft: false }
        ];
        boughZones.forEach(zone => {
            for (let x = zone.startX; x <= zone.endX; x += 6 + Math.floor(Math.random() * 4)) {
                const t = zone.isLeft ? (x / reach) : ((pw - x) / reach);
                const branchY = Math.round(5 + Math.pow(t, 1.2) * 15 + Math.sin(x * 0.09) * 1.5);
                const len = Math.round((1 - t * 0.52) * 34 + 12 + Math.random() * 14);
                flora.push({
                    type: 'wisteria_cluster',
                    x: Math.round(x),
                    branchY,
                    len,
                    hue: ['#c084fc', '#e879f9', '#f472b6', '#818cf8'][Math.floor(Math.random() * 4)],
                    phase: Math.random() * Math.PI * 2
                });
            }
        });

        const fountainX = Math.round(pw * 0.18);
        const archLeftPillarX = pw - 65;
        const archRightPillarX = pw - 37;

        for (let x = 10; x < pw - 10; x += 7 + Math.floor(Math.random() * 5)) {
            const nx = x / Math.max(1, pw);
            if (Math.abs(nx - 0.5) < 0.06 && Math.random() < 0.72) continue;
            if (Math.abs(x - Math.min(Math.round(pw * 0.68), pw - 142)) < 20) continue;
            if (Math.abs(x - fountainX) < 16) continue;
            if (Math.abs(x - archLeftPillarX) < 5 || Math.abs(x - archRightPillarX) < 5) continue;

            const baseY = getGroundY(x, 'botanical', pw, ph) + Math.round((Math.random() - 0.5) * 2);
            const r = Math.random();

            if (r < 0.25 && (nx < 0.42 || nx > 0.58)) {
                flora.push({
                    type: 'buddleia',
                    x,
                    baseY,
                    h: 28 + Math.random() * 26,
                    hue: ['#c084fc', '#e879f9', '#f472b6', '#facc15'][Math.floor(Math.random() * 4)],
                    tilt: (nx < 0.5 ? 1 : -1) * (0.12 + Math.random() * 0.14),
                    phase: Math.random() * Math.PI * 2
                });
            } else if (r < 0.44 && (nx < 0.36 || nx > 0.64)) {
                flora.push({
                    type: 'hydrangea',
                    x,
                    baseY,
                    r: 6 + Math.floor(Math.random() * 4),
                    hue: ['#60a5fa', '#c084fc', '#f472b6'][Math.floor(Math.random() * 3)],
                    phase: Math.random() * Math.PI * 2
                });
            } else if (r < 0.62) {
                flora.push({
                    type: 'fern',
                    x,
                    baseY,
                    h: 15 + Math.random() * 18,
                    dir: Math.random() < 0.5 ? 1 : -1,
                    phase: Math.random() * Math.PI * 2
                });
            } else if (r < 0.78) {
                flora.push({
                    type: 'glow_mushroom',
                    x,
                    baseY,
                    h: 8 + Math.random() * 11,
                    capR: 3 + Math.floor(Math.random() * 3),
                    col: Math.random() < 0.5 ? '#38bdf8' : '#a855f7',
                    phase: Math.random() * Math.PI * 2
                });
            } else if (r < 0.90) {
                flora.push({
                    type: 'foxglove',
                    x,
                    baseY,
                    h: 24 + Math.random() * 24,
                    hue: Math.random() < 0.5 ? '#e879f9' : '#60a5fa',
                    phase: Math.random() * Math.PI * 2
                });
            } else {
                flora.push({
                    type: 'meadow',
                    x,
                    baseY,
                    h: 16 + Math.random() * 22,
                    hasBloom: true,
                    kind: 'nightbloom',
                    phase: Math.random() * Math.PI * 2
                });
            }
        }

        // BÖLÜM SONU: BOTANİK BAHÇE BAŞLANGIÇ FLORASI
        
    } else if (hab.sceneProfile === 'reef') {
        // BÖLÜM BAŞI: MERCAN RESİFİ BAŞLANGIÇ FLORASI
        const ruinX = Math.round(pw * 0.26);
        const clamX = Math.floor(pw * 0.72);
        const rightColX = Math.round(pw * 0.76);

        for (let x = 10; x < pw - 10; x += 9 + Math.floor(Math.random() * 6)) {
            if (Math.abs(x - clamX) < 14) continue;
            if (Math.abs(x - (ruinX - 11)) < 7 || Math.abs(x - (ruinX + 19)) < 7 || Math.abs(x - (rightColX + 4)) < 7) continue;

            const nx = x / Math.max(1, pw);
            const sideMound = nx < 0.26 ? Math.pow((0.26 - nx) / 0.26, 1.5) * 34
                            : (nx > 0.74 ? Math.pow((nx - 0.74) / 0.26, 1.5) * 34 : 0);
            const baseY = Math.round(getGroundY(x, 'reef', pw, ph) - sideMound);
            const r = Math.random();
            const hue = [285, 325, 190, 165, 45][Math.floor(Math.random() * 5)];

            if ((nx < 0.24 || nx > 0.76) && r < 0.38) {
                flora.push({
                    type: 'kelp',
                    x,
                    baseY,
                    h: 48 + Math.random() * 54,
                    phase: Math.random() * Math.PI * 2
                });
            } else if (r < 0.25) {
                flora.push({
                    type: 'staghorn_coral',
                    x,
                    baseY,
                    h: 16 + Math.random() * 18,
                    hue,
                    phase: Math.random() * Math.PI * 2
                });
            } else if (r < 0.45) {
                flora.push({
                    type: 'brain_coral',
                    x,
                    baseY,
                    r: 6 + Math.floor(Math.random() * 5),
                    hue,
                    phase: Math.random() * Math.PI * 2
                });
            } else if (r < 0.65) {
                flora.push({
                    type: 'tube_sponge',
                    x,
                    baseY,
                    h: 15 + Math.random() * 20,
                    hue,
                    phase: Math.random() * Math.PI * 2
                });
            } else if (r < 0.82) {
                flora.push({
                    type: 'anemone',
                    x,
                    baseY,
                    h: 14 + Math.random() * 12,
                    hue,
                    phase: Math.random() * Math.PI * 2
                });
            } else {
                flora.push({
                    type: 'sea_fan',
                    x,
                    baseY,
                    h: 22 + Math.random() * 26,
                    hue,
                    phase: Math.random() * Math.PI * 2
                });
            }
        }

        // BÖLÜM SONU: MERCAN RESİFİ BAŞLANGIÇ FLORASI
        
    } else if (hab.sceneProfile === 'koi-pond') {
        // BÖLÜM BAŞI: KOİ GÖLETİ BAŞLANGIÇ FLORASI
        const mapleReach = Math.min(150, Math.round(pw * 0.30));
        for (let x = 8; x <= mapleReach - 4; x += 6 + Math.floor(Math.random() * 4)) {
            const t = x / mapleReach;
            const branchY = Math.round(6 + Math.pow(t, 1.2) * 14 + Math.sin(x * 0.09) * 1.5);
            const len = Math.round((1 - t * 0.55) * 26 + 8 + Math.random() * 10);
            flora.push({
                type: 'maple_bough',
                x: Math.round(x),
                branchY,
                len,
                col: ['#ef4444', '#dc2626', '#f97316', '#fb7185'][Math.floor(Math.random() * 4)],
                phase: Math.random() * Math.PI * 2
            });
        }

        const bambooStart = Math.max(pw - 86, Math.round(pw * 0.78));
        for (let x = bambooStart; x < pw - 6; x += 7 + Math.floor(Math.random() * 4)) {
            const baseY = getGroundY(x, 'koi-pond', pw, ph) - 2;
            flora.push({
                type: 'bamboo_stalk',
                x,
                baseY,
                h: Math.round(ph * 0.58 + Math.random() * (ph * 0.32)),
                lean: (Math.random() - 0.55) * 0.06,
                phase: Math.random() * Math.PI * 2
            });
        }

        for (let x = 10; x < pw * 0.28; x += 8 + Math.floor(Math.random() * 6)) {
            const baseY = getGroundY(x, 'koi-pond', pw, ph) - 1;
            if (Math.random() < 0.55) {
                flora.push({
                    type: 'iris',
                    x,
                    baseY,
                    h: 20 + Math.random() * 20,
                    col: Math.random() < 0.65 ? '#c084fc' : '#facc15',
                    phase: Math.random() * Math.PI * 2
                });
            } else {
                flora.push({
                    type: 'papyrus',
                    x,
                    baseY,
                    h: 22 + Math.random() * 24,
                    phase: Math.random() * Math.PI * 2
                });
            }
        }

        for (let i = 0; i < 36; i++) {
            flora.push({
                type: 'pebble',
                x: 20 + Math.random() * (pw - 40),
                y: 36 + Math.random() * (ph - 48),
                w: 3 + Math.floor(Math.random() * 5),
                h: 2 + Math.floor(Math.random() * 3),
                shade: ['#0c2536', '#123347', '#194158', '#081b29'][i % 4]
            });
        }

        const placedKoiLilies = [];
        for (let i = 0; i < 12; i++) {
            for (let attempt = 0; attempt < 30; attempt++) {
                const r = 6 + Math.floor(Math.random() * 5);
                const ry = Math.ceil(r * 0.55);
                const minX = 32 + r;
                const maxX = Math.max(minX + 4, pw - 82 - r);
                const minY = 34 + ry;
                const maxY = Math.max(minY + 4, ph - 12 - ry);
                const lx = Math.round(minX + Math.random() * (maxX - minX));
                const ly = Math.round(minY + Math.random() * (maxY - minY));
                if (lx < 82 && ly > ph - 22 - r) continue;
                const nx = lx / Math.max(1, pw);
                if ((nx <= 0.28 || nx >= 0.70) && ly > getGroundY(lx, 'koi-pond', pw, ph) - ry - 5) continue;
                if (!canPlaceLily(placedKoiLilies, lx, ly, r, 8, 6)) continue;
                placedKoiLilies.push({ x: lx, y: ly, r });
                break;
            }
        }
        placedKoiLilies.sort((a, b) => a.y - b.y);
        placedKoiLilies.forEach((pad, idx) => {
            flora.push({
                type: 'lily',
                x: pad.x,
                y: pad.y,
                r: pad.r,
                notchDir: idx % 2 === 0 ? 1 : -1,
                flower: idx % 2 === 0,
                flowerCol: ['#f472b6', '#f8fafc', '#fde047'][idx % 3],
                phase: Math.random() * Math.PI * 2
            });
        });

        // BÖLÜM SONU: KOİ GÖLETİ BAŞLANGIÇ FLORASI
    } else if (hab.sceneProfile === 'rainforest') {
        // BÖLÜM BAŞI: YAĞMUR ORMANI BAŞLANGIÇ FLORASI
        const cliffCenterX = Math.round(pw * 0.50);
        const lagoonClearHalfW = Math.max(30, Math.round(pw * 0.068));
        for (let x = 7; x < pw - 7; x += 7 + Math.floor(Math.random() * 8)) {
            if (Math.abs(x - cliffCenterX) < lagoonClearHalfW) continue;
            const nx = x / Math.max(1, pw);
            const inCenterValley = nx > 0.34 && nx < 0.66;
            if (inCenterValley && Math.random() < 0.18) continue;

            const roll = Math.random();
            const scaleM = inCenterValley ? 0.86 : 1.0;
            if (roll < 0.30) {
                flora.push({
                    type: 'tropical_leaf',
                    x,
                    h: (32 + Math.random() * 34) * scaleM,
                    dir: Math.random() < 0.5 ? -1 : 1,
                    hue: Math.random() < 0.5 ? '#0f766e' : '#15803d',
                    phase: Math.random() * Math.PI * 2
                });
            } else if (roll < 0.52) {
                flora.push({
                    type: 'jungle_fern',
                    x,
                    h: (22 + Math.random() * 22) * scaleM,
                    dir: Math.random() < 0.5 ? -1 : 1,
                    phase: Math.random() * Math.PI * 2
                });
            } else if (roll < 0.70) {
                flora.push({
                    type: 'bromeliad',
                    x,
                    h: (18 + Math.random() * 18) * scaleM,
                    hue: Math.random() < 0.5 ? '#e11d48' : '#f97316',
                    phase: Math.random() * Math.PI * 2
                });
            } else if (roll < 0.86) {
                flora.push({
                    type: 'heliconia',
                    x,
                    h: (28 + Math.random() * 26) * scaleM,
                    dir: Math.random() < 0.5 ? -1 : 1,
                    hue: ['#e11d48', '#f97316', '#facc15'][Math.floor(Math.random() * 3)],
                    phase: Math.random() * Math.PI * 2
                });
            } else {
                flora.push({
                    type: 'orchid',
                    x,
                    h: (22 + Math.random() * 22) * scaleM,
                    hue: Math.random() < 0.5 ? '#e879f9' : '#f9a8d4',
                    phase: Math.random() * Math.PI * 2
                });
            }
        }

        // Epifitler çıplak gövde ortasında değil, yan dalların gövdeyle birleştiği gerçek dal çatallarında yetişir
        const branchForkSpecs = [
            { x: Math.floor(pw * 0.14) + 6, y: Math.floor(ph * 0.24) + 21 },
            { x: Math.floor(pw * 0.27) + 6, y: Math.floor(ph * 0.36) + 21 },
            { x: Math.floor(pw * 0.75) - 6, y: Math.floor(ph * 0.34) + 21 },
            { x: Math.floor(pw * 0.86) - 6, y: Math.floor(ph * 0.22) + 21 }
        ];
        branchForkSpecs.forEach((pt, i) => {
            flora.push({
                type: 'epiphyte',
                x: pt.x,
                y: pt.y,
                hue: ['#f472b6', '#e879f9', '#facc15'][i % 3],
                phase: i * 1.1
            });
        });

        // Tüm kanopi sarmaşıkları doğrudan üstteki taç kubbelerinin içinden sarkar; orta şelale penceresini çerçeveler
        const vineXPositions = [
            pw * 0.06, pw * 0.16, pw * 0.28, pw * 0.44, pw * 0.56,
            pw * 0.72, pw * 0.84, pw * 0.94
        ];
        vineXPositions.forEach((vx, i) => {
            flora.push({
                type: 'canopy_vine',
                x: Math.round(vx),
                startY: 6 + (i % 3) * 3,
                len: 36 + (i % 3) * 14 + (i % 4 === 0 ? 18 : 0),
                phase: i * 0.9,
                hue: i % 3 === 0 ? '#22a65a' : (i % 2 === 0 ? '#15803d' : '#0f766e')
            });
        });

        const monsteraAnchors = [
            { x: 0.06, h: 48, dir: 1 },
            { x: 0.27, h: 56, dir: -1 },
            { x: 0.73, h: 52, dir: 1 },
            { x: 0.94, h: 46, dir: -1 }
        ];
        monsteraAnchors.forEach((plant, i) => {
            flora.push({
                type: 'monstera',
                x: Math.round(pw * plant.x),
                h: plant.h + Math.random() * 8,
                dir: plant.dir,
                hue: i % 2 === 0 ? '#16804a' : '#0f6b40',
                phase: i * 1.3
            });
        });

        // BÖLÜM SONU: YAĞMUR ORMANI BAŞLANGIÇ FLORASI
        
    } else if (hab.sceneProfile === 'arctic-tundra') {
        // BÖLÜM BAŞI: KUTUP TUNDURASI BAŞLANGIÇ FLORASI
        const ledges = getArcticLedges(pw, ph);
        ledges.forEach(l => {
            for (let x = l.x1 + 8; x < l.x2 - 8; x += 12 + Math.floor(Math.random() * 10)) {
                if (l.id === 5 && x > pw * 0.68 && x < pw * 0.78) continue;
                const by = l.yFn(x);
                const r = Math.random();
                if (r < 0.48) {
                    flora.push({ type: 'cotton_grass', x, baseY: by, h: 10 + Math.random() * 10, phase: Math.random() * Math.PI * 2 });
                } else if (r < 0.78) {
                    flora.push({ type: 'arctic_crystal', x, baseY: by, h: 8 + Math.random() * 8, col: Math.random() < 0.5 ? '#38bdf8' : '#c084fc' });
                } else {
                    flora.push({ type: 'arctic_berry_bush', x, baseY: by, r: 5 + Math.floor(Math.random() * 3), phase: Math.random() * Math.PI * 2 });
                }
            }
        });
        // BÖLÜM SONU: KUTUP TUNDURASI BAŞLANGIÇ FLORASI
    }
}

// ============================================================================
// BÖLÜM SONU: BİYOMA GÖRE FLORA YERLEŞİMİ
// ============================================================================


// ============================================================================
// MODULE: js/habitat-initializer.js
// ============================================================================




/* HABITAT INITIALIZER — resets shared state and builds the selected habitat's scene data. */

// ============================================================================
// BÖLÜM BAŞI: CANLI PROFİLLERİ VE HABİTATIN İLK KURULUMU
// Ortak durumu sıfırlar, flora üreticisini çağırır ve katalogdaki canlı profilini kurar.
// ============================================================================

const CREATURE_PROFILES = Object.freeze({
    bee: { count: 8, create: () => new PixelBee() },
    betta: { count: 7, create: () => new PixelBetta() },
    dragonfly: { count: 7, create: () => new PixelDragonfly() },
    butterfly: { count: 8, create: () => new PixelButterfly() },
    jellyfish: { count: 8, create: () => new PixelJellyfish() },
    koi: { count: 7, create: () => new PixelKoi() },
    parrot: { count: 5, create: () => new PixelParrot() },
    arctic_fox: { count: 7, create: () => new PixelArcticFox() },
});

function initHabitat(idx) {
    setCurrentHabitatIndex(idx);
    const hab = HABITATS[currentHabitatIdx];

    document.getElementById('habitatNameLabel').textContent = hab.name;
    const announcement = document.getElementById('habitatAnnouncement');
    if (announcement) announcement.textContent = `Habitat değiştirildi: ${hab.name}`;
    document.getElementById('habitatFeedHint').textContent = hab.hint;
    const dot = document.getElementById('habitatDot');
    dot.style.backgroundColor = hab.dotColor;

    creatures.length = 0;
    stimuli.length = 0;
    ambientParticles.length = 0;
    flora.length = 0;
    shootingStars.length = 0;
    sceneCache.staticEnvCache = null;

    const detailTier = [1, 2, 3].includes(Number(window.__weDetailTier)) ? Number(window.__weDetailTier) : 1;
    const particleTarget = detailTier === 3 ? 85 : detailTier === 2 ? 60 : 38;
    for (let i = 0; i < particleTarget; i++) {
        ambientParticles.push({
            x: Math.random() * pw,
            y: Math.random() * ph,
            speed: 0.06 + Math.random() * 0.14,
            phase: Math.random() * Math.PI * 2,
            size: Math.random() < 0.82 ? 1 : 2
        });
    }

    populateHabitatFlora(hab);

    const creatureProfile = CREATURE_PROFILES[hab.creatureProfile];
    if (creatureProfile) {
        const bonusCreatures = detailTier === 3 ? 3 : detailTier === 2 ? 1 : 0;
        for (let i = 0; i < creatureProfile.count + bonusCreatures; i++) creatures.push(creatureProfile.create());
    }
    if (typeof window.__weOnHabitatChanged === 'function') window.__weOnHabitatChanged(hab);
}

